/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201012-4","meetingId":"r02-c-settlement","date":"2020年10月12日","dateIso":"2020-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"私からは、３２１ページ、水辺利活用事業に関連して品川区の運河沿いでの釣りについて、また３４５ページ、品川区国民保護計画変更費について質問します。そこでまずお聞きいたしますが、例えばこのような運河沿いの土手で釣りをされている、その場所の管理権は品川区にあるのでしょうか。区内で実際に釣り場として、例えばホームページだとか、そういったところで周知しているような場所はあるのでしょうか。","respondent":"鈴木都市計画課長","answer":"区内水辺での釣りの状況ですが、現在、京浜運河の八潮側、都立京浜運河緑道公園になりますが、こちらのほうは干潟の自然保護区域や桟橋以外については、区の魅力の１つである水辺に親しむことが可能な区域として、釣り可能エリアとして既にＰＲ、周知がなされ。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問・要望","question":"管理は東京都が行っており、区は委託を受けているということを理解いたしました。１人で楽しむレジャーとして、感染のリスクの少ない釣りは、これからもっと需要が伸びてくると思われます。区議会自民党でも、先般、要望させていただきましたが、ぜひとも区のほうで釣り場の確保、場所の整備を今後も図っていただきたいと思いますが、区のほうでお考えがありましたら、お願いいたします。","respondent":"鈴木都市計画課長","answer":"今ご提案いただいた釣りは、ほかのアクティビティ等を含めて、品川区の魅力発信には、あるいは区民の水辺に親しんでいただく機会としては非常に重要なところですので、今後、そうしたスポットの整備、あるいはどういった釣りの在り方があるかというのは。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問・要望","question":"続きまして、３４５ページ、国民保護計画変更費についてお伺いいたします。今年の２月にテレビや新聞などでも毎日のようにニュースにありました横浜港に停泊していたダイヤモンド・プリンセス号、豪華客船ですが、これを見た方も多かったと思います。この国民保護計画の変更されたポイントについて具体的に教えていただきたいと思います。","respondent":"大森災害対策担当課長","answer":"委員ご案内のとおり、品川区の国民保護計画につきましては、平成１９年に策定いたしまして、その後、平成２５年３月に、Ｊアラートなどのシステムの導入に伴いまして大きく変更をかけたところです。それから、直近で令和２年３月に、再度、変更をかけたところです。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"国、東京都との整合性を図るというのは分かりました。私も変更された保護計画を読みましたら、その中に品川区以外、区外からの避難民の受け入れも入っていたと思いますが、そのとおりでしょうか。","respondent":"大森災害対策担当課長","answer":"そのため、避難誘導については、基本的には国とか都の指示に基づいて区が対応することになりまして、その中の１つの選択肢として、広域避難という観点から、区内から区外への避難、もしくは区外の方からの区内への受援、こういった形の想定もあります。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"そうなりますと、やはりこの地域の方にも、例えば避難誘導だとか、そういったところで協力をいただくようなこともあるかと思いますが、これまで防災訓練の中にもそういった武力攻撃事態を想定した訓練も行われてきたのでしょうか。","respondent":"大森災害対策担当課長","answer":"国民保護に関する防災訓練に関するお尋ねです。区では、この国民保護計画の変更に先立ちまして、令和元年９月に国民保護の図上訓練を行いまして、警察、消防、自衛隊といった関係機関と連携しながら訓練をしたところです。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"私からは、３１１ページ、道路バリアフリー事業、３２７ページ、公園・児童遊園費、３４３ページ、防災関係、３４５ページ、消防団運営費、３４７ページ、避難所等備蓄品について、順不同で質問します。この大井町駅、旗の台駅周辺のバリアフリー計画の概要と進展状況を教えてください。","respondent":"鈴木都市計画課長","answer":"旗の台駅周辺地区では、心身障害者福祉会館前区道の点字ブロックの補修、旗の台公園や荏原南公園のバリアフリー化改善整備、地域センターのだれでもトイレの高機能化など、バリアフリー化に取り組んでおります。","id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"点字ブロックは視覚障害者の方にはとても必要で、杖、車椅子、ベビーカーからは逆にバリアになってしまうことがあります。適材適所にほかの利用者のことも考え設置していくことが課題となりますが、ご見解をお聞かせください。","respondent":"溝口道路課長","answer":"今後も引き続き、お互いの方たちが利用しやすい点字ブロックの設置の仕方については、様々な整備をする段階で検討していきたいというふうに考えているところです。","id":"exchange-007"},{"speaker":"松澤委員","kind":"意見","question":"どうしても点字ブロックの上を通るときは、車椅子とベビーカーがちょっと通れるような隙間を空けてありました。落下や飛び出しなどの危険な場所、こういったところには黄色の警告ブロック、そして誘導ブロックは一本線として景観に配慮し同系色のゴム製にするなど、新しい設置方法の考え方もこれからの時代には必要になるのではないかと思いますが、ご見解をお聞かせください。","respondent":"溝口道路課長","answer":"ただ、やはり連続して誘導していく、視覚障害者の方にはそういったことも必要だという観点もありますので、そこはやはり両方の立場のご意見等を聞いて、しっかり考えながら、今後どのような形で整備していくのがいいのかというのは検討していきたいと考えているところです。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"いろいろとお話し合いの中でよりよいものができればいいと私も思っております。いろいろと点字ブロックについてお聞きしました。デパートのエレベーターも２つあります。ハード面だけではなく、教育、歩み寄るという部分にも力を入れるべきではないでしょうか。心のバリアフリーという観点で、道路のバリアフリーに対する今後の取組やお考えを教えてください。","respondent":"溝口道路課長","answer":"やはりハードだけではなかなかすぐに、道路を利用する方が安全・安心に歩行できる空間はできない部分もあると思います。そういったところでは、やはりソフト的な対応も必要だと考えています。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"しかし、現状、まだまだ公園は限られた空間の中、公園利用者や近隣住民からの安全や騒音等の要望などが、様々な禁止看板が立てられており、規制された空間というイメージが定着しております。公園の多様な機能を発揮するためには、柔軟な利活用が求められるのではないでしょうか。そのためには、日常の維持管理と調整を図りながら、多様な地域ニーズに対応した一定のルールづくりが必要ではないでしょうか。","respondent":"高梨公園課長","answer":"公園が周辺にお住まいの方々に認められ、愛着を持ってもらうとともに、公園を訪れる方にとって快適に憩える場となるためには、地域の皆様の合意を持ってつくられた一定のルールづくりは今後も必要であると考えているところです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問・要望","question":"時代とともに公園の在り方も変わっております。道路で子どもが遊んでいた時代、車社会になり交通事故が増え、子どもたちが安全に遊べる場として住宅街に公園が整備された１９９０年代に都市公園法が改正されました。その後、相次ぐ自然災害で地域の避難場所として位置付けられるように、利用者が求める価値観が多様化しております。品川区でも、こういった逆転の発想、そういったお考えはないのでしょうか。","respondent":"高梨公園課長","answer":"しかしながら、公園や児童遊園の大規模改修や新設の際に、園内のルールは、地域の皆様と相談しながら決めている現状がありますので、ご提案のできる看板の内容につきましても、選択肢の１つとして今後に活かしていきたいと考えております。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問・要望","question":"ただいま禁止看板に対して遊びを考えるというお話もありましたけれども、やはり禁止で縛ってしまうと、子どもが考える力がなくなってしまうのではないのかと私は感じております。公園の曖昧だった機能を静かに過ごしたい公園と、思い切り体を動かせる公園に分ける考え方、ドッグランの設置の考え方もそうですが、２５６ある品川区の公園の多様性を求める考えを広げていきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"今後、時代により求められるニーズも変わってまいりますので、その時々のニーズをしっかりと捉えて、区民に愛される公園づくりを今後も進めてまいりたい、このように考えております。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"自分の子どももそうでした。公園でゲームをしている子どもにゲームばかりやらないで遊びなさいと私も結構声をかけてしまうのです。やはり地域コミュニティの大切なつながりの場である公園機能のさらなる充実を願いまして、次の質問に移らせていただきます。コロナ禍において、避難所における新しい運営マニュアルが作成されましたが、品川区標準版と比べてどのようなことが変わったのか教えてください。","respondent":"平原防災体制整備担当課長","answer":"私からは、避難所におきます新型コロナウイルス感染症対策を踏まえたマニュアルにつきましてご説明します。委員ご指摘のとおり、本年７月２０日に本区から各地域に対しまして、新型コロナウイルス感染症対策を踏まえた避難所運営のマニュアルをお配りさせていただいたところです。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"今、運営マニュアルを配ったというお話がありましたけれども、この運営マニュアルは、どなたにお配りして、また避難所連絡会議の方には、どういうふうに対応してくださいとか、そういった説明はされたのでしょうか。","respondent":"平原防災体制整備担当課長","answer":"それを受けまして、各地域で順次開催されました避難所連絡会議、こちらにつきましては本部長だけではなくて、各町会の役員の方も入っている会議ですが、そういった会議の場に、私ども区から、防災課の人間が中心になりますけれども。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"本部長といいますと、多分これは町会長になるかと考えていますが、実は、町会長も近隣の町会でもそういった説明がないと私はお聞きしております。多分、今、コロナ禍の中で、なかなか集まることができない中で説明ができていないのかとは思っておるのですが、だからこそやっぱりしっかり、こういったときこそ地域に連絡がいくようなシステムの構築が大事ではないでしょうか。例えばアプリです。","respondent":"平原防災体制整備担当課長","answer":"その中で防災マップにつきましても併せてご提供していく考えです。","id":"exchange-015","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"避難所に関連しまして、備蓄について質問します。コロナ禍において、マスクが不足する大問題が発生しました。災害対応のための備蓄マスクは、あくまでも災害時におけるものとして配布はありませんでしたが、今後、このような不測の事態において、備蓄品の活用をどうお考えなのか教えてください。","respondent":"平原防災体制整備担当課長","answer":"今回の新型コロナウイルス感染症の状況を踏まえまして、必要な備蓄品の増備、マスクにつきましても併せて増備を考えておりますし、先ほどありました避難所マニュアルのところでこれまでと考え方を変えたところにつきましては、必要な衛生資機材も準備させていただいたところです。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問・要望","question":"こういう災害は起こらないと言われていても起こってしまいます。本当に災害はいつ起こるか分からないということを私たちは経験いたしました。こういったことがあったときもしっかりと対応できるような組織づくりを目指していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"３１３ページ、勝島歩道橋エレベーター等整備（南側）、３１７ページ、水辺のライトアップ整備、３２１ページ、八潮地区の将来像検討経費、３４９ページ、集中豪雨等対策費ということで順番にお伺いします。最初に、勝島歩道橋エレベーター等の整備についてです。この現状を確認させていただきたいのと、予定通りのスケジュールでこれが進んでいるのかということをまずお伺いいたします。","respondent":"溝口道路課長","answer":"北側の整備につきましては、今現在、更地になっておりますが、商業施設ができるというふうに聞いておりまして、それに併せて商業施設側のほうで２４時間稼働のエレベーターを整備するということで計画をしており、現在、事業を進めているところですが。","id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"すみません、もう一度確認します。今既に付いております南側のエレベーターは、まだ稼働していないと思うのですが、これはいつから稼働するのかということをもう１回確認をさせてください。","respondent":"溝口道路課長","answer":"説明が悪くて申し訳ありません。南側エレベーターの稼働状況です。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。そして、この北側の設置につきましては、当初、品川区で造るというふうにも伺っておりましたけれども、民間がやるということで、令和４年度と今伺いました。地域からも、一体ここはどうなっているのかという声も上がっておりますし、早く設置してほしいという、そういう期待もあります。これが地元にはどのようにお知らせされているのかということをお聞かせください。","respondent":"溝口道路課長","answer":"ただ、やはり北側の建築が遅れているとかというところの周知が少し足りなかった部分はあると思いますので、事業者を含めて地域の方にはしっかり説明しながら進めていきたいというふうに考えております。","id":"exchange-020","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。どうぞよろしくお願いいたします。少し先のことになってしまいますが、１日でも早く整備されますように、取組を推進していただきたいと思います。もう１点、ここは自転車が乗せられるということも聞いておりましたけれども、予定どおり自転車が乗れるということを前提に整備されているのかということだけ確認させてください。","respondent":"溝口道路課長","answer":"今回整備しておりますエレベーターにつきましては、当然、ＪＩＳ基準等、基準をクリアした形での整備をしておりますので、自転車も入れるような大きさのものを整備しています。","id":"exchange-021","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、水辺のライトアップ整備についてお伺いいたします。対岸では、八潮地域の青少年対策委員会主催でハゼ釣りが催されておりまして、ここも例年になく大きな応募があったと伺っております。でも、ここは国道でありますので、実際には品川区が何かできることではありませんけれども、ぜひ国のほうに八潮橋のイルミネーション事業を働きかけていただきたいと思いますが、いかがでしょうか。","respondent":"松本河川下水道課長","answer":"先ほどお話があったように、昨年度、京浜運河にかかるかもめ橋、勝島橋にもライトアップをさせていただきました。国が管轄する八潮橋につきましては、今後、しっかり働きかけをしていきたいというふうに考えてあります。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問","question":"このイルミネーション化が進む中で、夜の屋形船がこのイルミネーションを見るために走ることができるようなことも期待しておりますので、どうぞよろしくお願いします。次に、八潮地区の将来像検討経費です。ガイドラインの作成もするということも伺っておりますけれども、現状と今後の展望をお知らせください。","respondent":"鈴木都市計画課長","answer":"今、ガイドラインのご紹介もいただきましたが、このガイドラインの策定に向けて、将来、建て替え後の姿というよりも、今お住まいいただいている八潮をよりよく住みやすく、さらによりよいまちにするために、このガイドラインを区としては定めていきたいというところで。","id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"１０月１日、発行の保育園のしおりでは、八潮中央保育園の改修が１年延期されたスケジュールが出されておりました。都営の１階ですので東京都から借りている立場ではありますけれども、ゆくゆく、この八潮地域全体の将来像をどうしていくのかという在り方、区としてどうお考えになっているのかということも含めて、この八潮北保育園跡の活用についてお伺いいたします。","respondent":"佐藤企画調整課長","answer":"その後に関しましては、八潮地区の行政需要でありましたら、地元のお声をお聞きしながら、どういった施設が適切なのかということを併せて検討していきたいと考えております。","id":"exchange-024"},{"speaker":"新妻委員","kind":"質問・要望","question":"失礼いたしました。最後に、土のうの置場についてお伺いいたします。そして、これは基本的にはこれまでに水害があったところに置かれていると認識しているのですが、区内全体でのそういう意識が高まっていることから、この土のうの置場の拡充を求めたいと考えていますが、土のうの置場の様々な条件ですとか、何かそのようなことがあるのか、拡充できるのかどうかお伺いしたいと思います。","respondent":"溝口道路課長","answer":"土のう置場につきましては、最近、災害が大きくなってきているという区民の方の認識のもと、利用が増えてきているのだというふうに感じているところではあります。","id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"増えたところはできるだけホームページにも公開をしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"３４９ページの集中豪雨等対策費について、近年巨大化する台風など豪雨災害について伺いたいと思います。それだけに十分な計画や事前の訓練を重ねる必要があります。自主避難施設の開設や土砂災害、目黒川氾濫、高潮による立会川氾濫による避難所の開設にあたって、毛布１枚の支給ではなく、環境改善へ最低限、水、食料、パーテーション、ベッドの設置を行うことを求めますが、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"避難所における環境改善についてですけれども、水や食料につきましては、まずは持参していただくことを呼び掛けるものではありますけれども、必要とする方につきましてはお渡しするとともに、今年度の予算や今回の補正予算でお認めいただきましたパーテーションなど。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"事前に水や食料を持参してくださいと呼び掛けること自体は別に構わないと思うのです。気象庁は、特別警報の運用を開始しております。品川区全域に気象庁が大雨特別警報を発表することが予測されることが示されたとき、品川区民がとるべき行動を示した行動計画はあるのか、その内容のポイントは何か、伺いたいと思います。","respondent":"平原防災体制整備担当課長、中島防災課長","answer":"避難施設におきます避難環境を少しでもよくするため、様々な資機材、物資を活用することしておりまして、さらには。万一、特別警報が発表された場合に関しましては、非常な豪雨の中で避難をするというのは危険な場合もありますので、例えば自宅の２階に上がるとか、命を守る最善の行動、そのようなものを情報発信してまいりたいと思います。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"大雨特別警報は、確かに数十年に一度と言われておりますが、近年は毎年のように各地で示されている。やはりこうした被害が予測される事態になったときには、浸水ハザードマップに示された浸水想定区域と、その周辺にお住まいの方の具体的な行動、またエリア外にお住まいの方の具体的な行動を示した住民の行動など、エリアを分けた行動の徹底が大切だと思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"基本的に品川区に関しましては、昨年の台風を踏まえまして、現在のところ、１,２００人の避難という基準で検討を進めているところですが、様々情報発信をしていく中で、例えば個人の避難行動を時系列でタイムラインとして計画していただくような周知をしています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"タイムラインの啓発に努めていきたいということですが、まだまだ住民には十分に届いていないという実感があります。大雨特別警報が発表されることが予測され、品川区内全域が対象となることは十分あり得ます。ぜひ住民がとるべき計画の徹底、住民が参加する水防訓練などの実施も検討していただきたいと思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"防災の観点からいたしましても、避難訓練も検討しているところでございまして、例えば避難行動要支援者の避難訓練とか、そういうことも実施に向けまして検討しています。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"とりわけ自分で移動が困難な方、移動するのに支援が必要な方にとっては、とても不安な経験をしたとお話を伺いました。幸い、昨年は重大な水害の被害は発生しなかったのですが、いつ起きてもおかしくないと考えています。要支援者への支援も重点的にぜひ実施していただきたいと思いますが、改めて水防訓練や一人ひとりのタイムラインに沿った計画の策定などを求めたいと思いますが、改めていかがでしょうか。","respondent":"中島防災課長","answer":"水防に関しましては、かねてから区職員の訓練等に努めているところですが、やはり区民と一丸となった防災対策という観点では、避難行動要支援者の個別計画、これは震災のほうでも、今、福祉部と連携しまして取り組んでいるところですが、そちらをまた一層強化していくということ。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。強化するということで、タイムラインも作っていきたいということですけれども、今週、来週起きてもおかしくない台風の被害でありますから、職員の方にはもちろん大変なご苦労をかけるかと思いますが、ぜひ住民の命を守るために力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３１７ページ、水辺利活用事業に関連して、３３９ページ、マンション管理支援事業、３１７ページ、治水対策費からお伺いいたします。品川区の舟運、水辺活用に、この東京国際クルーズターミナルの活用をするべきではないかと２年程前からお伝えしているところであり、今年の予算特別委員会の総括質疑でもお伝えしたところです。この内覧会に区長がご出席された経緯と理由をお聞かせください。","respondent":"鈴木都市計画課長","answer":"当初からこのクルーズターミナルにつきましては、区としても非常に品川区と近い、近接しているということもあって、いろいろ関係部署の中で、帰属ですとか、そうしたところも含めて調整をしてきたところで、お声がけがあった中での内覧会参加です。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。当然その逆も行けるということになります。舟運水辺活用を推進する品川区ですから、区民の子どもたちの教育にもよい効果が期待できるかと思います。ぜひ品川区の舟運の発展のために、舟運が区民に期待される日常の足となるために、クルーズターミナル近くの青海小型船発着所浮桟橋の活用を所管の東京都港湾局と粘り強い協議の上、積極的に進めていただきたいと思いますが、いかがでしょうか。","respondent":"松本河川下水道課長","answer":"当初、オリンピックに合わせて実施する予定でしたが、今、新型コロナウイルス感染症の状況でありまして、今後の実施に向けて検討を進めているところです。","id":"exchange-034","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"私もポテンシャルは非常に高い場所だと思いますので、ぜひご活用をお願いします。品川区の舟運、水辺活用の東京湾進出、ダイナミックな展開、そしてそのことから区民の日常の足となることを期待しまして、次の質問に移らせていただきます。","respondent":"森住宅課長","answer":"マンション管理支援事業についてです。区では、マンション管理セミナーとして年２回、防災対策等検討交流会も併せて実施しています。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。やはり防災また大規模修繕というのは一番関心が高いのかと思います。いろいろな住民のお考えがありますけれども、それらがやはり共通して関心が高い事項かと考えております。そうしたことで、今後、国は２０２２年に管理計画認定制度というものを創設されるです。今年４月から始まった東京都の管理状況届出制度との関係性、重複するところはないのか、それら３点、お伺いいたします。","respondent":"森住宅課長","answer":"東京都の条例との関係性ですが、こちらもまだ整合性がどこまでとれるのかというところも含めて、都と国で検討されているというふうに聞いてあります。","id":"exchange-036","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたことで国も動き出したと思うのですけれども、東京都の管理状況届出制度があるにもかかわらず、国もさらに出したということで、二重になってしまうところがあるのかということ、どうなるのかということがちょっと懸念されるところなのですけれども、その辺り、引き続き、品川区としても注視していただき、また、マンションは品川区にももう既に結構たくさんありまして、また今後。","respondent":"森住宅課長","answer":"周知につきましては、東京都と連携し、東京都では、例えば公共機関の吊り広告であったり、そういった部分でしっかりとＰＲしていきたいというふうに申しておりますので、区もそれと連携しまして、しっかりとＰＲをしていきたいというふうに考えております。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"昨年も台風第１９号によりまして、武蔵小杉でマンション浸水事故が起きました。浸水を防ぐ、浸水被害の軽減という事業の趣旨・目的からしますと、そもそも扉自体を防水扉にしてしまったほうが、浸水防止、地下発電機の被害を防ぐ、浸水被害の軽減という効果は高く効率的かと考えるので、防水板に加えて防水扉の設置等工事の助成も行っていただきたいと思いますけれども、ご見解はいかがでしょうか。","respondent":"松本河川下水道課長","answer":"現在、当課で行っております防水板設置等工事助成事業ですが、大雨、洪水、高潮などによる浸水被害の軽減のために、住宅、店舗、事務所などに防水板の設置および防水効果を高めるなどの関連工事の一部に対して助成をする制度です。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"それらは、恐らく地下発電機かと思われますので、そうしますと、台風とかで浸水して発電機が止まってしまったら停電になる、そして住民の生活が一時止まってしまうということになってしまいますので、いっそのこと防災扉のほうが、より事業の趣旨・目的の効果を達成しやすいと思うのですけれども、ぜひ検討を行っていただきたいのですけれども、その点についていかがでしょうか。","respondent":"松本河川下水道課長","answer":"今の助成制度ですが、今お話のありましたタワーマンションだとか、そういった地下に設備等がある場合には、やはりマンションを造る際に防災扉を付けるべきだというふうに考えております。私たちの今の助成につきましては、既存のある建物等でそういった……。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"３１９ページ、３項１目雨水流出抑制推進事業、３２１ページ、４項１目やさしいまちづくり整備費、３２５ページ、３目大井町駅周辺地区再開発事業、３４１ページ、６項１目居住支援協議会について伺います。大井町駅周辺地区再開発事業、広町地区について伺います。過日の他会派の一般質問の答弁で、土地区画整理事業の活用を検討しているとありました。","respondent":"多並都市開発課長","answer":"この土地区画整理事業を今回の地区についての事業として検討を進めているところのポイントといたしましては、土地を再編する、今ちょうど駅のほうに区の土地があり、また、今ある現庁舎の離れたところにあるところをＪＲ東日本の土地と合わせながら。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"広町地区の公有地は、区の公有財産の管理、区の規定や条例から離れてしまうのでしょうか。ご説明ください。事業の中で区民の財産が勝手に使われてしまうのではないかという不安がよぎります。区民の財産に関わることなので、区民に対して丁寧な説明が必要だと考えますが、見解を伺います。先ほど、土地区画整理事業の有効性といったことが話されていましたが、そこの理由についてももう一度お知らせください。","respondent":"多並都市開発課長","answer":"使い方についてでありますが、基本的な考え方としては、まずは土地の区画を再編して、今よりもより大井町の周辺のまちづくりに発展できるようにということで、今回も大井町駅周辺地域まちづくり方針という形で方針をまとめさせていただきまして。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"続けます。行政機能・にぎわい集積ゾーンと、駅側の新たな都市機能集積ゾーンでは浸水想定区域が異なりますが、浸水想定区域について、どのような議論がされて、このようなゾーン分けがされたのか伺います。土地区画整理事業によって、土地を公平に負担して土地の再編を図るという中で、浸水想定区域とそうでない区域での公平な負担は、どのように検討がされているのか、区の見解を伺います。","respondent":"多並都市開発課長","answer":"ベースとなるところの検討を今進めているところで、併せて、今度は細かいところについて、各事業者と協議しながら進めなければいけないところです。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"分かりました。詳しいことは今後聞きたいと思います。行政機能・にぎわいゾーンの中では、新庁舎建設の検討がされています。庁舎機能検討委員会では、新庁舎の候補地について、今後、変更する可能性があるのか問われた区は、現在示している候補地以外の選択肢はないと発言をしています。ほかに選択肢がないとする理由を伺いたいと思います。","respondent":"多並都市開発課長","answer":"ここの中で、現庁舎が老朽化または様々な新しい機能が必要だということで、現在、庁舎機能検討委員会を開きながら、どのような機能が必要かということを検討しています。","id":"exchange-043","title":"町会・自治会支援"},{"speaker":"田中委員","kind":"質問","question":"選択肢がないとする理由を伺ったので、もう一度伺えればと思います。先へ進めます。現在優先すべき施策として、新型コロナウイルス感染症対策があります。このことからも拙速にまちづくりを進めていくのではなく、住民への丁寧な説明を行い、相互理解が進む時間を十分にとっていく必要があると主張し、次の質問にいきます。各駅の計画の進捗状況は先ほどの質疑から伺いました。","respondent":"鈴木都市計画課長、榎本総務部長","answer":"今ご紹介いただきました大井町、旗の台以外の重点地区化ですが、現在のところ、特定の地域を取り上げて導入に向けて検討を開始しているという状況はございません。要は、容積としてどれぐらい入るか、ざっくりですけれども、入るのは今より大きくなければ移転する意味がないですから、そういった意味で候補地としては広町のところになるです。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"障害者、高齢者、乳幼児やその保護者、ケア者、介護者などの当事者から歩きづらい場所等を聞き取り、駅周辺に限らず、区内全域でのバリアフリーを進めてほしいと要望しますが、区の見解を伺います。やさしいまちづくり推進協議会に関わっていたと思いますが、２０１８年を最後に開催されていないのでしょうか。京急側は設置に向けてどのような見解を示しているのか、協議の進捗も併せて伺います。","respondent":"溝口道路課長、鈴木都市計画課長","answer":"今後も様々なバリアフリーに対するご要望があると思いますので、機会を見ながら、関係団体等のご意見も聞きながら整備に努めていきたいと考えているところです。やさしいまちづくり推進計画が地域福祉計画のほうに統合されたというご紹介をいただきましたが、基本的な考え方として、やはりやさしいまちづくり推進計画は、ハード、ソフト両面からバリアフリー化。","id":"exchange-045"},{"speaker":"田中委員","kind":"提案","question":"土地がなくてという答弁がちょっとよく分からなかったのですけれども、２０１５年から生活者ネットワークは主張していますが、区は、先ほどもありましたホームドア設置などに助成を出しているのですから、区民要望の多い場所や、今回のような請願採択のあった場所については、優先的に区が率先して設置に向けた提案を事業者にしていってほしいと改めて要望いたします。雨水流出抑制推進事業について伺います。","respondent":"松本河川下水道課長","answer":"雨水利用の促進に向けてタンクの設置費の助成を行っているところです。浸水対策だったり、水の利用について助成をしています。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"ぜひ拡充をお願いしたいのですけれども、そこの見解を伺います。","respondent":"松本河川下水道課長","answer":"拡充につきましては、こちらは東京都との協議等もありますので、東京都とその辺のことにつきまして話合いをしていきたいというふうに考えてあります。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"本日は、３０７ページ、シェアサイクル事業について、３０９ページ、デザインマンホール蓋設置等について伺います。シェアサイクル事業についてですが、平成３０年に区は株式会社ドコモ・バイクシェアと、都内初となる災害時におけるシェアサイクル使用等に関する協定を締結しています。協定上の災害の定義は、災害対策基本法上の災害でいいのか。これまでこの協定の活用実績があるのか伺います。","respondent":"稲田土木管理課長、中島防災課長","answer":"実績は現在のところありません。繰り返しになりますが、こちらのシェアサイクルの活用については、これまで実績はございません。水害のときに使うかどうかですが、実際のところ、台風や大雨のときに自転車で行くかというと。","id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"国会でも新型コロナウイルス感染症が災害対策基本法上の異常な自然現象に該当するのかというのは、これは議論がされていたところだと思います。なかなか想定は難しいとは思うのですけれども、シェアサイクル協定上、この新型コロナウイルス感染症などの感染症が災害ということで対象になっていくのかどうか、そこをお願いいたします。","respondent":"中島防災課長","answer":"こちらの協定につきましては、あくまで現時点では自然災害を想定していますので、そちら以外のところについては基本的には対象外というふうに考えているところです。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。災害時に、協定上、自転車は使用できるのだけれども、ポートまで遠いということになると、せっかくの協定がなかなかうまく活用できなくなってしまうのかというふうにも思います。ですので、地域センター周辺にもポート整備をしていけるように、区として計画的にドコモ・バイクシェアと、あるいは周辺地権者と協議していくべきかというふうに思うのですけれども、ご見解をお願いいたします。","respondent":"稲田土木管理課長","answer":"今年度４月から本格実施に移ったのですけれども、なかなかやっぱり荏原地区とかは、全体から見ると少ないというような状況もありますので、災害時の活用だけに限らず、シェアサイクルのポート等も増やしながら事業を進めていきたいというふうに考えております。","id":"exchange-050"},{"speaker":"松本委員","kind":"意見","question":"今、荏原地区というふうな話が出ましたけれども、確かに荏原地区のポートはちょっと少ないかなというふうに私も地元に住んでいますので思うのです。その荏原地区に関しては、逆にポートが少ないということもある一方で、あそこはかなり人口も密集している。これはやっぱり区としても対策というか、何かしら考えていかないといけないのではないかと思うのですが、この見解をお願いいたします。","respondent":"稲田土木管理課長","answer":"ポートに自転車があふれているというような話とか苦情等は区のほうにも入ってきており、私も現場等々を見て回っているところですが、なかなかこれをバランスよく均等に配置するところは難しいところではありますが、事業者はトラックを用いまして、いろいろなところに。","id":"exchange-051"},{"speaker":"松本委員","kind":"意見","question":"やっぱり抜本的な解決の１つの方法としては、ポートを増やしていくということかと思いますので、引き続きご努力をお願いしたいと思います。次に、デザインマンホール蓋設置等についてですけれども、こちらは平成３０年度の決算額だと６６万円程度だったのですけれども、平成３１年度（令和元年度）は約４７０万円と７倍以上になっています。","respondent":"溝口道路課長","answer":"ただ、令和元年度（平成３１年度）の予算につきましては、現地でデザインマンホールの設置をしており、その分、工事費等がかさんだことによって決算額が大きくなっております。","id":"exchange-052"},{"speaker":"松本委員","kind":"質問","question":"一方で、令和２年度の予算だと、デザインマンホールに関連する予算が計上されていないということなのですけれども、これは増やす予定がないのかと、あと、マンホールカードとかも増刷するとか、そういう費用があり得るのではないかと思うのですけれども、この辺りはどうなのでしょうか。","respondent":"溝口道路課長","answer":"今年度につきましては、道路課の事務費の中で少し考えておりまして、新たに今年度、武蔵小山のほうに、スクエア荏原においてマンホールカードの新たな配布等を行っておりますので、その分の事務的経費は予算で進めるところです。","id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"これは面白いことに広告代もＫＡＤＯＫＡＷＡからもらっているということで、こういった企画、実は品川区にはサンリオだけではなくて、ゲームメーカーのセガもあるということで、こういったところもぜひ協議していただきたいと思いますが、いかがでしょうか。","respondent":"溝口道路課長","answer":"区民の方に親しんでいただく、来ていただく、そういったところの１つのツールだと考えていますので、様々な手法を検討していきたいというふうに考えております。","id":"exchange-054"},{"speaker":"芹澤委員","kind":"提案","question":"併せて、３４５ページの防災体制整備費で、ドローンについて幾つかお伺いしますけれども、その前に１点確認で、以前、仙台市のほうで未確認飛行物体が来て、その対応をする際に、いろいろなところが気象庁ではありませんとか、自衛隊のほうでも関知していませんというような様々なことがあったと思うのですけれども、これは所管が違えばおっしゃっていただきたいと思いますが。","respondent":"森住宅課長、中島防災課長","answer":"私からは、住宅補修緊急支援事業、住宅課のほうで実際の事務を行いましたので、その部分についてご説明します。私からは、未確認飛行物体に関するお問合せにつきましてですが、こちらは災害対策というよりも危機管理事象の範疇と推察されますので、当然、危機管理の部署等が適切に対応するところではありますが、防災課といたしましては。","id":"exchange-055"},{"speaker":"芹澤委員","kind":"質問","question":"住宅補修に関しては、非常にいい前例ができたと思っていますので、引き続き柔軟な対応を続けていただければと思います。ドローンに関しては、順次人数、あと機器を増やしていくというようなお話がありました。次に、防災タブレットについてもお伺いします。防災タブレット、これから新しくなるというふうに伺っておりますけれども、まず新旧で何が変わったのかをお聞かせください。","respondent":"中島防災課長、平原防災体制整備担当課長","answer":"実際に飛ばす際は、必要な許認可を得てやっているところでございまして、ほかの場所、市街地での練習などでは、恐らく条件等々もまた変わってくると思いますので、可能かどうか、その条件についても確認をしてまいりたいと思います。私からは、防災タブレットにつきましてお答えします。ご案内のとおり、防災タブレットは、今年度、更新を予定しております。","id":"exchange-056"},{"speaker":"芹澤委員","kind":"質問","question":"ドローンに関しては、今お話しいただいたとおり、上から俯瞰して見るということで、いつもの景色とは違うわけです。そうすると、無線ＬＡＮの整備というようなものもたしかどこかに経費として入っていたように理解をしているのですが、この無線ＬＡＮ、Ｗｉ－Ｆｉの接続がなくても、同じように４Ｇなりで接続ができるという認識でよろしいでしょうか。","respondent":"平原防災体制整備担当課長","answer":"こちらのネット環境ですけれども、今度新たに導入することを検討しておりますタブレットにつきましては、通常はＬＴＥ回線です、いわゆる通常のキャリア回線を用いて通信することを考えてあります。","id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問・要望","question":"国が指定する災害の扱いと、新型コロナウイルス感染症はまた別だと理解をしていますけれども、今回の新型コロナウイルス感染症の拡大によって、何か防災協定を使ったものがあるのかどうか、まず１点お聞かせいただきたいのと、あと、今回の新型コロナウイルス感染症で、防災の考え方が少し変わってきたのかと思うのですが。","respondent":"中島防災課長","answer":"災害時というところで、今ずっと運用してきている協定ですので、それをすぐほかの事象に展開していくというところまでは、まだ調整していないところです。基本的には現状の災害を中心に協定は運用していきたいというふうに考えてあります。","id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問","question":"ほかにも物資の提供という意味で言えば、これまで通常の防災協定の中では、飲料水の提供であったりとか、様々な物資の提供も協定の中に入っていると理解しています。最後に、水辺千本桜計画推進費についてお伺いしていきます。目黒川沿いを中心にして、水辺に千本桜をというふうに区長の発信でこの計画をつくっていただいたと思っていますが、まずこちらの計画の進捗をお聞かせください。","respondent":"中島防災課長、溝口道路課長","answer":"協定につきましては、例えばマスクなどにつきましては、今回は防災課の管理している備蓄も活用して対応してきたところでございまして、そういうほかの災害以外の事象について。水辺千本桜計画につきましては、２０２０年まで、オリンピックの開催が予定されていたときまでに水辺に桜を整備していこうということで、平成３０年から事業を始めております。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"質問・要望","question":"水辺千本桜計画についてですが、今お話しあったとおり、１,０００本を達成したということで、私の会派からの要望でもありますけれども、１,０００本を達成したということで、ここで水辺の桜の計画をもう中止にしてしまうというか、完了としてしまうというふうにせずに、ぜひ品川区の桜はすごいねというふうに思ってもらうには、もう一声、桜の植樹が必要なのかと思っています。","respondent":"溝口道路課長","answer":"そういった中で、場合によってはさらに増やしていく、さらに拡充していく、そういった考えもありますので、まずはしっかり管理して皆さんに目黒川沿いの桜を知っていただく、そういった取組につながっていければというふうに考えているところです。","id":"exchange-060"},{"speaker":"せお委員","kind":"質問","question":"３２９ページ、子どもたちのアイデア等を活かした公園づくりから何点かお聞きします。そこで、ワークショップの際に作成されたアイデアブックですが、大井坂下公園整備の設計の際、どのようなアイデアが採用される、または採用されたのでしょうか。今回、残念ながら採用されなかったアイデアは、今後どのように活用されますでしょうか。お聞かせください。","respondent":"高梨公園課長","answer":"そのアイデアをいただきまして、通常のシートに加えて背もたれ付きのシートであったり、複数人で乗れるような少し大きめなシートを備えたブランコを、今、実施設計中の大井坂下公園で採用する予定となっております。","id":"exchange-061"},{"speaker":"せお委員","kind":"提案","question":"今回、子どもたちの考えは柔軟で、特別支援学校の生徒が発言したりとか、特別支援学校の先生から提案などがあったりすると、すぐそれに合わせて考えてアイデアが出てきたりしていました。これから区内の施設や取組を検討する際に、障害がある子もない子も一緒に行うワークショップをぜひとも様々な場所で実施していただきたいと、これは要望したいと思います。","respondent":"高梨公園課長","answer":"しかしながら、インクルーシブの視点につきましては、これからますます重要視されていくものと区としても考えておりますので、このような視点を意識しながら、遊具改修の際にも検討していきたいと思います。","id":"exchange-062"},{"speaker":"せお委員","kind":"質問・要望","question":"例えば、ベンチ１つをとっても、背もたれがあるほうが、高齢者にも、あと座位が保持できないお子さんにも使いやすいかと思います。ぜひともその辺も考慮していただき改修していただきたいと要望いたします。次に、都立林試の森公園に関してです。今年の予算特別委員会でのご答弁で、都に要望を伝え、働きかけていくとありましたが、その後、何か変化はありましたでしょうか。お聞かせください。","respondent":"高梨公園課長","answer":"その検討に際しまして、品川区へも地元自治体ということで意見照会が行われました。区といたしましては、公園機能の拡充にあたり、品川区が予定しております社会福祉施設等との機能連携について、積極的な協議、検討を要望しています。","id":"exchange-063"},{"speaker":"せお委員","kind":"質問・要望","question":"東京都もインクルーシブ公園の整備を進めていますので、改めて連携を強めていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"３０５ページ、屋外広告物取締事務です。これは具体的にどのような内容、理由でしょうか。もう１点、屋外広告物条例違反の悪質な業者に対しては、過料、罰金などがありますが、注意、指導を超えて実際に過料、罰金を科した事案は年間何件程度ありますでしょうか。このような悪質な事業者に対して、区はどのような対策を講じていますでしょうか。","respondent":"稲田土木管理課長","answer":"屋外広告物等の除却件数についてお答えいたします。","id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"その植木鉢、プランター等に関して、急増しているように感じるのは、それは取締りの基準が厳しくなったからでしょうか。その他の点もまとめて質問します。関係者の皆様にご努力いただいているのですけれども、平成２８年度１,２５６件から令和元年度１,４６７件と、一進一退でなかなか減少していないのが実情ですけれども、この理由についてどのように分析していますでしょうか。","respondent":"稲田土木管理課長","answer":"そんなに変化がないのではですが、区としましては、パトロール強化、道路課とも連携をしながら現状を把握しながらやっているところでございまして、先ほどもちょっと言いましたけれども、植木鉢とか、そのときは片づけるのですけれども。","id":"exchange-066"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、緊急時連絡用通信機器についてですけれども、こちらは７月にＰＨＳが停波したため、スマートフォン５２台を業務用に支給したとのことですけれども、今回の分と、既に区からスマホを支給されている方は対象から外して、携帯電話のみをお持ちでスマホを持っていない理事者の方など、どの程度いらっしゃるのでしょうか。これはもちろん区長、副区長も含めてです。","respondent":"平原防災体制整備担当課長","answer":"そのような取扱いとさせていただいているところです。","id":"exchange-067"},{"speaker":"くにば委員","kind":"質問","question":"今ちょっと答弁漏れがあったのですけれども、先に質問のほうをいきます。今回支給の５２台には防災時の連絡用として何か統一したアプリをインストールしましたでしょうか。現在、発災時の連絡方法はどのようにしていますでしょうか。今後、アプリを活用した庁内での連絡・連携についての方針もお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"あるいは、それに安否確認機能が付いておりますので、それで返答していただいて職員の安否を把握できる、そういったもので導入させていただいているところです。","id":"exchange-068"},{"speaker":"くにば委員","kind":"意見","question":"最終的に携帯電話のみをお持ちでスマホを持っていない理事者の方がいらっしゃるかどうかというのは分からなかったのですけれども、今、スマホにＬＩＮＥのアプリを入れているということで、そちらのＬＩＮＥのアプリのグループ、やっぱり相互に連絡ができるというのが非常に活用できて便利な部分だと思います。最後、八潮地区の将来像検討経費です。その点をお聞かせください。","respondent":"鈴木都市計画課長","answer":"平成２９年度よりまちづくり検討を開始しています。","id":"exchange-069"},{"speaker":"くにば委員","kind":"質問","question":"最後、端的な数字が分かれば。八潮地区、まだ耐用年数が３０年あるというふうにおっしゃっていましたけれども、この検討事業はいつぐらいまで続ける予定でしょうか。例えば、あと２０年間ずっと検討ばかり続けていると、かなりの予算がかかってしまいます。検討をいつまで続けるかお願いします。","respondent":"鈴木都市計画課長","answer":"平成２９年度から昨年度までの決算ですが、１,２４０万円余です。それから、検討ですが、基本的には来年度をもって、まちづくりのガイドラインを取りまとめて行っていきたいです。","id":"exchange-070"},{"speaker":"つる委員","kind":"質問・要望","question":"３４７ページ、防災行政無線管理費、３０５ページ、交通安全啓発費、３０９ページ、道路安全施設費、３３７ページ、コンクリートブロック塀等安全化支援事業、３０７ページ、駅周辺等放置自転車対策事業、３１１ページ、道路バリアフリー事業について伺っていきます。今日は子どもたちの安全・安心という視点でそれぞれ確認をさせていただきたいと思いますが、まず防災行政無線に関してです。","respondent":"平原防災体制整備担当課長","answer":"ただいまご質問のございました防災行政無線、１７時のチャイム「夕焼小焼」ですけれども、１９８９年（平成元年）に公募を行いまして、それ以降、「夕焼小焼」を放送させていただいているところです。","id":"exchange-071"},{"speaker":"つる委員","kind":"提案","question":"自治体によっては、季節を感じられる曲というか、季節によって四半期に一度、曲を変えたりとか、また、地元地域の出身の芸能の方で、例えばＸ ＪＡＰＡＮの曲をかけているとか、ウルトラセブンの曲をかけているとか、自治体によっていろいろあると思うのですが、過去にもそういう提案もありましたけれども、例えば、この曲について、私は「夕焼小焼」は大好きでありますけれども、いろいろな。","respondent":"平原防災体制整備担当課長","answer":"冒頭ございましたとおり、私ども、１７時のチャイムにつきましては、防災行政無線がきちんと機能しているかという試験を目的に実施しているものですけれども、例えば防災以外の効果につきまして、どのような形で使うことができるのかとか、あるいは、私ども自体は、今現在。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"次にいきます。決算ですので実績を見ると、例えば除去については６０件、フェンスについても６０件やる予算の中で、最終的な決算としては、除去が２２件で、フェンスが７件というふうになっています。そうしたところは、この条件から外れてしまうのですが、そうしたところに対する支援策もこの中で活用できるのかどうか、併せて教えてください。","respondent":"長尾建築課長","answer":"今年度に関しましては、半年程度ですけれども、おおむね３０件程度の除却助成の申請を受け付けているところで、昨年度と比べましても引き続き伸びているような状況があります。引き続き丁寧に対応していきたいと考えております。","id":"exchange-073"},{"speaker":"つる委員","kind":"質問・要望","question":"その脇に万年塀が非常に高い、２ｍぐらいでしょうか、あるところですので、しっかりとここは対策をお願いしたい、そういう思いであえてお伝えさせていただきました。では、次にいきます。駅周辺等ですが、駐輪対策という視点ですけれども、まずその前に、今、車道に自転車ナビマーク等が表示されているおりますが、これは法定外表示というものかと思うのですが、この認識を教えてください。","respondent":"川口交通安全担当課長","answer":"ただいまご質問の自転車ナビライン、自転車ナビマークのご質問です。こちらにつきましては、法定外表示ですので、法律上、規定されたものとは異なります。","id":"exchange-074"},{"speaker":"つる委員","kind":"提案","question":"いわゆるゾーン３０も含めて法定外表示は、結構いろいろあるのだなということを改めて思ったところでありますが、その中で駅周辺等の駐輪対策ということで、かつて私も２０１１年に初めて大阪市の取組を紹介して、何度か子どもたちが、「違法駐輪、駄目だよ」というようなことをかいた絵を歩道上に貼ったりとか、また敷地に貼って駐輪をやめさせていく、こういう取組をやったらどうだという。","respondent":"川口交通安全担当課長","answer":"したがいまして、以前の答弁等では交通管理者である警察等との協議を踏まえてというところなのですけれども、以前、警察のほうに質問した際には、なかなか設置は困難という回答であったと思います。","id":"exchange-075"},{"speaker":"つる委員","kind":"提案","question":"最後は要望になると思いますが、今申し上げた交通環境をしっかりと確保していただくというところでは、これも既に何度か提案も、２０１７年以降させていただいているＷｈｅｅＬｏｇ！国土交通省からも様々なログも提供されているわけでありますが、今後ぜひ、また改めて提案をさせていただきたいと思いますので、このＷｈｅｅＬｏｇ！の活用について、ぜひ積極的に様々な部署で検討いただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問","question":"３２０ページ、都市計画費、空港環境担当に関わって、羽田新飛行ルートについて質問いたします。国土交通省は、６月に羽田新経路の固定化回避に係る技術的方策検討会を設置しました。この検討会について、共産党の都議会議員が、先月、都議会で、「固定化回避は名ばかりで、実際は、都心上空の低空飛行が大前提とされています。お尋ねいたします。","respondent":"鈴木都市計画課長","answer":"その中では、今ご紹介いただいたように、「現在の滑走路の使い方を前提とし」と、こうした表現は、今、第１回目の議事録が国のホームページ上でもアップされておりますが、その中でも委員の発言として議事録の中でも紹介されているというところでは認識しているところですが。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問","question":"この検討会について、さらに念のためお伺いしておきます。そして、「新飛行ルートの滑走路運用及び発着便数そのものを再検討すべきではないか」との質問主意書を提出しました。そうしますと、品川区は、やはり検討会が新ルートを、ある意味、前提としているのだというふうにご認識しているということでよろしいのでしょうか。","respondent":"鈴木都市計画課長","answer":"羽田新ルートについて、昨年８月、国のほうで運用について本格決定を公表したわけですが、その過程の中で、これは国の事業、国策ということで、国の判断のもと、国の責任において進められていくべきものというところの認識ですが、ただ、これが決定したからといって。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問","question":"もう１点伺っておきます。そこで伺います。以上のこと、まず第１に、自衛隊機が新飛行ルートを飛ぶこと、それから第２に、１時間に合計４４便という着陸便数に自衛隊機が含まれていること、それから第３に、部品欠落の報告制度、それから羽田空港において実施している国による駐機中の機体チェックについて、自衛隊機は対象とされていないことを品川区は認識されていたでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"それは国の防衛あるいは様々な中で飛ぶこともあると、これは羽田新飛行ルートに限らず、従来から民間の航空機のルートを、当然ながら羽田に着陸するときは自衛隊機も飛ぶという考え方だと認識しています。","id":"exchange-079"},{"speaker":"おくの委員","kind":"質問・要望","question":"そう、飛ぶことがあるということなのです。そうしますと、自衛隊機までもが新ルート上を飛ぶという以上、区民の安全は、国土交通省が対策をやったというだけでは守り切れないということはいよいよ明らかであって、いよいよもって新ルートそのものをやめることを国に求めるべきではないかと私は思うのですが、その点、いかがでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"そうした中で、当然ながら自衛隊機は落下物の取組を何もしなくていいのかということは全くございませんで、それは国の責任において、それは自衛隊の中で当然ながら定期的なチェック、確認はされていると思いますが、羽田新ルートについて、これは定期ではなくて大分本数。","id":"exchange-080"},{"speaker":"横山委員","kind":"質問","question":"私からは、３１３ページ、都市計画道路整備事業について、３２０ページ、都市計画費について、３２１ページ、区民の自主的なまちづくりへの支援についてと、時間があれば、３０５ページ、道路・公園等監察費についてをお伺いいたします。１点目に、都市計画道路整備事業についてお伺いいたします。道路の便益計算について、例えば補助１６３号線では、どのような積み方をしていますでしょうか。","respondent":"溝口道路課長","answer":"この評価につきましては、基本的な考え方についてはあまり従前から変わっていないのですけれども、従前からの新規採択のとき、または事業が一定期間経過したとき、その後、事後という形で最終的にこの事業を行うことによってどういう成果があるのか。","id":"exchange-081"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらの補助１６３号線につきましては、全体でやっていらっしゃるということでしたので、例えば今後ですけれども、区としてもアカウンタビリティの向上を図っていただくということを要望いたしますが、こちらはいかがでしょうか。２点目にまいります。都市計画費についてお伺いいたします。","respondent":"溝口道路課長、鈴木都市計画課長","answer":"当然、今後いろいろ様々な事業をやっていくときには、１つの指標として、また分かりやすい形、区民の方が数字でこれだけ道路を整備することによって効果がどのくらいありますという手法でありますので、また、先ほども話したように。大正初期では、全体的に田畑を計画的に作って生産性を上げていこうということで、耕地整理事業が行われましたが、耕地整理、非常に区画が大きいということで、周りの道路も４ｍない、俗に言う３.６ｍ道路が。","id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"歴史的な経緯についてご説明ありがとうございました。特に水害に対してなのですけれども、３０年から５０年後に起きたときにも、また１００年後もしのいでいけるように、人命を守るためのインフラの再配置の議論を始めていく必要があるというふうに私は考えておりますが、過去の災害の被害を今までどのようにまちづくりに活かされていますでしょうか。区のご見解をお聞かせください。","respondent":"鈴木都市計画課長","answer":"水害の話もございましたが、これも東日本大震災では、特に千葉県のほうで液状化が多かったというところで、東京都の液状化マップ等を来庁された方が閲覧できるような体制を関係部署がとってありますので、そうした中でこの液状化も周知させていただいて。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"３点目にいきたいと思います。区民の自主的なまちづくりへの支援についてお伺いいたします。こちらは具体的にどのような内容なのでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の自主的なまちづくりですが、地域の課題をまず居住者の方々、土地を所有されている方々が自主的に、例えば共同化を図っていきたい、あるいは防災性の向上を図っていきたいというところで、まだまだ何か市街地再開発事業とかそうしたところではなくて、地域が主体となって。","id":"exchange-084"},{"speaker":"横山委員","kind":"意見","question":"こういった支援があることを認知していただけるようにお願いしたいのですが、区のご見解を簡単にお聞かせください。","respondent":"鈴木都市計画課長","answer":"この制度をしっかり使っていただけるように、様々な機会を捉えて周知をしてまいりたいと思います。","id":"exchange-085"},{"speaker":"西村委員","kind":"質問","question":"３２３ページ、不燃化１０年プロジェクト、３４７ページ、防災行政無線設備更新費について伺ってまいります。区は、５か年計画の３年目に、２億７,６００万円近く費用をかけまして、防災行政無線の修繕を行いました。どのような工事を行ったのか、改めて詳しくお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"防災行政無線の工事のお尋ねですけれども、こちらは国の法令改正に基づきまして、防災行政無線に活用しております発信電波をアナログ波からデジタル波に移行するために機器を交換するものを５か年で実施しているものです。現在はその４年目という状況です。","id":"exchange-086"},{"speaker":"西村委員","kind":"質問","question":"議事録を見ましても、こちらはずっと議論されていることと思いますが、工事をしていただいても、やはり聞こえない状況はあまり変わらないように思います。これをどのように解消していくのか。特段聞こえをよくする工事ではなかったと理解していますが、これまでの聞こえないという区民の方の声は承知されているでしょうか。お聞かせください。","respondent":"平原防災体制整備担当課長","answer":"私ども、そういう声をいただきましたら、直接現地に赴きまして、音量の調査など必要な調整を行っているところですけれども、現在の住宅の高層化、あるいは高気密化に伴いまして、全ての方にきちんとした形で防災行政無線が届くというのが難しい状況です。","id":"exchange-087"},{"speaker":"西村委員","kind":"質問","question":"私もそのように思うのですが、この防災行政無線というのは、もしかしたら、もうこれ以上、性能的には限界かもしれないというふうに思っています。区では、既に様々な方法を取り入れています。様々にＳＮＳも展開しておりますが、この中からテレビ・プッシュについて伺ってまいります。停電するとテレビは見られませんが、このテレビ・プッシュは自動表示されるのでしょうか。教えてください。","respondent":"平原防災体制整備担当課長","answer":"テレビ・プッシュのお尋ねですけれども、テレビ・プッシュはあくまでもテレビの電源を入れるというようなものですので、停電時には電源が入ることはございません。","id":"exchange-088"},{"speaker":"西村委員","kind":"質問・要望","question":"幾つかの自治体、都内ですと３１の自治体では、Ｊ：ＣＯＭの防災情報サービスを利用しておりました。初期費用以外に月３００円、未加入の方は月５００円がかかり、自治体と連携しているので、しながわテレビ・プッシュに近いサービスかというふうに思っています。このサービスでは、避難情報、気象情報など防災情報をテレビを自動起動して表示します。ご所見をお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"品川区におきまして、既存の電波形態といいましょうか、そういうようなものをいかに活用して、どのような形でお届けできるかというのは、いろいろなパターンを、私ども、今、研究させていただいておりまして。","id":"exchange-089"},{"speaker":"西村委員","kind":"提案","question":"ぜひともお願いしたいと思います。例えば、どこに避難すればよいのか分かるチャットボットの活用を以前ご提案させていただきましたが、先ほど、松澤委員の答弁でもありました民間アプリを活用したコンテンツにも期待をしております。会派からも要望しておりますが、高齢者、障害をお持ちの方には、特に防災無線が自動的に入る方法、例えばラジオの一斉配布などをご検討いただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"ラジオについてですけれども、現在、私ども、平成２４年度に事業を実施いたしました防災ラジオ、こちらはアナログ波対応ということもございまして、先ほど来ご説明しています防災行政無線のデジタル波に対応して、どのような形で、今後、機器といいましょうか。","id":"exchange-090"},{"speaker":"西村委員","kind":"確認","question":"過渡期だと思いますが、どうぞよろしくお願いいたします。次の質問に移ります。災害時に安否確認のために玄関のドアノブにリボンをかけるという例年よりも小さな訓練ですが、防護服で救護に向かう訓練も行われました。結果的に町会の多くの方が参加する訓練になりました。コロナ禍における今年度の防災訓練に関して、区内の状況、区のお考えをお聞かせください。","respondent":"大森災害対策担当課長","answer":"現在までのところ、例年と同様の規模で実施することは困難と考えておりますが、メンバーを限定するなど、新型コロナウイルスの感染防止に工夫した形で実施したい、このように考えているところです。","id":"exchange-091"},{"speaker":"西村委員","kind":"意見","question":"発展的に考えてくださっておりまして、ありがとうあります。続けることが大事だというふうに思いますので、このような状況ではありますが、できる範囲で自助、公助、共助に、取り組んでいきたいというふうに思います。最後に、駆け足ですみません、不燃化１０年プロジェクトですが、現在の申請状況と、また来年３月以降の支援制度の延長について、どこまで検討されているのか、お聞かせください。","respondent":"佐藤木密整備推進課長","answer":"不燃化１０年プロジェクトにつきましては、当初、令和２年度までで終了の予定でしたけれども、東京都のほうでは助成事業につきまして、５年間の延長を決定しております。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３１３ページ、補助１６３号線整備、東急大井町線交差部工事経費、３２９ページ、公園・児童遊園維持管理費の防犯カメラ設置費、３４５ページ、防災体制整備費の中からになるかと思うのですけれども、災害時の受援体制ということについてお伺いしたいと思います。初めに、３１３ページの補助第１６３号線整備の東急大井町線交差部工事経費についてですが、大体１８億円余という区の負担があります。","respondent":"溝口道路課長","answer":"補助第１６３号線の高架下の工事の件です。これにつきましては、基本は高架部分のほうを区が出すような形になっていますが、当然、東急の附帯する工事もありますので、そこについては東急と費用を按分いたしまして、それぞれの協定に基づいて支払っているものです。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"大井町線沿線の騒音に対する苦情について、区に対してはどのような声が届いていたりするのか、あるいは、騒音の状況についての認識をお伺いしたいと思います。例えば、最近になって、急行などが走ったりしていますので、騒音の状況が以前にも増して強くなっているとか、そのようなことがあるのかどうかも含めて区の認識をお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"ただ、ご紹介いただいたように、各停から急行が通るということもあって、年に何件かになりますが、そうした声もいただいているところはあります。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"そういったこともあって、ここに来て、この騒音、何とかならないのですかみたいなお話が出ているのだと思います。そのような中で、こういったところの整備についての考え方というのは、区として整備していこうとしたときの考え方というか、どういったときに、例えば大井町線交差部みたいな道路拡幅とかというような話とは別に、あるのかどうかということをお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"これは区として新たな課題と捉えて、東急に働きかけていく必要があるかどうかについては、いろいろ東急と様々な機会を捉えて意見交換する場等々がありますので、そうしたところをまずは技術的あるいは費用的なところも含めて。","id":"exchange-095","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。ぜひそういった住民の声を受け止めていただいて、東急との話し合いを進めていただければというふうに思います。続いて、公園・児童遊園維持管理費の防犯カメラ設置費についてですが、現状、品川区内の公園・児童遊園、また防災広場、水辺広場等、現在、区立公園といわれているものは２６９か所、そこら辺での今現在の防犯カメラの設置状況についてお伺いいたします。","respondent":"高梨公園課長","answer":"公園・児童遊園等における防犯カメラの設置状況ですが、昨年度、１４８公園２３５台の防犯カメラを設置いたしまして、累計で、令和元年度末時点におきまして、２４４公園で４０３台の防犯カメラを設置完了しております。","id":"exchange-096","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"意見","question":"そうすると、若干まだ未設置のところがあるということになるかと思います。この未設置のところについて、現在、設置に向けての考えとか、また、設置がまだされていない理由等が特にあればお聞かせください。","respondent":"高梨公園課長","answer":"防犯カメラ未設置の公園の状況ですが、まず、設置していない公園は２５公園ほどありますが、現在、工事中で設置自体ができない公園が数か所あります。これは区の工事が終われば、設置を考えていきたいと考えています。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"今ございました電源等がなくてというところについてですけれども、これは例えばソーラー式の防犯カメラが今出てきているかと思います。今、未設置の公園への設置について、防犯カメラの性能とか、コストパフォーマンスとか、そういったことを含めて、ソーラー式防犯カメラで対応していくということへのお考えについてお伺いしたいと思います。","respondent":"高梨公園課長","answer":"電源のない公園における防犯カメラの設置についてですが、ご提案のソーラー式の防犯カメラにつきましては、かつては大体１週間程度は連続した録画時間を確保したいといったようなこと、あと、ソーラー蓄電池の性能等から不安があったものですから。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ区内全ての公園になるべく早く防犯カメラが設置できるようにというふうに希望いたしますので、最新のソーラー式防犯カメラと新しい技術、積極的に検討していただいて、導入を進めていただきたいと、このような思いですので、よろしくお願いいたします。このボランティア受け入れの手順を示したマニュアルの概要について最初に教えてください。","respondent":"中島防災課長","answer":"災害時の受援についてのお尋ねですが、災害時、業務全般につきまして、災害時対応マニュアルを作っており、その中でボランティアあるいはほかの自治体からの受入れについてマニュアル化をしています。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。それで、１つお伺いしたいのは、今年７月、豪雨で熊本などで災害が出て、復旧作業でボランティアの活動があったわけですけれども、やっぱり新型コロナウイルス感染症の関係で、県外から受け入れるということに対しては、熊本県としては若干お控えくださいというような動きがあったかと思います。今、区としてこの辺の感染症とボランティアの受け入れについての考え方をお伺いしたいと思います。","respondent":"中島防災課長","answer":"いずれにしましても、今回の計画にどこまで入れられるかは今後検討ですが、そういうしっかりとした感染対策等についても配慮してまいりたいと思います。","id":"exchange-100","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"意見","question":"ぜひしっかり前もって考えておくというか、決めておくべきことは決めておく必要があるかと思います。いざというときに混乱を来さないように、この点についてもしっかりとご検討をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"土木費の街路灯管理費の中の３１１ページの一番上にあります街路灯建替事業、ＬＥＤ型から質問をいたします。従来の街路灯からＬＥＤ型へ建替えた事業です。これで計画していた事業は終了したと考えていいのかどうかお答えください。そして、区内には何基の街路灯があり、全てを建て替えるにはどれほどの時間が必要だったのかもお聞かせください。","respondent":"溝口道路課長","answer":"今回予算に計上しておりますＬＥＤ街路灯への建替事業です。これにつきましては、もともと水銀条約、水銀灯を使ったランプが使えなくなるということで、５年間をかけて直してきたところです。平成元年度〔同日後刻に「平成２７年度」と答弁訂正あり〕から工事を進めてきています。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"従来の街路灯と比べますと、電力は約７５％削減、そして明るさもアップと紹介されていますけれども、そうなると、この明るさ、住宅街などではあまり使えないということになるのでしょうか。","respondent":"溝口道路課長","answer":"そういったものも見極めながら、令和元年度からのＬＥＤ化に向けて事業に計画的に着手してきたという経緯があるものです。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"その下にあります災害時消えない街路灯設置、３基、１４９万円余からの質問ですけれども、３基で１４９万４,９００円、１基当たり５０万円弱の計算になる街路灯ですけれども、高いのか安いのかは分かりませんが、こちらも計画した事業は全て終わったと考えてよろしいのか。","respondent":"溝口道路課長","answer":"これにつきましては、やはり災害時、停電が起きたときに、区民の方々が安全に避難所なり広域避難場所に逃げ込める、そういったところを目的に、停電地点でも３日間程度は夜間明かりが点いているような街路灯を整備していくという形で整備を進めておりまして。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"大きな災害時には、街路灯が消えてしまうわけですけれども、大変心強い街路灯であります。しかし、消えないと言っても、今、お答えがありましたけれども、点灯時間的には大体どれぐらい点灯しているものなのか。そして、もちろん昼間、日が照っているときなどは、もちろんそれは消えているわけであると思いますけれども、その点灯時間、大体どれぐらいもつものか教えてください。","respondent":"溝口道路課長","answer":"すみません、説明が足りず申し訳ありませんでした。今回設置したバッテリー内蔵の消えない街路灯につきましては、夜間のみ３日間程度。","id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"２０１１年３月１１日に発生した東日本大震災のとき、東京都町田市内の広い地域で電力供給が断たれ、夜になると道路には帰宅困難者があふれたそうであります。しかし、道路照明がつかなかったため、一時停滞施設等への誘導に支障が生じたそうであります。このたびの災害時消えない街路灯とは、この「消えないまちだ君」でしょうか。それともまた本区独自で作り上げたものなのかどうか、お聞かせください。","respondent":"溝口道路課長","answer":"ただ、全部が全部これが入らないところもありましたので、そういったところはこれと類似のものをつけておりますが、こういったものも１つのいい製品だという形でご紹介をされていたものですから、そういったものも使いながら、また同等な機能のものもありますので。","id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"準備は必要であります。区民の命や区の財産を守るためにも、一刻も早い準備をまたお願いしたいと思います。次に、３３９ページの中ほどにあります住環境改善促進事業の中の親元近居支援事業から質問をいたします。この三世代すまいるポイントとは、品川区に引越しをすることでポイントがいただける、そのポイントを生活の一部に活用することができるということですけれども、ご説明を願いたいと思います。","respondent":"森住宅課長","answer":"親元近居支援事業についてのお尋ねです。","id":"exchange-107"},{"speaker":"木村委員","kind":"意見","question":"三世代すまいるポイントというのは、親世帯、子ども世帯が、どちらかが品川区内に１年以上住まいをしていることが条件とありました。同居にしても、近居するための転居件数は増えているのかどうか。この事業、本区では、平成２３年から行っているとのことでありますけれども、他の区も行っている事業なのか、それとも区独自の事業なのか、お聞かせください。","respondent":"森住宅課長","answer":"実績につきましては、最近少し減少気味です。ＰＲに力を入れていきたいと思います。２３区では、三世代すまいるポイントとして出しているところはないですが、近居の助成をしている区は幾つかあるというふうに聞いてあります。","id":"exchange-108"},{"speaker":"あべ委員","kind":"質問","question":"私からは、３２５ページの市街地再開発事業、大井町駅周辺地区再開発事業と、それから、いわゆるＣ地区と呼ばれる地域などについても伺いたいと思います。それから、３４３ページ、防災対策全般と防災会議等について、そして３４７ページの備蓄物資についてもお伺いしたいと思います。","respondent":"多並都市開発課長","answer":"全体的なまちづくりマスタープランの中で、定住性であったり、人口であったり、クレーム等のいろいろな説明をその中で検証しているところでありまして、区としましては、そこの各単位の中での人口フレームは想定しないで進んでいる、その大きな中の進め方ということで。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"今のところ想定がないというふうなご答弁に聞こえたのですけれども、大井町は地形的にも歴史的にも道路の構造があまりよくない、鉄道を中心に発達してきたまちだと思います。開発で道路は少し拡幅したり、増やしたぐらいでは、なかなか地域としての交通キャパシティは大きく増えていかないのではないかと。この人口規模の視点がぜひ計画には必要ではないかと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"その事業を進めている中で、やはり例えばＣ地区だけではなくて、今回の広町地区、Ｃ地区、Ｅ地区等の今地域の方にまちづくりの検討をしていただいている地区がありますけれども、そのような機会を捉えながら、区としましては。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"Ｃ地区の話はこれからです。今、地域内では、例えば開発に早く同意すると、買取価格が上がるとか、有利になるとか、あるいは区が決定したことだから、もう反対しても無駄だというような話も出回っているようですが、こういったことはあるのでしょうか。人によって権利率が変わったりとか、区が既に何かを決定しているということはあるのか、そこをまず確認させてください。","respondent":"多並都市開発課長","answer":"Ｃ地区についてのところですけれども、現在は、地域の有志の方が勉強会という形で開いて、今後のいろいろな手法について検討している段階と認識しています。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"質問したことに答えてください。私が質問をしたのは、同意する時期によって交換率が変わることがあるかということと、それから、区が既に何かを決定しているのかという２点だけです。それ以外のことで時間を使わないでください。答弁をお願いします。","respondent":"多並都市開発課長","answer":"同意することで変わることはありません。もう１つが、区が早く決めたからといって変わることももちろんありません。要するに、今進めている事業の中で公平に進めていただくものです。","id":"exchange-112"},{"speaker":"あべ委員","kind":"確認","question":"確認したいことができました。ですので、区としては、この情報デバイトを埋めていくのが行政としての責任ではないか、特に再開発事業の収益構造ですとか、権利変換状況、他地域での地権者の方々がどのような提示がされて、結果的にどのようであったのかといったようなことを積極的に提示していくことが区の役割ではないかと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"やはり地域の方のお話をよくお聞きさせていただいて、今後のどういうまちにしていくかというのは、地域の方が主体で考えていくべきでもありますので、そこについてご不安がある方がいらっしゃれば、区としてやはりそこはしっかりお支えさせていただいて。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"かなり聞いていないことで時間が経ってしまいました。防災会議については、先日の本会議の中で女性の人数がまだ３人ということで、１０年近く求めてきたことがまだ実現していなかったということは非常に衝撃でありました。これからは太陽光発電機をマンション等にも配備できるよう助成していくような考え方をぜひお願いしたいのですけれども、いかがでしょうか。","respondent":"中島防災課長、平原防災体制整備担当課長","answer":"防災会議につきましては、女性の委員の割合を国の目標値である３０％に至る方策の中で、委員の任命については様々考えていきたいと思います。停電時に太陽光発電について助成するですが、そこは検討させていただきたいと思います。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３２４ページの都市開発費に関連して、超高層ビルは防災対策にならないということについて質問をいたします。トイレも使えず、住民の大半が１週間以上、生活できなくなりました。目黒川沿いに超高層マンションが多数あります。この住宅棟の電気室は何階にあるのか伺います。超高層マンションが浸水で停電したら、生活できなくなるという新たな問題が起こると思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"これ以外の箇所についても同様なところが多いところですけれども、各地区とも、目黒川沿いに再開発事業、また事業を進めるということで、電気室に水が入らないように、防水板をハザードマップの浸水の深さに合わせながら設置するということで。","id":"exchange-115"},{"speaker":"のだて委員","kind":"質問・要望","question":"早急な対策が必要だと思いますが、先ほど、防水板を電気室に設置しているということなのか、これからしていくということなのか、そこの確認もさせていただきたいと思います。やはりこれ以上の新築はやめて、既存建物への対策を抜本的に強めていくことが必要なのではないかと思いますが、それぞれ伺います。","respondent":"多並都市開発課長","answer":"いずれにいたしましても、その現場の状況に合わせながら、今あるマンション等のビルについても、そういう内容で、より安全・安心できるような形で整備していかなければいけないというところで。","id":"exchange-116"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の答弁ですけれども、防水板は既に設置されているということで、浸水深に合わせてという話でしたが、先ほど紹介した２棟は３.０ｍから５.０ｍの浸水深になるということですけれども、電気室が地下にあって、防水板を設置したというのは、天井いっぱいまでの防水板ということになるのか、そこのところを確認させていただきたいと思います。","respondent":"多並都市開発課長","answer":"もう１つは、防災課とよく連携しながら、避難体制等はどのような形ですればいいか、その現象に合わせながら、その地域の住民の方が安心・安全にできるように進めていくべきというところで考えているところです。","id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"特に耐火性や耐震性などがありますけれども、以前の予算特別委員会でも耐震性について、超高層とそれ意外とでは違いがあるのかと質問したところ、区は「何ら変わりはない」と答弁しました。超高層再開発は防災対策にならないと思いますが、いかがでしょうか。そうした取組を区が支援していくことが、地権者だけでなく、地域住民との関係でも重要だと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そもそも今あるまちの中で老朽化建物であったり、耐震性のないマンションがあったり、そのまちの課題、または細い道路があって避難に困難だとか、そのような様々な課題を抱える中で、市街地再開発事業、まちづくりの中で改善していくということで。","id":"exchange-118"},{"speaker":"のだて委員","kind":"意見","question":"再開発を進めていると言いますけれども、それ以外の方法もあるということで、やはり地域の住民が立ち退きを迫られたり、周辺の住民に大きな影響を及ぼすということがありますので、そういった面でも低層での共同化を進めていくということが、やはり住民に理解されるまちづくりだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-119"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３０５ページ、交通安全啓発費、３４７ページ、防災行政無線管理費、同じく避難所管理費からお伺いしたいと思います。そこで、新型コロナウイルス感染症の影響で自転車が生活の移動手段となってきている現状を区はどのように捉えていますでしょうか。こうした現状を捉えて、今後の自転車利用について、区のご見解をお聞かせください。","respondent":"川口交通安全担当課長","answer":"東京都におきましても、自転車活用推進計画の見直しが図られているところでございまして、その内容を踏まえ、区としても対策について検討をしてまいりたいというふうに考えております。","id":"exchange-120"},{"speaker":"こんの委員","kind":"確認","question":"こうした新型コロナウイルス感染症も影響してということで、自転車の利用というところは、放置自転車の関係で徒歩というところだったけれども、これからは自転車を利用するという考え方で進んでいくということが確認されました。しかし、便利な移動手段ではありますが、自転車は車両の一部という扱いですから、きちんと運転マナーが守られないと大変に危険な車両とも理解をしております。","respondent":"川口交通安全担当課長","answer":"したがいまして、今度、第１０次品川区交通安全計画につきましても、今年度末で終了いたしまして、次年度からは第１１次計画ですので、引き続き自転車の事故防止対策については強化をする上での計画等の策定を検討していきたいというふうに考えております。","id":"exchange-121"},{"speaker":"こんの委員","kind":"提案","question":"次の質問にまいります。このデジタル化へ移行後、令和３年度中に今後の対策を決めていくという、現在検討されていることを承知しておりますが、この検討内容は、例えばＦＭ波を受信して自動的にスイッチが入るものについて、コミュニティＦＭでは、そういった機能を持たせることも可能だとするなど、区の見解は議事録でも確認をしております。","respondent":"平原防災体制整備担当課長","answer":"防災行政無線の放送をいかにしてお届けするかということについてですけれども、現在、防災行政無線のデジタル化に移行する工事に伴いまして、現行の防災ラジオについてはご指摘のとおりデジタル波を受信することはできないのですが。","id":"exchange-122"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、現在の防災ラジオをお持ちの方が、このデジタル化に移行後も、同じ仕組みでラジオを持てるような形で進めていただきたいと思いますが、もう一言、ご答弁をお願いできますでしょうか。","respondent":"平原防災体制整備担当課長","answer":"新たな防災ラジオですが、あくまでまだ検討中のものですので、これといったはっきりした形ではございませんけれども、平成２４年から大分年数が経ちまして、インターネット環境などの拡大もありますので、そういったところも踏まえながら。","id":"exchange-123"},{"speaker":"こんの委員","kind":"確認","question":"避難所管理費に関連して、総務費でも少しお聞きいたしました災害対策職員待機寮の職員の方の動きについて確認をしたいと思います。そこで、総務費の中でもお聞きいたしました災害対策職員待機寮の職員の方が、現在、１１９人いらっしゃるとお聞きしておりますけれども、その待機寮の職員の方の初動について、昨年の台風第１５号、第１９号の際には、どのような対応、どのような初動をとられたのでしょうか。","respondent":"中島防災課長","answer":"災害対策職員待機寮の職員につきまして、基本的には災害、風水害のときにも動員をしているところで、昨年の台風の際は、本部において情報収集、電話対応等も含めまして、本部のほうで従事しています。","id":"exchange-124"},{"speaker":"こんの委員","kind":"質問","question":"今のご答弁からいくと、本部でこの待機寮の職員の方の動きを、いわゆる指揮命令して動いていただくという理解でいいでしょうか。その動き方、どのような対応、行動をされたのかお聞きしたいと思います。","respondent":"中島防災課長","answer":"本部の中では、指令情報部というか、実際に防災課を中心とした指揮の中に、待機寮は動員しておりまして、本部の中で台風の対応のときは電話対応を行ったところです。","id":"exchange-125"},{"speaker":"こんの委員","kind":"確認","question":"１１９人余りの方々が全部そういう対応だったのかというところをお聞きしたいわけですが、要は、この待機寮の職員の方々は、この名目のとおり、災害対策に待機をしてくださっている職員の方ですので、災害時にどのような動きをしているのか、またどのような動きをすることになっているのか、そこら辺を確認したいと思います。","respondent":"中島防災課長","answer":"説明が不足して申し訳ございませんでした。１１９人、災害対策職員待機寮に職員がおりますが、基本的に風水害のときは、輪番制で大体１０名程度の職員が従事しています。ですので、昨年の台風のときは、その１０名の職員を中心に動員をかけたところです。","id":"exchange-126"},{"speaker":"こんの委員","kind":"質問","question":"風水害の場合、いわゆる台風や集中豪雨のときは、事前に災害が大体予測ができるので、対応もこれぐらいでというような形で、昨年の１０名程度の対応をとられたということですけれども、確かに震災のときには、どういう災害が起きるかというのが分かりませんので、どの程度の職員の方に動いていただくかということもあると思いますが、そうしたことがきちんと決められているのか。","respondent":"中島防災課長","answer":"実際、避難所連絡会議の方々と、主に係長級の職員を中心といたしまして、毎年、避難所連絡会議などでお会いする機会などを設けてあります。実際に避難所訓練、特に区内一斉防災訓練、そういう中で実際に顔を合わせてしっかりお互いを知る関係で訓練に取り組んでいるところです。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"３２３ページの密集住宅市街地整備促進事業、この中では大井五丁目・七丁目、西大井三丁目の道路の測量をするという話があったと思うのですけれども、それがどういう状況になっているのでしょうか。その考え方、どういう進め方を今後しようとしているのか、お考えをお聞きします。３つ目は、３２１ページのコミュニティバス導入です。なぜコミュニティバスというものが入ってくるのだろうか。","respondent":"佐藤木密整備推進課長、多並都市開発課長、鈴木都市計画課長","answer":"令和元年度におきましては、決算書の中の事業推進業務等委託という中に入っておりますけれども、こちらで大井。委員からお話がございましたが、今現在、地域の有志の方がまちづくりの勉強会という形で将来の方向性について検討されている段階です。コミュニティバスの導入目的についてですが、ご紹介いただきましたように、世論調査でも非常に住み続けたいという回答をいただく方が高い割合であった。","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"密集住宅市街地整備促進事業ですが、測量は終わったのですか。それがご答弁になかったのですが、それを基にしてどういう動きをしようとしているのか。なので、そういう手法も今後考えていくべきではないかと思います。私たちの思うものと、住民たちが必要だと思うニーズが本当に合っているのかというのは、やはり検証していきながら進めていただきたいと思いますが、いかがでしょうか。","respondent":"佐藤木密整備推進課長、多並都市開発課長、鈴木都市計画課長","answer":"今回、実施いたしました測量につきましては、いわゆる工事の前の測量というよりは、今現在、地域で５町会の皆様方と。大井町周辺のまちづくりにつきましては、やはりまちの課題や、まちの活性化等をよく見ながら、また地域の方のご意見をお伺いしながら。いろいろ声も寄せられている中で、やはり高齢化ですとか、子育て世代の多い地域、１１の指標を先ほどご紹介しましたが、そうした分析をしっかり行って。","id":"exchange-129"},{"speaker":"鈴木（真）委員","kind":"確認","question":"災害ごみ関係です。衛生費でもごみの問題を確認させていただきましたが、区のがれき処理について、地域防災計画を見ていきますと、その仮置場として、しながわ区民公園、鮫洲運動公園、あとは都の施設が幾つか出ていましたが、そういうところでは想定訓練的なものをやっているのかどうかということがまず１点です。それから、都の施設との間で何か協定でも結んでいるのかどうか、その辺を教えてください。","respondent":"中島防災課長、高梨公園課長、稲田土木管理課長","answer":"災害廃棄物に関する訓練については、具体的な場所等も含めまして、特に実施はしていないところです。この対応といたしまして、特に平日の昼間であったりとか、保育園のお散歩等で訪れる方が多いという状況を鑑みまして。今後におきましては、今、公園課長も申しましたとおり、公園の配置とか、いろいろと周辺のまちづくりの状況等も考えながら。","id":"exchange-130"},{"speaker":"鈴木（真）委員","kind":"意見","question":"災害ごみの関係ですけれども、やはり衛生費のときも言いましたが、世田谷区、大田区での被害もあります。さっきもちょっと言ったのですけれども、鮫洲運動公園のところは、フェンスを張ってしまっていて、車が入れるところは、１か所ぐらい、ちょっと狭いところしかないので、いざというときに入れない。あれを見ていてもすごくいいと思ったので、ぜひそれはお願いしたいと思います。","respondent":"中島防災課長","answer":"災害廃棄物に関しましては、これまでは災害対応マニュアルを区のほうで作っておりまして、その中で関係部署と連携して運営に努めているところですが、具体的な内容の反映、あるいは災害廃棄物は災害の規模によりまして、総合的かつ計画的に対処すべきものですので。","id":"exchange-131"},{"speaker":"鈴木（真）委員","kind":"確認","question":"具体的にもう１か所、同じ鮫洲運動公園ですけれども、実は今朝も確認をしてきたのですけれども、あそこは通路の間に大型のオートバイが結構止まっているのです。今朝も１０台ぐらい止まっていました。万が一事故でも起きたときも心配もあるので、その辺、区も承知して整備をやっていると思うのですけれども、その辺のお考えをお聞きしたいと。それから、旧東海道の道路の問題で確認させてください。","respondent":"高梨公園課長、溝口道路課長","answer":"今、委員のご提案のありました方法等も含めて、解消に向けて前向きに検討していきたいと考えております。悪ければ直していく、そういったことを引き続きやっていくというのは大切だと思っていますし、今後どういう形で解消できるのか、それについては、また来年度を含めてしっかり検討していきたいと考えているところです。","id":"exchange-132"},{"speaker":"鈴木（真）委員","kind":"意見","question":"鮫洲運動公園のほうはよろしくお願いします。鮫洲運動公園に限らず、そういう公園があれば、全てのところで同じように考えていってもらいたいと思います。それから、旧東海道のところは、殊に駐車場が最近できているところなどは、その出入口がかなり凸凹になっているところもあるので、その辺、またご苦労ですがよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"確認","question":"私からは、３２５ページの大井町駅周辺地区再開発事業から広町地区のまちづくりとＣ地区について伺いたいと思います。その協定に基づき検討される中に、現庁舎跡地の活用も入っているのかというふうに伺ったのですけれども、私は資料で見たら、入っているということだったのですけれども、そういうことでいいのかということをまず確認したいと思います。","respondent":"多並都市開発課長","answer":"広町地区のまちづくりにつきましては、ＪＲ東日本と平成３０年に協定を締結して、共同で検討を進めているところです。このまちづくりの手法について、今、検討していますけれども、土地の再編という形で土地区画整理事業という形で再編をしていくということになります。","id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"とても丁寧に説明されたのですけれども、では、新庁舎ができた後、現庁舎は跡地という形になってくるのですけれども、そこは共同ではなく、区として検討していくということでいいのですか。","respondent":"多並都市開発課長","answer":"単独検討というのは、今度は区が再編した土地について、どのようなものを建てたり、どう利用していくか、土地利用をどうしていくかということを検討するものでありますので、単独検討というのは区が単独で行うものとご理解いただければと思います。","id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"現庁舎跡地は単独検討になるということですね。やっぱりそうした十分な収益、もうけが見込めると判断したＪＲ東日本と検討するというところでは、開発なわけですから、ＪＲ東日本のもうけのために現庁舎まで一緒に使われてしまうのかというところで、私はすごく心配したのですけれども、そうすると、開発と切り離して単独で考えていくということをもう１回伺いたいと思います。","respondent":"多並都市開発課長","answer":"土地の再編についてのことは先ほど説明しましたけれども、あともう１つは、まちづくりという観点で、大井町駅周辺がどういう形で進めていくべきかということで、その方針に従って、区ももちろん検討しますけれども、ＪＲ東日本がこれから施設検討をする際には。","id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっと話を聞いていると、やっぱり開発と一体に進められるのかという。私としては、切り離して考えていただきたいとずっと求めてきているとおりなのですけれども。区民の土地を何に使う、交換してまで何に使うのかということが明かせないというのはなぜなのか、そしてそれをなぜ区民に問わないのか、示さないのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後、まちづくり方針に従いながら、都市計画の様々な手法について検討しながら進めていくということで、１つの手法として、土地区画整理事業、また、具体的な建築物の施設計画を立てる際には、都市計画手法も考えながらやっていくことになりますので。","id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区有地は区民の土地なわけです。先ほどもおっしゃっていましたけれども、それがどう公平に交換されたのか、されるのか、そういうことを公表していただくと、ああ、なるほどというふうになるので、そういうものを公表すべきだと思いますし、また、土地を交換する駅前一等地は何に使われるのか、そして、現庁舎跡地の活用の検討内容なども公表していただきたいと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今後の進め方をもう少し詳しくご説明しますと、先ほどの土地区画整理事業、ずっとお話ししていますけれども、これはその手法の説明をしているものでありまして、その内容をどうするかというのは、まだお示しできる状況ではないということで。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱり新型コロナウイルス感染症のこういう最中で、検討とはいえどもすごく、１億円、２億円とかかってくるのがまちづくりの検討ですので、一旦ここは立ち止まって、コロナ対策に十分使うことを求めたいと思います。そして、Ｃ地区について伺います。まちづくり勉強会が行われているということですけれども、区としては、Ｃ地区は再開発として進めたいと考えているということでいいでしょうか。","respondent":"多並都市開発課長","answer":"その内容を共有した段階で、次にどういう事業手法になるかという進め方の順番ではないかということで、現時点ではまだ再開発事業等を区としてそのように進めるということで考えているものではありません。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"お話を聞きながらとか、今も共有しながらという段階ですと言うのですけれども、今、課長がお答えいただいているということは、都市開発課長ですので、都市開発なのですね。都市開発課は開発以外に何かほかに事業をされる所管なのでしょうか。そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"市街地再開発事業だけではなくて、いろいろ地区計画の中であったり、総合設計だったり、その土地の特性に応じて様々な手法が違いますので、区画整理もその中の１つですけれども。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地域の課題を解決するというところで、東小路などの防災性に課題があるところなどは、木密整備推進事業とか、そういうところでできるところだと思うのです。望んでいないのに自分の、そして家族の土地を奪われる。ぜひ住民の声を聞くというのであれば、デベロッパーを除いて、抜きにして住民の方とじっくり話して協力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"届いているとしたら、どういうようなお声があったでしょうか。３２３ページ、平成３１年にまちづくりビジョンが作成されて、令和元年度には、今、都市再生整備計画を作成していると伺っています。大きな枠組みの考え方の中で、庁舎機能も検討されていますけれども、第二庁舎について、工事は約３０年前、平成３年から平成６年、平成６年８月に竣工と伺っています。内訳等が分かればお尋ねします。","respondent":"松本河川下水道課長、品川財政課長、鈴木都市計画課長","answer":"区民の声ですが、直接私たちのところに現在のところはありませんが、設置にあたって、周辺の住民の方にこの工事を。第二庁舎の建設費ですが、おおむね７０億円となっております。それから、建設期間は、平成３年から平成６年までの３年間となっています。今後の予定ですが、この検討を進めまして、令和４年度には、いろいろハードルがありますので予定ではありますが、令和４年度末には事業認定を受けて。すみません、答弁を追加します。財源としましては、基金、それから一般財源、あと特別区債を発行しています。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"台風に間に合ったのでよろしいかと思います。立会川・勝島のまちづくりについては、勝島地区は人口が急増していて、高齢化率も区全体は２１％なのに、勝島地区は４.４％という大変若いファミリー層が多いところです。そして、それは当時の東京都の財調の算定に入っていたのでしょうか。入っていたとすれば、どれぐらいの割合が算定されたのでしょうか。お願いします。","respondent":"品川財政課長","answer":"これは防災センター等が入っておりますので、この防災の部分ということで起債が発行できるということで上げてあります。それから、財調の部分ですけれども、当時はこの起債部分の２５％分が財調でまかなわれておりました。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"７０億円のうち１４億円は起債して、そのうちの２５％、約３.５億円は算定されたということです。財源確保が重要だと考えていますが、どのように調達するのか、現時点でのお考えがあればお願いします。もし仮に起債した場合、先ほどは２５％が東京都の財調の算定でしたが、現在もし同じように起債したとすれば、金額は置いておいて、どれぐらいの割合で算定されるのでしょうか。","respondent":"品川財政課長","answer":"ここの部分は毎年財調交渉の内容には入っていないのですけれども、財調の部分で結構これは変更になる部分になっているですので、今は５０分の１となっておりますが、今後、続くかどうかは、ちょっと見通しとしては難しいかと考えています。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"不確定な要素が多い中、ご答弁ありがとうございました。ところで、今、起債の話が出ましたが、なかなかこの辺の起債のことは難しいので、ちょっと教えていただきたいのですが、庁舎建設などにおける国や都の補助金、あるいは国や都の手当てのある、さっきの起債です、先ほど、東京都で５０分の１と言われましたが、特別区には、市町村とは異なり、なかなか難しい事情があるのかと思います。","respondent":"品川財政課長","answer":"財調のほうの特別交付金の中で、一部使える部分もあるのではないかということですが、これもはっきりと条件等が確定しているわけではないので、そういった部分もいろいろ活用できるところは十分活用しながら、庁舎建設の財源を獲得していきたいと、このように思っております。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"活用できるものは活用して探していかれるということですので、ぜひ研究、検討をして、財源を確保していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問・要望","question":"３４１ページ、借上型区民住宅、これは、決算書に１団地出ていますが、特優賃、これがこういう形で出てくるのは最後の最後ということで確認させていただきたいと思います。課長は東京都に品川区の代表として協議に行っていただいていると思うのですけれども、そういう意味において、どういう思いで、またどういう決意で行かれているか、改めてお伺いします。どういう進捗状況か、教えてください。","respondent":"森住宅課長、長尾建築課長、佐藤木密整備推進課長、川口交通安全担当課長、松本河川下水道課長、中島防災課長","answer":"借上型区民住宅につきましては、今年の２月末をもちまして、区内の借上型住宅全てを終了いたしましたので。今後についてもこの品川シェルターについては、引き続き周知等をしながら活用を図っていきたいと考えております。区としましても、この取組については引き続き取り組む必要があると考えています。こちらにつきましては、道路交通法の第３８条におきまして、車両等が横断歩道のところで横断しようとする歩行者があるとき。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回ぐらいやって終わりましたということを伺って、だって、私、１０年ぐらい伺っているのです。もう１回言います、看板とかを立てても止まらないですから、行ってしまいますから、今までやっているわけですから、ぜひそこをやっていただきたいと考えていますので、よろしくお願いします。ですから、上の収入、上限を、私はもう変えてもいいのだと思うのですけれども、その辺はいかがでしょうか。","respondent":"森住宅課長、川口交通安全担当課長","answer":"区民住宅の使用料につきましては、上限として、２人、３人、４人という家族の中で決めさせていただいているところでございまして、今後、区民住宅の中で使用料について議論があるときには。区といたしましては、今は区の公式のＬＩＮＥアカウントですとか、いわゆる情報発信ツールが非常に充実しておりますので、警察以上の情報発信能力を持っているというふうにも認識しております。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問・要望","question":"本当に。ルールを守って横断歩道を渡っているだけではないですか。ここだけは知恵を出していただいて、もう課長が担当しているか、品川区でいう湾岸警察も入れて、交通課長等と話していただいて、もう横断歩道は止まるという形にしていっていただきたいと思いますが、改めて、あと１年半の間に、どういう形でやっていっていただけるかという思いは、これはお伺いしたいので、よろしくお願いいたします。","respondent":"川口交通安全担当課長","answer":"今年度、第１０次品川区交通安全計画が終わります。第１１次でありますけれども、そこの中の具体的な講じようとする施策の中にも、この部分については入れ込めないのかということで検討していきたいというふうに考えております。","id":"exchange-149"},{"speaker":"安藤委員","kind":"質問","question":"３２１ページ、特定整備路線、コミュニティバス、時間があれば、３２５ページ、大崎駅周辺地区再開発事業について伺います。特定整備路線です。この特定整備路線は、区長が手を挙げ、３路線が特定整備路線に選定され、事業化されました。補助第２９号線と放射第２号線について、見込まれる総事業費、またこれまで取得した道路用地の取得率と総面積をそれぞれ教えてください。","respondent":"鈴木都市計画課長","answer":"補助第２９号線の用地取得率、これは令和２年４月現在になりますが、補助第２９号線は６区間に分けられておりますが、全体の平均としては、４月１日時点で２１％、放射第２号線の用地取得率が３２％です。","id":"exchange-150"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり住民が反対していますから、全然進んでいないということと、６０２億円と２２６億円、膨大な税金だということです。伺いますけれども、コロナ禍という社会情勢の変化に鑑み、事業を中止して速やかに廃止するよう都に求め、住民要望実現のために活用するべきではないでしょうか。区長に伺いたかったのですが、区長はいないので、ぜひ責任ある方がご答弁いただければと考えています。","respondent":"鈴木都市計画課長","answer":"これは特定整備路線と一緒に、周辺の耐震化、不燃化、区が行っている事業とセットで重層的に行っていく必要があると。これはコロナ禍においても立ち止まらずに、しっかりこの取組は進めていかなければいけないという認識です。","id":"exchange-151"},{"speaker":"安藤委員","kind":"質問","question":"そう言いますけれども、私は膨大な税金と時間と労力をかけ、今いる人を追い出す。南北の延焼遮断道路を整備、防災を強調しますけれども、風が東西に吹けば、また同時発火すれば何の意味もない道路です。火の粉や車両閉鎖の可能性も考慮にそもそも入っていない。区は、道路反対、そして税金の使い方を変えろという粘り強い区民の皆さんの声をどう受け止めているのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区としては、東京都と一緒に重層的に防災性の向上、地震に対する備えをしっかり取り組んでいきたいです。","id":"exchange-152"},{"speaker":"安藤委員","kind":"提案","question":"次にいきます。ワークショップでの住民の意見はできる限り反映していただきたいわけですが、人数的に限界もありまして、人選する町会もなかなか一苦労なのではないかと、コミュニティバスに強い関心をお持ちで、そういう意見を言える方を選出するのはなかなか苦労しているのではないかと思うのですけれども、この場でも、私が地元の地域から伺っているルート案、以前の提案について何点か伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"コミュニティバスについて、まず大崎ルートですが、大崎ルートにつきましては、導入効果の高い区域は、先ほどからご説明しておりますが、１１の指標を用いて地域の選定、さらには、ルート選定にあたっての７つの視点ということも決めて行ってあります。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"併せて質問してしまいます。２点目が、新しいルートですけれども、例えば区が認定している交通不便地域でありながら、上大崎がルート候補から外れているのですけれども、これはやっぱり強い要望があるのです。途中で池田山公園とか、上大崎なども通るというルートも、具体的な要望として伺っているのですが、こういうルートを検討していただきたいのですが、いかがでしょうかというのが２点目です。","respondent":"鈴木都市計画課長","answer":"これ、先ほど来、ご説明している１１項目の指標の中の重み付けを２倍にして重点的に検討を行っている指標の１つなのですが、やはりその遠い地域も面積が大きいところ、小さいところ様々でございまして、決して上大崎ルートも点数を付けて効果的な地域を選出するにあたって。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ住民の声を取り入れ、１日も早く区民に便利なコミュニティバスの運行を実現していただきたいと思います。区は当該地区について、３名くらいの未同意はやむを得ないという認識なのでしょうか。伺いたいと思います。１００％同意までは認可しないよう都に働きかけるよう求めますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"これまでも準備組合の中では権利者の皆様とよくお話合いをしながらここまで続けてきたところもありますので、法令の規定も踏まえて、今回の申請に至ったという受け止めで、区としてもそういう受け止めで計画的なまちづくりということで進めていきたいと考えているところです。","id":"exchange-155"},{"speaker":"たけうち委員","kind":"確認","question":"３０７ページの有料自転車等駐車場運営費、また同じページのシェアサイクル事業、３２３ページの不燃化１０年プロジェクト、３４７ページの避難所管理費について伺います。それから、不燃化１０年プロジェクトについては、いろいろ質疑があって確認ですけれども、東京都は延長していくとなっていますが、品川区では、９地区は継続、それから新しい地域も含めて東京都に申請を出している。","respondent":"川口交通安全担当課長、稲田土木管理課長、中島防災課長、佐藤木密整備推進課長","answer":"下神明駅周辺には、確かにおっしゃるとおりそういうものがございませんので、今後もシェアサイクルポート。職員にヒアリングなどを行いまして、やはり災害対策本部の運営、あるいは避難施設の周知、避難場所の運営要領などが課題ということで。それを受けまして、品川区といたしましては、現行の整備地区および新しい地域も視野に入れまして。","id":"exchange-156"},{"speaker":"たけうち委員","kind":"質問・要望","question":"使っていない部分をどう有効活用できるのかという視点で考えてもらいたいと。東京都の土地なので、そことの調整も要るのだと思いますけれども、これは要望にします。不燃化１０年プロジェクトについては、そろそろ東京都からも返事がないと、やっぱり地域でも、多分皆さん、いつ終わるのでしょうかと、本当だと今年度末なのですね。これはぜひお願いしたいので、ここはもう１回答弁をいただきたいと思います。","respondent":"佐藤木密整備推進課長、中島防災課長","answer":"令和３年度以降の不燃化特区の件ですが、委員ご指摘のとおり、我々も窓口等で来年度以降どうなるのかというお問合せを受けておりまして、東京都のほうにもそういった実態を含めて申入れをしておりますので、地区が決定次第。風水害の避難行動の訓練、検討していたところも新型コロナウイルス感染症の関係で少し滞っている部分もありますが、課題認識として持っておりますので、引き続き調整してまいります。","id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問・要望","question":"不燃化１０年プロジェクトのほうは、我々も我々の立場で東京都にぜひ早く返事をくれということでやってまいりたいと思いますので、ぜひ積極的に頑張っていただきたいと要望します。これも要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"大沢委員","kind":"質問・要望","question":"３４７ページ、避難所について伺いたいと思います。冗談はさておいて、３４７ページの避難所からお伺いさせていただきたいと思いますけれども、いろいろと調べて、事務事業概要等々も見せていただいたのですが、内部障害者、オストメイトの方の避難所における対策、対応は、どのように行われているのか教えていただきたい。","respondent":"平原防災体制整備担当課長","answer":"一部そのような施設がないようなところもありますけれども、それに対応した仮設のものになってしまうのですが、それで今、代用させていただいているところです。こちらはトイレの状況になりますけれども、こういったような形で現在対応させていただいているような状況になります。","id":"exchange-159"},{"speaker":"大沢委員","kind":"質問","question":"だれでもトイレということで、ストーマを洗う部分のところということで心得ておりますけれども、ストーマ装具等々の備蓄はされているのですか。","respondent":"平原防災体制整備担当課長","answer":"こちらにつきましては、学校設備ということもございまして、学校の備蓄品といいましょうか、通常の備品を活用するということになっておりまして、現状では災害用備蓄品として、だれでもトイレ用のものを準備しているものはございません。","id":"exchange-160"},{"speaker":"大沢委員","kind":"意見","question":"「ございません」とはっきりおっしゃいましたけれども、やはり内部障害の方はなかなか障害をお持ちだということが、手帳は持っていらっしゃるけれども、なかなかお困りのことは多かろうと思いますし、ましてや腸とか膀胱の罹患が非常に高かろう、成人病としては多いところだと思うのですけれども、そこのところでやはり用意しておく必要が私は多くあると思いますし、やっぱり性質上。","respondent":"平原防災体制整備担当課長","answer":"例えば区民避難所なのか、福祉避難所なのか等々、いろいろなことを検討させていただきながら、そういったものの配備を進めていきたいというふうに考えてあります。","id":"exchange-161"},{"speaker":"大沢委員","kind":"提案","question":"そこで１つ提案なのですけれども、内部障害者向けのポータブルのトイレ、これは普及というか、近年出始めております。これで３４７ページの質問については終わります。国なのでそうそう区は手をつけられるという問題ではないとは思うのですけれども、そこのところをどういうふうにお考えになっていらっしゃるか教えてください。","respondent":"高梨公園課長","answer":"今、委員お尋ねのとおり、林試の森公園は区内の貴重な緑を生み出す場所ということで、区としても認識しています。特に緑の少ない荏原地区にとっては、貴重な緑であるというふうに感じております。","id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"自転車の事故もということなのですけれども、やはりコロナ禍ということで、最近、多く見るのが、宅配の自転車業者の方、あの方たちは時間に追われている部分もあるのですけれども、意外と交通ルールに、先ほどもルールなのかマナーなのかと藤原委員からもありましたけれども、怖い運転をされていて、ヒヤリとするようなところもあるのですけれども、その宅配業者の方たちに対する安全教育というか。","respondent":"川口交通安全担当課長","answer":"これにつきましては、今、シェアサイクルの担当者が、他区、同じ実施をしている区の会議が定期的にありますので、その中で事業者に対してしっかりそういう指導も併せてやってもらいたいという要請を区からもしています。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"交通安全について業者の方たちに伝えていただきたいと考えています。先ほど来、「交通安全」という言葉が出ていますが、ここに表記をしてある「交通安全計画」とありますけれども、私は「交通安全」というのは、どうもあまり解せない言葉で、「交通安全計画」ではなくて、「交通安全化計画」ではないのでしょうか。","respondent":"川口交通安全担当課長","answer":"ちなみに、参考ですけれども、いわゆる交通切符を適用した自転車の取締り、赤切符で取締りをされた件数が、平成３０年には１,５６３件であったものが、令和元年は１,９６０件ということで。","id":"exchange-164"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、やはり標語、スローガンは交通安全でもいいのですけれども、ここのところを一ひねり、二ひねり変えて、「交通安全化運動」、交通の安全に対する何とかというふうに変えていただいて、交通の安全と言っても、交通安全というのは何がなんだか意味をつかみかねるのですけれども、そこのところをどういうふうにお感じになられますでしょうか。","respondent":"川口交通安全担当課長","answer":"委員ご指摘の「交通安全化」なのではないかですけれども、我々は１つの名詞的に「交通安全」と申し上げておりますけれども、やはり「交通安全」の中には、それぞれ、例えば交通の円滑化を図ることによる交通安全もありますし、交通の障害に基づいて。","id":"exchange-165"},{"speaker":"大沢委員","kind":"質問","question":"これは東京都の警視庁なり、あるいは上の役所から出た言葉なので、私ごときが言っても、どうにも変わる問題ではないのですけれども、やはり交通安全という交通に対する安全性をかもし出すには、やはり表現を変える必要はあるのではないか。もうちょっと交通に対する危機感を持ってもらえるような表現に変える必要があるのではないかと私は思いまして、この質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３３３ページ、しながわ水族館、それから３２４ページ、都市開発費の中で京急連続立体化とか、品川駅南地域、大井町駅周辺関係に触れたいと思っています。初めに伺いたいのは、今、品川区は都市型観光といろいろ言っています。集客が必ず必要だと。なぜこのようなことを言うかというと、例えば台東区、今、台東区に来る方は、来客数６,０００万人だと言われています。これも１つの仕掛けなわけです。","respondent":"高梨公園課長","answer":"都市型観光、集客についてのご質問ですが、水族館という切り口でお答えします。しながわ水族館は、品川区を代表する観光施設であると考えておりますが、開館から来年で３０周年を迎えるということと、周辺に大分水族館が３０年前に比べて多くできました。","id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"シンボル的なしながわ水族館になっていただきたいと考えていますけれども、その中で何点か話をさせていただきたいのは、現在の管理許可制度、これに基づく基本協定、これはやっぱり見直すということは非常に考えてほしいというのが１点。それは近隣の方の話もよく分かっていますけれども、それぐらいのことも含めて検討していただきたいと思うので、水族館のところはもう１回お答えいただきたいと思います。","respondent":"高梨公園課長","answer":"営業時間のご提案につきましては、委員からもありました周辺の住居等との関係もありますが、３０年経ってきたといったところもありますので、そういったところを既存の考え方にとらわれないで、また周辺の方々ともお話合いをしながら検討を進めていきたい。","id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"決定をして、今、買収行為もスタートしていくということでありますけれども、必ず高架があるので高架下、それから駅舎のデザイン、それから駅前広場、地域の方からも意見を聞いて、いろいろパースを引いていただくということにこれからなっていくのだろうと思っていますけれども、ぜひそのときに、いろいろ考えていただきたいのは、地域の人としては、もう決まっていて、南地域と連動してくるとなると。","respondent":"中道まちづくり立体化担当課長","answer":"今お話のございましたゴジラの点につきましては、品川区で旧東海道、八ツ山といったところで登場したといったところで、非常に北品川に関係の深いキャラクターであり、また幅広い方に親しまれているキャラクターというところで、非常に魅力あるキャラクターですが、その一方で。","id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確かに地域でも、上陸して八ツ山を踏みつけて壊してしまった、まちを破壊したのはゴジラだという意見もあるのは事実でありますけれども、やっぱりそれはそれで１つの考え方もあるので、ぜひ考えていただきたいと思います。では、あそこは品川駅から１０分圏内だけれども、そこにテナントがあったから入るのか、それがずっと後々になってどういう状況になるのだということも考える。そこは一段超えると。","respondent":"中道まちづくり立体化担当課長","answer":"そうした東京都の敷地に対しましては、区が間に入りまして課題を解決していくとともに、やはり品川浦といったところで船宿等の観光施設がありますので、そういった活用も地域と一緒に考えていきたいと思います。","id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/470470?Template=document&Id=1492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":123965,"voices":401}},{"id":"r02-20201013-4","meetingId":"r02-c-settlement","date":"2020年10月13日","dateIso":"2020-10-13","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","topics":[{"id":"topic-01","title":"令和元年度品川区一般会計歳入歳出決算","agenda":"令和元年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、３６７ページ、学校ＩＣＴ推進経費、あとは３５１ページ、８３運動経費についてお伺いいたします。その前に、ページが見つからないので、所管がずれるかもしれないので、その場合、またおっしゃっていただきたいと思うのですが、品川区は宮古市と災害時相互援助協定を結んでおりますけれども、これまで宮古市と品川区の児童が交流を持つ２泊３日のツアーをやってきたと伺っています。","respondent":"有馬庶務課長、工藤指導課長","answer":"この事業は、青少年育成活動、親子体験交流事業ということで実施していると捉えております。毎年親子１０組２０人程度は行っているのではないかということです。今年度はコロナの関係で行けないという情報を聞いております。タブレットの活用での持ち帰りのところですが、配備いたしますタブレットにつきましては、携帯電話と同じ通信ということで、学校の中での活用においても、もちろん校内・校外、また家庭においてもインターネットにつながる環境ですので。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"確認","question":"宮古市のほうは、ほかの事業で海外研修といったものもあるかと思います。それで、タブレットはもう一度確認したいのですが、そうすると、持ち帰りが前提になるということでよろしいのでしょうか。それとも、まだ学校での判断もしくは保護者の判断で、それぞれ持ち帰っていただければというような方向性なのでしょうか。","respondent":"工藤指導課長","answer":"タブレットにつきましては、持ち帰りが前提でということで検討を進めているところです。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"提案","question":"続けて８３運動についてお伺いいたします。８３運動については、予算特別委員会の中で何度か提案をさせていただきました。コロナ禍ということでありますので、大きな進捗というのはないのかと理解していますけれども、８３運動で今年度進んだということが何かあればお聞かせください。","respondent":"有馬庶務課長","answer":"いろいろとご提案も頂きました、８３運動の日を設定するとか、８３運動週間というのは、８３運動が、８月３日が夏休みであるということや、いきなり週間を設定するのは難しいということで、冒頭申し上げましたけれど、ポスターということの話が出ましたが。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"特にまたコロナの中で、不審者情報などが相次ぐ中で、８３運動の事業というのが、さらに大きな意義を持っていくと理解しています。それを少しずつ改善していきたいというような発言があって、今、チラシをお配りされるということですので、これまでのＰＴＡに対しての周知とは、また、より１つギアを上げて周知されるというような理解でよろしいのでしょうか。","respondent":"有馬庶務課長","answer":"今までは８３運動推進委員会から、啓発グッズでこんなものを作ってほしいというようなことで、それに対応して、ではそうしましょうということで、それをお配りしていたというような形での、本当の側面支援という形でしたけれども、一歩踏み込んで。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"意見","question":"運動に参加する人数をどんどん増やしていくというのは、なかなか難しいことなのかなとも思うのですが、特に８３運動というのは、非常に大きな負担をかけるようなものでもなくて、非常に分かりやすく意義のあるものだと思いますので、ぜひ引き続き、これは積極的に取り組んでいただければと思います。何かあればご意見をお聞かせください。","respondent":"有馬庶務課長","answer":"コロナ禍でいろいろと行事ができなかったところもありますので、一応、心のケアではないですけれど、何か思い出づくりということに取り組んでいこうということで考えているところです。","id":"exchange-005"},{"speaker":"松澤委員","kind":"確認","question":"私からは、３６７ページ、学校ＩＣＴ活用経費、３６９ページ、学校システム運営費についてお伺いいたします。私自体、教育ＩＣＴが詳しく分からないので、確認しながらの質問になることをお許しください。そこで、品川区におけるＩＣＴ環境整備は現在どのように進んでいるのかと、推進校で全員配付しているタブレットが壊れてしまった場合の補償などがどのようになっているのか、教えてください。","respondent":"篠田学務課長","answer":"機械が壊れてしまった場合ですけれども、区から貸与している機械ですので、例えば壊れてしまったということでお預かりして、その間、代替機をお渡ししてお使いいただくというような形で対応しています。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"代替機を渡すことは、壊した家庭が負担するということはないということでよろしいでしょうか。","respondent":"篠田学務課長","answer":"例えば故意で、明らかにいたずらをして壊してしまったなどということがなければ、そういった確認が取れなければ、基本的には公費で全て対応しています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"ただいま、無線ＬＡＮを全て配置という話がありましたけれども、国が目指しているのは、教科指導における教育用のコンピュータ導入というのがあります。そこでお聞きしたいのが、パソコンを導入する学校もある中、タブレットを品川区が選んだ理由と、タブレットにはセルラーモデルとＷｉ－Ｆｉモデルというのがあります。通信料、交信料がかさんでしまう。そこでお聞きいたします。この２点をお願いします。","respondent":"篠田学務課長","answer":"タブレットを選んだ理由ですけれども、パソコン等ですと、１年生等小さいお子さん方ですと、取扱いの関係で、やはりタブレットのほうがなじみやすいだろうということで、またこれから先の時代を考えたときに。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"分かりました。ＬＴＥが悪いなどではないのですけれども、セルラーモデルと比べてＷｉ－Ｆｉモデルというのは、たしか調べたところ、２万円ぐらい安いのです。こういった図書館でのＷｉ－Ｆｉの活用などを私は考えましたが、話し合いの場でどのような議論がされたのかというのが１点。そして、家庭でのインターネット環境についてのアンケートの結果が分かりましたらお願いいたします。","respondent":"篠田学務課長","answer":"したがいまして、今回の契約におきましても、一般的な使用料から考えると、かなり割安な回線の使用料となってきているところですので、Ｗｉ－Ｆｉモデルですと、例えばご自宅に持ち帰ったときに、環境がなければ別にまたポケットルーターなどの貸出しが必要になったり。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"全国どこでも、どこの学校にいても、最新の質の高い学習環境を利用できる仕組みの整備が求められております。品川区でも、この教育クラウドを活用していくと思いますが、グーグルやマイクロソフト、最近ではＧｏｏｇｌｅ Ｃｈｒｏｍｅが活用されていると聞いておりますが、例えばＣｈｒｏｍｅｂｏｏｋとまなびポケットを組み合わせるなど、品川区での今後の予定などがありましたら教えてください。","respondent":"篠田学務課長","answer":"今お話のあったような基盤の関係につきましては、当初はなくても全体の管理ができるのかということで考えていたところではあるのですけれども、やはり様々共有フォルダの作成など、いろいろと考えていくと、何らか対応していくことが必要だろうということで、現在。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ、子どもたちにとって何が一番いいのかを考えて活用していただきたいと要望いたします。これは家庭の問題だとは思うのですけれども、学校側から何かそういうものに向けて取り組む課題やお考えというのはありますでしょうか。","respondent":"工藤指導課長","answer":"今後、宿題等を学校、教員から出す場合には、ｅライブラリアドバンスを活用することで、宿題はそれによって行う。そういったことで、家庭学習・自学自習を習慣化していくことにも取り組むというところで検討を進めているところです。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"宿題をタブレットでやるようになれば、子どももやはり開かなければいけないという部分で、大変いい取組みだと思われます。最近では、情報化統括責任者であるＣＩＯというのですか、最高情報責任者を置く民間企業が増えていると聞いております。そこで、雇用や勤務形態は様々ですが、品川区におけるＩＣＴ支援員の現状と今後の取組みについて教えてください。","respondent":"篠田学務課長","answer":"人材の関係があるものですから、なかなかいきなりすぐに増やすというのは、難しい部分はあろうかとは思うのですけれども、できるだけ厚みを持った形での対応をしていきたいということと、また来年度においても、さらにそれを一層継続して。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"続きまして、学校システム運営費からお聞きいたします。そうすると、私は友達が周りにいないと連絡帳を預けられないなどといった声も聞いたことがありますので、電話で済む話なのですけれども、そういった部分で困っている、要はＳＮＳでやってほしいです。欠席届をオンラインでやり取りするとか、学校プリントのデジタル化を含めた現場の先生の負担軽減等の考え方も含めてご見解をお聞かせください。","respondent":"工藤指導課長","answer":"そういったことも含めて、研究も含めながら、今、検討を進めているところではあります。ですので、保護者の方のニーズも踏まえながら、また学校の教員の働き方改革という観点からも、効率よく連絡がしっかりとできるようなところを検討してまいりたいと考えています。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問・要望","question":"確かに、いきなりデジタル化で全部デジタルというのは、私もどうなのかとは正直思っております。紙と一緒に共存していくという考え方も確かにすばらしいと考えています。アプリや支援ツールというものを活用して、ＩＣＴ教育に対する負担を軽減するためにも改善していただきたいと考えますが、先ほどとかぶってしまいますけれども、ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"教員については、採点を自動機能で行いますので、子どもたちの進捗状況をすぐさま確認することもできますので、そういった意味で業務改善、また授業改善に資することができるとも考えておりますので、そういった活用についても含めて様々検討していきたいと考えています。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"情報化がどんどん進んでいく中で、ご苦労されている教育委員会の皆さんと先生たち、特に先生たちが、コロナ禍というのもありまして、いろいろな負担を強いられていると思います。そういった方々をしっかりと把握してフォローする、そういった環境の整備を要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"３６１ページ、マイスクール運営費、３６７ページ、学校ＩＣＴ活用経費から関連してお伺いいたします。昨日の今日でありますので、まだ詳細はこれからかと思いますが、昨日１日、オンライン授業がどのように行われ、そしてまた、先生の様子、生徒の様子、またお声がありましたらお聞かせいただきたいと思います。１日の授業が、全てオンラインが活用されたのかということもお伺いいたします。","respondent":"篠田学務課長","answer":"本日からは本格的に授業で取り組むと聞いていますので、まだ詳細を聞き及んではいないのですけれども、今日から活用されているです。","id":"exchange-016"},{"speaker":"新妻委員","kind":"確認","question":"そして９月には一斉下校後の訓練ということで、保護者を交えてオンラインでの安否確認をするということで、６月、７月、９月と、このように取り組んできた成果が、今回のオンライン授業に活かされてくるのかと考えています。今回この学校がオンライン授業を展開するにあたっては、これらの準備が活かされてきていると認識するのですが、区の見解を伺います。","respondent":"工藤指導課長","answer":"委員にご指摘いただきましたように、お話しいただいたところは、早くから計画的にＺｏｏｍを活用するというところを進めていたという事例であると私どもも認識しています。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"ＩＣＴと言うと得手不得手があったりというところもありますが、地域の力というのはすごいということも実感しておりますので、これからも様々活用していただきながら、強力に進めていただきたいと思います。改めて、マイスクールに通いたい人は、どういう段取りややり取りがあって、マイスクールに入室というのでしょうか、マイスクールに入っていくのかという流れをお知らせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"所管は教育総合支援センターですので、そちらのＨＥＡＲＴＳを中心とした指導主事にも相談して、これからの道筋について考えてまいります。本当に適応指導教室がよろしいのか、学校の中で対応できるのか、その辺の検討からまず始めます。","id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"前期の文教委員会の所管事務調査でひきこもりを取り上げた際に、教育委員会には、マイスクールの現状、人数等々も含めて確認させていただきました。３学期になると、空きがなかなか少ないというようなことも伺いましたけれども、現状、この３つのマイスクールに、どれだけの人数が通っていて、また待機者というのでしょうか、見学したいという人がどれだけいるのかということをお知らせください。","respondent":"矢部教育総合支援センター長","answer":"マイスクール五反田、マイスクール浜川につきましては、それぞれ現状で、昨年度末で、五反田のほうが２６名、浜川のほうが十数名という報告を受けてあります。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"マイスクール八潮はもう定員がいっぱいであって見学者も数人いる。五反田と浜川に関しては、少しまだ余裕があるという状況でよろしいのでしょうか。だけれども、見学を申し込んではいるものの、空きがないということで、年度初めの来年４月まで待ってほしいと言われたと。今後のマイスクールの在り方やニーズ等を踏まえて、マイスクールの拡充等も必要かと思いますが、区の見解をお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"小学生につきましては、委員ご指摘のとおり、八潮で対応しています。先ほどもお話に出ましたが、人口が増加しているというところで、ニーズの強さ、大きさは感じております。今後ともこの３教室の在り方について前向きに検討してまいりたいと考えております。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"３５５ページ、生徒指導対策等経費に関連して、中学校の理不尽な校則についてお伺いしたいと思います。質疑後、中学生の保護者から、見直しを求める質問への共感、さらに、理不尽な校則の実態など、様々な声が届きました。今回は特に髪形に絞って伺いたいと思います。校長会について、誰がいつどんなお話を何度もしているのか、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"それを踏まえまして、見直しのことですが、昨年も含めてこれまでも、校長会で教育長より見直しの指導はございました。現在、生活指導主任会でも話題に挙げて、見直しの検討をしています。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"私が伺った中学１年生と中学３年生の生徒は、生徒同士の中でも、「ツーブロック禁止っておかしいよね」とか、「サイドを伸ばすのはおしゃれだから禁止って納得できない」など、生徒の中で様々話題になっていることが分かりました。生徒会でこうした意見を提出した学校はあるのか、伺いたいと思います。先ほども伺いましたが、教員の中ではどんな議論が実際にされているのかも伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"生活指導の中ではどのようなお話があるかというご質問ですが、先般でも私のほうで聞いたところは、校則の目的、小学校も含めてですけれど、何でここにこうあるのか、また共通理解をどのようにするべきかというような議論が交わされております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"提案","question":"ツーブロックという具体的ではないが、見直しのお話をしているということですが、学校の現場ではすごく具体的に禁止事項が並べられていますので、具体的に提案をすることが必要ではないかと思うのです。お伺いしますが、生徒の髪形禁止の不満の声は教育委員会にどのように届いているのか、どんな声があるのか伺いたいと思います。こうした姿勢が重要だと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"どちらにしましても、地域で今までの時代背景や子どもたちの様子を見て決めてきたことですので、そこはこれからも見直しのほうの働きかけを進めてまいりたいと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"見直しの働きかけは歓迎したいと思いますけれども、質問したのは、生徒の髪形についての不満の声は区教育委員会に届いているのか、どんな声があるのか、改めて伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"失礼いたしました。児童・生徒の髪形についての意見については、私どもには聞こえてきておりません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会に届いていないというのは、現場の声が届いていないと思います。生徒の声を吸い上げ、区教育委員会にもその声を受け止めてほしいと思いますが、いかがでしょうか。実際に、保護者からも、納得がいかなくて教育委員会に電話をするということもよく伺います。声をつかんでいないというのは、あまりにも、生徒の声、保護者の声を軽視していると思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"真摯に受け止めてあります。生活指導主任会を２か月に１度ほど行いますので、そこで、今回の校則の見直しの話題の際にも、児童・生徒からどのような声が上がったかというのは、その中では協議されていることと考えております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"提案","question":"本会議の質問の後、複数の保護者からお話を伺いました。それで、「従わないと内申点に響きますよ」と言ったそうです。ポニーテール禁止というのは本当ですか。この方は今、高校生になったので、今の中学校がどうかまでは私は確認しておりませんけれども、ポニーテール禁止について教育委員会は知っているのか、なぜ禁止なのか。私はおかしいと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"繰り返しになりますけれども、これまでの決まりの設定にあたっては、各学校が吟味して作成していると考えておりますので、委員がおっしゃるとおり、見直しはまだこれからも続けるよう働きかけてまいります。ですから、そういったことを把握して、学校は適切に指導していると思いますが、先ほど教育総合支援センター長からもありましたとおり、いわゆる内申に関わるであるなどというのは正さなければいけないと思いますけれども。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私もこの質問をするにあたって、ポニーテールというのがそもそもどういう髪形なのか聞いたところではあるのですけれども、結ぶ位置が上のほうにあるということでいいのですね。先ほどの説明だと、結ぶ位置が上だと黒板が見えなくなる。そんな理由で、主に女子生徒が自分の好きな髪形を禁止するというのは、理不尽だと思いますけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"そういった指導が理不尽ではないかというご指摘ですが、やはり指導というのは前後関係、教員と生徒の関係ももちろんありますし、また校則を含めたところは、当然、今、見直しを進めているところではありますけれども、そういったものが。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういう話の中で、どういう生徒との関係の中で、そういう指導が入ったのか、前後関係があるのは分かります。そして、大人が決めた校則ですから、自ら、やはりこれは時代に合わないと思うものは、正していくことも必要だと思います。この時期を、禁止、禁止と縛るのではなくて、その生徒を個人として尊重し、主体性にこそ向き合う、そういう指導をしていただきたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"どれも重要なことだと考えております。ただ、学校の中では、子どもたちの個性を光らせる場面は多々ありまして、いろいろなところで私たちは輝く場面を見ます。そこの場面で十分活躍させて褒めていきたいと考えております。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"よく校則の話をすると、学校では個性を出すと集団生活ができなくなる、こういう理屈を持ち出す人が結構いるのです。今後とも、生徒や保護者、また現場の教員の声に耳を傾けていただいて、学校教育を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"筒井委員","kind":"確認","question":"私からは、３４８ページ、教育費全般から、コロナウイルスによる影響と少人数教育について、３６４ページ、図書館費についてお伺いいたします。かなり緊張感を強いることにもなろうと思いますけれども、確認としまして、品川区でもこのような形で給食を行っているのか、現状をお知らせください。行っていたとすれば、それはいつから始められたのでしょうか。","respondent":"篠田学務課長","answer":"これを始めたのは、学校が再開されました６月から分散登校を始め、そのときからそういった形で始めて、現在も継続しています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"報道でも取り上げられておりますけれども、本区でも、こうした、コロナウイルスによって子どもが受けたストレス、心のダメージがあるという実感や事例というのはあるのでしょうか。同様に、子どもに対応する教員も、コロナ感染防止対策に気を遣うのと相まって、ストレスや心のダメージが相当あるかと思いますけれども、そうした実感や事例はありますでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"その中では、やはり学習に対する不安と、もう一つ、クラスが変わったところがありますので、お友達との関係の不安は出てまいりました。そういった中では、教員が１人で抱え込むようなことはなく、やはりチームとして学校教育を行っていくということが必要であるということは、お話をしながら進めているところではあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ教員の方にも気を向けて、ケアをしていただきたいと思います。子どもも当然そうですけれども、学習面や友達との関係で悩みがあるということですが、そうした子どもたちと教員の心のケアはどうされていくのか。先ほどご答弁がありましたとおり、生徒たちに対しては思い出づくりをやっていくというようなことをおっしゃられましたけれども、具体的にそれはどのような形でやっていくのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"もともと卒業遠足があったところは、そちらの卒業遠足をまた３学期にやろうと考えているところもありますし、もう既に移動教室が中止になったことで、６年生や５年生に、それぞれ自分たちが考えた活動をやろうということで。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"そうした遠足やレクリエーション、活動などといったことで、子どもたちに対しては心のケアをやられていくということなのですけれども、そういった活動をさせる、思い出づくりをさせるといったこと以外で、子どもたちに対してもう少し丁寧に聞き取るとか寄り添うとか、そういった活動というのはないのでしょうか。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"学期に１回は生活アンケートを取ってありますので、そちらでお子さんの様子を取り、５年生・７年生については東京都のスクールカウンセラーによる全員面接も行ってあります。教員の心のケアにつきましては、先ほど申し上げましたが、不調が見られたりした場合には、もちろん必要に応じて産業医面談につなぐなど、やはり教職員のケアについても引き続き注意深く見ながら進めていきたいと考えています。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。続けて少人数学級のほうをお伺いいたしますけれども、先月、突然、文部科学省が、３０人学級に１０年をかけて段階的に移行するというような方向性を発表しました。東京都品川区の、今、言ったとおり、物理的・場所的制約といった地域事情も加味されるべきかと思うのですけれども、本区としては、文部科学省が今回出した方向性に対し、どう対応されていくのでしょうか。","respondent":"篠田学務課長","answer":"ただ、こちらのほうも、文部科学省も、今、委員からのご指摘があったとおり、一定の期間を置いてというような形での、まだ考え方が示されているだけですので、その辺のスケジュールが固まってくれば、それに沿った対応を考えていく必要があるだろうとは受け止めているところです。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。ただ、どうしても方向性が少人数学級になっていくのかと思いますので、これは注意深く見ていただいて、それに対しての準備はしていくべきかと思いますので、しっかりと対応のほどよろしくお願いします。続いて図書館のほうに移りますけれども、今、書籍消毒器というのが区内の図書館に幾つかあると思いますけれども、各図書館の設置台数とメーカーと１台当たりの値段を教えてください。","respondent":"横山品川図書館長","answer":"メーカーについては、図書館流通センターのＬＩＶＡという、４冊を除菌できる機械が、価格８０万円から９０万円で入っているのと、あと２、３冊に対応するＣＯＣＯＣＨＩという機種が、５０万円から７０万円台で入ってあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"もともと図書館の本というのはどうしても不特定多数の人が触れるので、衛生面で消毒の必要性が高まっているかと思いますけれども、今回のコロナウイルスで消毒の必要性はさらに高まっていると思いますので、ぜひそうした書籍消毒器の対応というのもお願いしたいと思いますが、どうしても今後もウィズコロナということ、コロナウイルス感染防止ということを考えますと、そうした機械での対応というのは。","respondent":"横山品川図書館長","answer":"一方で、地域資料、品川区にしかない資料については、これからデジタル化を進めていこうという形で、電子書籍の導入とともに地域資料のデジタル化というものを併せて導入しようという検討を今進めているところですので、状況を見ながら対応していこうと思っているところです。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"コロナウイルス感染防止、ウィズコロナという時代の対応というのは必要だと思いますので、今、研究は進められているということですけれども、引き続き電子図書館の研究、そして、図書館を電子化しますと国から急に言われたときに、いつでもすぐに対応できるような準備をぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"学校給食放射性物質検査について伺います。学校給食でもそうなのかと区教育委員会へ問い合わせたところ、学校は継続と確認ができました。これらのことからも、今後さらに放射性物質検査の必要性が求められます。質問します。給食の安全を確認するためにも継続して検査すること、そして放射性物質が移行しやすい食材の傾向が見えてきていることから、単品検査への切替えを再度求めますが、見解を伺います。","respondent":"篠田学務課長","answer":"これまでもご答弁申し上げているとおり、放射性物質の検査につきましては、日々、様々なケースの状況等、それから当然、経費もかかりますし労力もかかるという中で、そこのバランスを考えながら、実施にあたっては考えていくということでお話を申し上げまして、これまでも。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもの生きる、発達するという育ちの権利を保障する観点からも、これ以上縮小を進めることのないよう強く要望します。デートＤＶ、性教育について伺います。保健体育の教科書を確認したところ、デートＤＶについてほんの１文触れていましたが、デートＤＶについて理解を深める授業が行われているのか、改めて伺います。","respondent":"矢部教育総合支援センター長","answer":"デートＤＶに限らず、子どもたちの人権を守るという点で、市民科をはじめ各社会科でも、教科を中心に指導してきたところです。各学校におきましては、セーフティ教室などで、子どもたちの、自分で身を守る被害防止に努めているところです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもがデートＤＶにある状態を通常だと誤って認識してしまわぬよう、学ぶ機会が求められます。冊子については、子どもの手の届くところに置き、講演についても周知するなど連携を図っていただきたいと要望します。それで見解を伺いますが、次にいきます。月経について伺います。その結果、不妊をはじめとした気づきにくい様々な病気の早期発見にもつながると考えますが、区教育委員会の見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただし、お子さんの様子につきましては、養護教諭を含め、もしも必要であれば学校医とも相談して、丁寧に、プライバシーを守って対応してまいりたいと考えております。デートＤＶについてです。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ連携を取って進めていただきたいと要望いたします。養護教諭やＰＴＡ、保健センターなどと協力して、子どもが体について学ぶ機会の確保を求めたいと要望しますが、見解を伺います。次に、体罰等の実態調査について伺います。そして、都の改善には時間がかかると思うので、区内での体罰・暴力の早期発見・救出のために、都の改善を待たずに、区としての調査を早急に行うことを求めますが、見解を伺います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"初めに、月経に関わる対応のお話ですが、私たちとしましては、子どもたちは様々な悩みを抱えてありますので、担任を中心に子どもたちに丁寧に向き合って対応してまいりたいと考えております。生徒アンケートの期間ですけれども、東京都教育委員会が行っています調査につきましては、実施時期が１２月ということで、生徒向けには１２月という案内をしています。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"でしたら、非該当にはならないと思います。中・高生の体罰の質問用紙についての期間については、小学生の質問用紙を確認すると、期間というのは書かれていないのです。だから子どもたちは書けるのです。改善を都にも求めてほしいですし、区としても、そこを削除して調査を行ってほしいと思います。区教育委員会としての趣旨説明が必要だと考えますが、見解を伺います。","respondent":"工藤指導課長","answer":"やはりご指摘も頂いてありますが、体罰あるいは不適切な指導をなくすということが非常に重要なことであると認識していますし、例えば本調査の趣旨も含めて、そういったことが、学校、教員。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"様式についてです。東京都の調査様式というのは分かるのですけれども、区としてすぐに直せると思うので求めます。そして次に、新型コロナウイルス感染症関係について伺います。民生費でも伺いましたが、新型コロナウイルス感染症の影響から、来年度、小・中・高等学校に入学する子どもたちは、例年とは違い、準備が間に合わないまま進学します。","respondent":"矢部教育総合支援センター長","answer":"中学校に向けましても、既に６年生は今、コロナ禍だからこそできることでリーダーシップを取っておりますので、そのようなことで、また中学校のほうも対応して、そのような状況を踏まえて丁寧に対応してまいりたいと考えております。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"小学生になった子どもたちは、例年に比べてできることが少ないかもしれませんが、それを受け止めてほしいと要望します。区教育委員会と学校だけでなく、幼稚園や保育園などの先生たちと情報共有を行い、子どもたちを迎える体制を整えてほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問・要望","question":"本日は、３６７ページ、学校ＩＣＴ活用経費、３５４ページ、区教員経費、あるいは３５５ページ、教職員人材育成経費について伺います。ですので、タブレットとペーパーレスの関係の中でも、まずはこれまで手配りされていたプリントをペーパーレスの方向で進めていくということが、学校現場でも必要ではないかと思いますが、ご見解を伺います。","respondent":"工藤指導課長","answer":"ただ、やはりそれは、今後のタブレット配備も併せながら、大事な視点であると認識していますので、そういった意味では検討してまいりたいと考えています。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"教職員のところはまた後ほどお伺いできればと思うのですけれども、児童・生徒に対する紙の配布というところで、まずはプリント等のペーパーレス化を進めるというのは大事かと思いつつ、さらに一歩進めて、例えばテストの結果や通知表は、新型コロナの関係で終業式には通知表を配れませんでしたというふうな報道なども、これは品川区ではありませんけれども結構あるところでございまして、これも。","respondent":"工藤指導課長","answer":"もちろん個人情報の保護というのが、タブレット内、またそういった情報の管理というのは非常に重要ですので、そういったことが可能かどうか、またはそれが適しているのかどうかも含めて、検討課題であるという認識ではありますので、そういったことも踏まえて。","id":"exchange-046"},{"speaker":"松本委員","kind":"質問・要望","question":"少しお伺いしたいのですけれども、１人１台、ＬＴＥ型タブレットが配付されて、児童・生徒がデジタル教材で学べるようになった後、もうかなり学べるようになった後に、保護者の中から、希望者には、デジタル教材を学校側が学校の経費で負担して印刷して配付すべきだ、全員ではなくて希望者には配付するべきだという話が出てきた場合。","respondent":"工藤指導課長","answer":"そういったメリット・デメリットも含めながら、何が有効かというのは検討する必要があるとも思いますし、そういった活用を図っていく範囲では、様々ご要望はあろうかと思いますが、取組みの趣旨というのをご理解いただくということも踏まえながら進めたいと考えています。","id":"exchange-047"},{"speaker":"松本委員","kind":"質問・要望","question":"続きまして教員側ですけれども、先ほど、職員会議のペーパーレス化に取り組んでいただいている学校もあるということで、これはぜひ進めていただきたいと思いますが、ほかの学校での取組みや、推進していく流れというところもお願いできればと思います。","respondent":"工藤指導課長","answer":"各学校で行っていくものに関しましては、やはりあらかじめ資料等、読み込んでいただきたいものというのは事前に配付する。それを、例えば現在の機能で言えば（イントラネットの）回覧機能を使って、既に送っておくということで取り組んでいる学校もあると存じています。","id":"exchange-048"},{"speaker":"松本委員","kind":"質問","question":"その中でまたお伺いしたいのですけれども、一部の教員が、自分が雇用されたときにはタブレットなどなかった。タブレットを使うことは働く上で前提とされていなかったと述べて、紙での授業しかやらない、あるいは職員会議も、希望者には資料を学校側できちんと印刷して紙で配るべきだと主張した場合に、学校側としてはどのように対応するでしょうか。","respondent":"工藤指導課長","answer":"もう今、現状は、タブレットを活用することで授業の質も高められるという視点で授業改善に資していくというところが、教員に課されている使命であるというところは、教員に対しては指導してまいりたいと思いますし、そのように取り組んでいきたいと考えています。","id":"exchange-049"},{"speaker":"松本委員","kind":"質問","question":"時代に合わせて、やはり職場環境、働き方も変わっていくものだと思います。タブレットが配付されて、ペーパーレスでやっていきましょうという流れの中で、希望者には資料を紙で配付するべきだと、資料を作成する側もそういったことがあると、教員にも負担となると考えています。停滞させている人たちに対しては強く怒りを持っているということを改めて申し上げまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"西村委員","kind":"質問","question":"３５９ページ、学校と家庭の連携推進事業と、３６１ページ、マイスクール運営費、関連しまして、不登校、ひきこもりについて伺ってまいります。ページが見当たりませんでしたが、時間が余りましたら、まもるっちについて伺います。先ほどのご答弁で、マイスクールそれぞれの利用状況の報告がございました。この人数は多いのか少ないのか。お知らせください。","respondent":"矢部教育総合支援センター長","answer":"平成３０年の不登校の出現率につきましては０.５５％、中学校につきましては３.７１％と、例年、徐々に増加傾向にあります。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"不登校児童・生徒への支援の在り方について伺ってまいりたいと思います。現在、不登校児は、全国小・中学校で合わせて１７万人と言われます。把握が難しいとは理解していますが、マイスクールやフリースクールに行かない、行けない児童・生徒の推計値はどのようになっているでしょうか。ケアしている配慮があれば、さらに取り組んでいただきたいと思いますので、お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"実際には個別対応になりまして、不登校の理由はみんなそれぞれ個別ですので、担任を中心に学校で、体制をつくりながら、家庭と連携を取って連絡しています。こちらはＨＥＡＲＴＳもつながっている事例もありますので、そちらで訪問して話をしたりということまでは聞いてあります。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区にはＨＥＡＲＴＳがありますし、スクールカウンセラーもいてくださって大変心強いのですが、不登校児の中には長らく外出できていない児童・生徒もいると伺っています。私が伺った事例ですと、ＨＥＡＲＴＳの面談をきっかけにマイスクール五反田に行く。児童センターに行くお子さんもいると伺っています。このようなことに関して、区のお考えと今後の展望をお聞かせください。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"今後、１人１台タブレットが配付されますので、学校に来られないお子さんたちの新たなフォローになるかということで、学習面・生活面でも検討を進めていきたいと考えています。区内においても、マイスクール五反田等で通い始めて、自分で学びたいという意欲が上がってきて、進学につながっているという実績もあります。そういったところが相まって進学率が上がってきていると認識しています。","id":"exchange-053"},{"speaker":"西村委員","kind":"質問","question":"ＩＣＴの推進は大変期待が持てると思います。今、教育分野は大きく変わろうとしていると思っています。一般的に、フリースクール、ホームスクールなどは、原則、公的な支援がありませんので、親が学費を負担しなければならず、金銭面で苦しむ家庭も少なくないと伺っています。こういった、学校に行けない児童・生徒のこれからの公教育はどうあるべきか、区のお考えをお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"ただ懸念は、不登校が長期化することを助長してしまうということは文部科学省の通知にもありますので、その辺りを慎重に進めてまいりたいと考えております。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問","question":"ぜひとも引き続きお願いします。ひきこもり支援について伺いますが、全国的にも苦労しているといういろいろな報道が多い中、経済産業省の委託事業で、「ｅスポーツを活性化させるための方策に関する検討会」という報告書を読みました。都市部は特に、ゲーム、オンライン、ｅスポーツなどの取組みが注目されていますが、この辺りはどのようにお考えでしょうか。お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"ｅスポーツにつきましては、世界でも認知されているということは承知しています。ただし、現在、新しく学習指導要領が改訂されましたが、そちらには示しがございませんので、国または東京都の示しを踏まえて対応していきたいと考えております。","id":"exchange-055"},{"speaker":"西村委員","kind":"質問・要望","question":"ほかの地域での事例ですけれども、オンライン学習、あと対話が中心の哲学カフェのような、非認知能力を養う講座を出席扱いとしたり、スタディーサプリを無料で受講できるといった事例も伺いました。それが心を開くきっかけになることもあります。寄り添う施策としてぜひ調査・研究を進めていただきたいと思っています。９月２１日の広報しながわで教育特集が組まれていました。次の質問に移ります。","respondent":"矢部教育総合支援センター長","answer":"それ以外に専門家、特に不登校への対応についての専門家をお呼びして、校内で研修を行っていただく。そのような事業です。","id":"exchange-056"},{"speaker":"西村委員","kind":"意見","question":"保護者出席率が９割という区内地域もあったそうです。１学期・２学期は外部の講師を呼ぶことが中止になりまして、コロナ対策をした上で、今まで培ってきた外部とのつながりを壊さないように、コミュニティ・スクールをぜひ継続してほしいと考えています。その辺り、ご意見をお聞かせください。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"各学校の行事につきましては、委員がおっしゃったとおり、１学期はコロナ禍でございましたので大分控えてございましたが、新たな形で、日にちを分けたり、時間を分けたり、来ていただく方を制限したりということで進めてあります。ご指摘いただきましたように、コミュニティ・スクールは、地域に根差した、地域とともにある学校づくりという中では、やはり地域の関わりのところは、学校支援地域本部も含めまして。","id":"exchange-057"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、まもるっちについて伺いたいのですが、項目が特別になく、見つけられず、すみません。入学した際に、学校側もしくは、オプションのご説明までは要らないと思うのですが、基本装備の部分だけでももう少し丁寧に、説明会が難しい場合は、何かＹｏｕＴｕｂｅで動画で作っていただくなど工夫していただきたいと思うのですが、可能でしょうか。ご意見をお聞かせください。","respondent":"有馬庶務課長","answer":"ところが、今年度につきましては、ちょうど入学式があってすぐ休校になってしまったというようなこともございまして、保護者の方に十分な説明が学校からできなかったのかと拝察いたします。","id":"exchange-058"},{"speaker":"西村委員","kind":"質問","question":"私の子どもが１年生で、なかなか、まもるっちを理解できていなくて、コロナ禍ということがあったのだと改めて理解いたしました。何かそのような方法で、緊急通報時にどのような連絡が来るのか、あとはこれは２４時間対応できているのかなどのご質問も保護者の方たちからありまして、その辺りがなかなかまだ周知されていないのだと感じていますので、ぜひとも取組みをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"つる委員","kind":"提案","question":"３６４ページ、図書館費、３６９ページ、学校図書館経費、それから教育費で学校の朝の受入れ時間について、それから３５２ページ、教育指導費について伺っていきたいと思います。図書館関係であります。その『よりぬきサザエさん』を読んで読書感想文を出したのです。中学校については、今年度についてはモデル校として、冨士見台中学校では市民科の授業で取り組まれていると伺いました。","respondent":"横山品川図書館長","answer":"国際連合で、持続可能な開発目標について、子ども、６歳から１２歳が学び、実際に行動を起こすことを促すために、「ＳＤＧｓ Ｂｏｏｋ Ｃｌｕｂ」という形で、目標の１から１７まで順番に取り上げて、１か月ずつブックリストを発表していくという方針が出されております。","id":"exchange-060"},{"speaker":"つる委員","kind":"質問・要望","question":"どこか分からなかったので教育費というところで恐縮なのですが、平日、いわゆる通常の登校する朝の、学校での受入れ時間の対応についてということなのですが、これは２０１９年ですか、２０１８年だったでしょうか、これから新１年生になるという保護者の方からご相談を頂いて、いわゆる小１の壁の一つとして、朝の登校時間の課題のご相談を頂きました。そういう学校も伺っているところであります。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"それに対応しまして、校長のほうで、今お話がありました教員の勤務時間のこともありますが、管理職を中心に、早めにお子さんを一部お預かりしている事例はあります。これは学習面の支援ということではございませんが、通学安全業務につきましては７時半から配置できるようにということで対応しています。","id":"exchange-061"},{"speaker":"つる委員","kind":"質問・要望","question":"子どもたちの安全・安心というところでは、７時半ぐらいから体制を取っていただいているということでありました。次に教育指導費ということで、午前中の質疑の中で、コロナ禍における様々な教育、それから指導内容については、オンラインの活用なども含めて個別具体のことは伺いましたし、また文教委員会でも一定程度質疑がされているのも確認させていただきました。","respondent":"矢部教育総合支援センター長","answer":"今後につきましても、今のようなコロナの事情、またこれから、なかなか制限がありますけれども行事も進めていくということになっておりますので、学校独自の工夫した、子どもたちの創意を活かしたような行事も組み立てていきたいと考えています。","id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"たしか今年の予算特別委員会でも申し上げたと思いますが、やはりそういう意味では、こうした機会をどう教育の現場で捉えて、児童・生徒の生き抜く力に結びつけていくかということが大事だと思います。「お手紙どうもありがとう。花丸」。それで今、生きる力というか勉強を頑張るという気持ちになっていて、やはりこんな、子どもの心に響くような教師が１人でも増えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"くにば委員","kind":"質問","question":"私は、３５７ページ、一貫教育推進経費、３６７ページ、学校ＩＣＴ活用経費から、オンライン学習について伺います。品川区では、平成１８年に先進的な取組みとして小中一貫校を開校し、さらに平成２８年度には義務教育学校開校、令和２年度で５年目になります。","respondent":"工藤指導課長","answer":"そういった意味では、小学校も中学校もそれぞれの方針に応じた特色ある学校行事等も行ってありますので、義務教育学校の中で育まれる、また４－３－２という学年団のまとまりというのも非常に、特に５・６・７年生、また前期課程と後期課程の教員の行き来であるとか。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"今ご答弁くださったメリットであるとか、デメリットもあると思うのですけれども、そういった部分を、小・中学校の教育現場にフィードバックして、その結果、新たに始めた取組みや、あとは変更した教育手法がありましたらお知らせください。今、品川区には義務教育学校が６校ありますけれども、今後さらにこの取組みを強化して、義務教育学校を増やしていく方針はありますでしょうか。ご答弁をお願いします。","respondent":"工藤指導課長、篠田学務課長","answer":"やはり勉強合宿を行うにあたっては、様々指導員の確保であるとか、教職員体制が十分取れているというところで取り組みやすさというのがありますけれども、ただその取組みにつきましては。これまで品川区では６校、地域バランス等を考えて設置してまいりましたけれども、小学校・中学校・義務教育学校と、３校種の体制、バランスの取れた体制が一番重要と考えていますので。","id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"最後にもう一点、小中一貫校、義務教育学校出身者について、卒業後の中長期的な特性把握の分析であるとか、あとは小・中学校出身者との大学進学率の差異であるとか、その後の職業分布等の違いなど、客観的な統計データを取る調査やアンケート等はなさっていますでしょうか。こちらについては、全国の自治体や文部科学省で、同様に、この点の中長期的な統計調査は取っているのでしょうか。","respondent":"工藤指導課長","answer":"国のほうのそういった統計的な調査があるかということにも、現状、私どもも、そういったものがあるという把握もしてございません。","id":"exchange-066"},{"speaker":"くにば委員","kind":"質問・要望","question":"続いてオンライン学習についてです。学習の遅れは、学校がありとあらゆる工夫を図って教育をすべきで、これでは家庭への教育の押しつけだ」。そういった保護者の声について、区はどのように捉え、受け止めていますでしょうか。オンライン学習については、生徒へのケアだけではなく保護者の負担軽減、メンタル面への配慮やケアが必要だと考えますけれども、この点のお考えをお聞かせください。","respondent":"工藤指導課長","answer":"そういった意味では、例えば保護者の方に採点をお願いするなどという事例も幾つかあったと認識していますけれども、学校によっては、子どもが家で考えるような課題を提示しながら、またそれが、登校できたとき、または課題を回収するときに。","id":"exchange-067"},{"speaker":"くにば委員","kind":"質問","question":"自宅学習だと、漫画やゲーム、スマホ等、多くの誘惑があり、学習の進みが遅くなる生徒がいる。学校でほかの生徒と関わる機会が損なわれているため、人間関係形成についての教育が進まないなど、様々なデメリットが指摘されていますけれども、これらのデメリットに対する具体的な改善策の取組み、例えば集中力持続のための具体的な方策のアドバイスなど、どのようになさっていますでしょうか。","respondent":"工藤指導課長","answer":"委員から今ご指摘があったところですけれども、これから私どもはタブレットを導入して、さらにオンラインでの学習というのも進めていく中、また家庭学習の在り方ということについても、やはり同時に検討しているところではあります。","id":"exchange-068"},{"speaker":"くにば委員","kind":"質問・要望","question":"オンライン学習については非常に有用で、今後必ず進めていかなければいけない分野だと思います。コロナの影響はこれからもまだまだ続くと思いますし、ここに関しては区でもしっかりと研究を進めていただいて、オンライン学習が、より生徒が今までの学習よりもプラスになるような研究を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、３６１ページの特別支援教育費について伺いたいと思います。インクルーシブ教育の充実を求めて、学習支援員・介助員の拡充、それから特別支援教育推進計画の策定を求めて質問したいと思います。そのことで現場がどう変わったのか、また現場の状況から、今後さらに大幅に増やすことが必要ではないかと考えますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"品川区の人口が増えておりますので、今後も、広げてまいりたいと考えております。介助員・学習支援員の数については、手元にすぐ出てきませんので、今はお答えできません。すみません。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、増えた人数に合わせて５倍にした場合どうなるのかと計算しましたら、８億８,０００万円ぐらいになるのですけれども、そういうことで考えると、この予算の増え方というのは少し少ないのではないかと思うのですが、いかがでしょうか。そういうことからすれば、ここのところの大幅増をすべきではないかと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"担任も、そのスタッフや、自分も見識を深めて、そのお子さんに対してどうあるべきか、ほかの子どもたちにはどう理解してもらうかということが大事なのかと考えておりますので、繰り返しますが、人数については増えていくことは認知しておりますが。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だって、１人につき、１週間に１時間しかついていないわけですから。こういうことからも、ぜひ品川区ではもう少し、ここのところの増員、時間数の増、１人についての時間数の増も含めて、大幅増員をしていただきたいと強く要望しておきます。しかし、今、障害者の権利条約も批准されましたし、障害者差別解消法も整備されて、法整備もかなりできていまして、インクルーシブ教育の充実が求められております。","respondent":"矢部教育総合支援センター長","answer":"本年度におきましても、豊葉の杜学園に、ことばの教室、また来年度におきましても、荏原平塚学園と日野学園において、特別支援学級の前期課程のほうの対応をするところです。これからも様々な状況を鑑みながら計画的に進めてまいりたいと考えています。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都も計画をもちろんつくっているのですけれど、それとともに、やはり区独自の計画をぜひつくっていただきたいと思うのです。隣の目黒区、そのほかの幾つもの区がつくっているのですけれども、隣の目黒区では、平成１９年に第一次をつくり、今年３月に第四次をつくりました。区としてもぜひ推進計画をつくって、この取組みを拡充させていただきたいと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ご意見のとおり、これまでも計画的に進めてきたところです。まだまだ課題もあると思いますので、これからの成果とともに十分検討してまいりたいと考えております。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、計画をつくることによって、これまでの状況をしっかりと分析して、そして課題を明らかにして、そして何が今大事なのかというところを精査して、具体的な対策というところにつなげていくことができると思うのです。ぜひとも推進計画をつくっていただくように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"学校ＩＣＴ活用経費です。いよいよですが、来年、品川区においても、児童・生徒全員、１人につき１台、タブレットが渡されます。そこでお聞きしたいのが、各教科の指導に関しては、この文部科学省の資料を参考にされるのか、それとも、例えばですけれども、品川モデルみたいな感じで、名前をつけて品川区独自に活用方法を検討するのか、この活用方法について見解をお聞かせください。","respondent":"工藤指導課長","answer":"やはり区としても、品川区の一貫教育に合った活用を図るという観点で、学校、また教員の意見も反映させながら作成しておるところです。","id":"exchange-075"},{"speaker":"せお委員","kind":"質問","question":"今おっしゃられた、本当に品川区の特性に合わせた部分というのを取り入れていただけると効果が上がると思いますので、ぜひお願いいたします。そこで言いますと、ＩＣＴ推進校で今まで活用していたトータル学習システムもすばらしいものなのですが、このトータル学習システムは今後どのような取扱いになりますでしょうか。","respondent":"篠田学務課長","answer":"今後はなかなかそういう形ではなくて、クラウド環境において、常にオンラインで最新の情報が引き出せるといったことが理想的だろうということで、今回、新たなタブレットを配付するにあたっては、トータル学習システムはここまでという形で。","id":"exchange-076"},{"speaker":"せお委員","kind":"質問","question":"全く新しいものに変わるということで、教師の方も子どもたちも混乱しないようなＩＣＴの活用をお願いしたいと思っています。さらに、先ほどご紹介した文部科学省の参考資料ですが、その中には、特別支援教育におけるＩＣＴの活用についても資料があります。先ほどは教科の面でしたが、今度は特別支援教育におけるＩＣＴの活用について、品川区での具体的な方法を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"特別支援教育におけるＩＣＴ活用についてのご質問です。既に特別支援学級におきましてはタブレットが渡っておりまして、１人１台とは申し上げられませんけれども活用しております。","id":"exchange-077"},{"speaker":"せお委員","kind":"質問・要望","question":"現在ある、そういったノウハウももちろん活用していただいて、個別最適化した学びを実現していただきたいと思っています。そこでお聞きしたいのですが、まず通常学級に通っている、特別支援教室の対象ではないお子さんは、現在、個別最適化した学びのための支援というのはどのように行っているのか。そして、タブレットを導入したらどのような支援になるのか。以上、２点、お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"そこで個別に教員も回りまして、子どもたちの考えを活かして、その後、追究、検討となるわけです。そのようなことで、個々の時間において個別に対応していると考えています。","id":"exchange-078"},{"speaker":"せお委員","kind":"提案","question":"個別最適化した学びというと、先ほどご案内した文部科学省の活用例にもありますが、肢体不自由児などで、学校に通うのが困難なお子さんは、現在、特別支援学校の訪問教育を受けているお子さんが多くて、一般質問でもご提案しました、ＯｒｉＨｉｍｅなどを使って地域の子どもたちとの触れ合いを行ったり、視線や口を使って入力装置を使用するなど、ＩＣＴの活用が進めば、望んでいた未来に近づきそうで。","respondent":"矢部教育総合支援センター長","answer":"委員にご紹介いただきましたＩＣＴ活用も含めまして、これまでの特別支援学級等のＩＣＴ活用を、有効なものを取り入れて、今後もほかの、１人１台タブレットに向けて、有効な活用を考えてまいりたいと思います。","id":"exchange-079"},{"speaker":"せお委員","kind":"質問・要望","question":"質問が変わりまして、３５５ページ、学校支援費に関連して、児童・生徒のメンタルケアについてお聞きします。東京都は臨時休校明けに、スクールカウンセラーとの面接を、まずは心配な様子が見られる子どもから行い、その後、５年生、７年生、全員と行うよう求めていて、先ほど、品川区でも面接を行ったとご答弁がありましたが、面接した結果、どのようにフォローしているのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"５年生・７年生以外の面談またはスクールカウンセラーの対応ですが、基本的にはやはり担任が毎日様子を見ていますので、そこから、養護教諭やスクールカウンセラー、また保護者と随時連携して、丁寧に対応していきたいと考えています。","id":"exchange-080"},{"speaker":"せお委員","kind":"質問・要望","question":"それで、児童・生徒に負担がかかり過ぎるような感染対策というのは、いま一度検討していただきたいと要望いたします。こちらは確認となるのですが、就学相談の中では、それぞれのお子さんに、通常学級か、特別支援学級か、または特別支援学校か、どこに就学したらよいかを伝えていると認識しています。さらに、現在の就学相談はどのような流れで実施していますでしょうか。２点お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"就学相談についてのお尋ねです。就学相談の担当の委員は、まず医師です。さらに校長、また特別支援学級のあった学校の元校長、特別支援学校や特別支援学級の教員が集まって協議を致します。","id":"exchange-081"},{"speaker":"せお委員","kind":"質問","question":"今の就学相談の流れなのですが、お子さんの様子を見て面談をして、その後、どこがいいかとお伝えする。就学相談の中身はそれだけなのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"その後に協議の結果、ここがよいのではないかというような助言をするという形で、そこからご連絡をさせていただいた際に、いかがですかということで、そこからさらに次の枝葉に分かれる選択肢、または相談に乗るというような手順です。","id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"これに関してはまた別の機会で質問します。主要施策の成果報告書の４８ページから、こちらも確認なのですが、事業概要に、「様々な障害のある児童・生徒の増加、多様化に対応するため、特別支援学級・特別支援教室を整備、増設する」とあり、課題のところにも、「特別支援学級の新設を継続して行う」とあります。","respondent":"矢部教育総合支援センター長","answer":"ただ、インクルーシブ教育は、いろいろなお子さんに対応するということだと考えておりますので、通常学級にいても、特別支援学級、特別支援教室、特別支援学校においても、そのお子さんにとって、これからの成長に一番望ましいものを支援していく場所と捉えております。","id":"exchange-083"},{"speaker":"せお委員","kind":"質問","question":"最後に１点だけ。特別支援学級を増設してほしいというか、多分、各校に欲しいというお声があると思うのですけれど、そういうニーズがあるということへの理由というのは何だとお感じでしょうか。","respondent":"矢部教育総合支援センター長","answer":"個別に様々な理由が考えられますけれども、やはり１つは保護者の理解。例えば、ここ１０年間、私が教育委員会にいた間でも、特別支援教育に対する理解はとても深まっていると思います。","id":"exchange-084"},{"speaker":"せお委員","kind":"質問・要望","question":"私たち障害児の親の考えでは、多くの人は、特別支援学級や特別支援学校というのは、本来のインクルーシブ教育には含まれていないです。それは、障害がない子たちとは所属が異なるからです。みんなで過ごせるという。そういったところが本来のインクルーシブ教育ではないかと私は思っています。ぜひともそこを念頭に、これからの教育のビジョンを考えていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３５７ページ、ルネサンス推進事業について、３７５ページ、保健運営費について、５１８ページ、美術工芸品・芸術文化資料類についてお伺いいたします。１点目に、ルネサンス推進事業についてお伺いいたします。結果の平等を追求すべき内容と、機会の均等を確保しておけばよい内容とをどのように区別していますでしょうか。３点目の、美術工芸品・芸術文化資料類についてもお伺いいたします。","respondent":"工藤指導課長、矢部教育総合支援センター長、有馬庶務課長、篠田学務課長","answer":"ルネサンス推進、また「プラン２１」というお話も頂きました。品川区の一貫教育についてのお尋ねというところで回答申し上げます。例えば、「見通しと振り返り」という言葉になっていまして、子どもたちが一番最初に学習課題を捉えた後に、どうやって勉強していったらいいだろう。それ以外には、各学校では複製絵画を持っておりまして、これにつきましては、年に１回、学校を巡回するというようなことで。学校の健診と保健衛生部門との連携についてのお尋ねがございました。","id":"exchange-086"},{"speaker":"横山委員","kind":"意見","question":"みんな違っていい、みんなオーケーを両立するということをお願いしたいと思います。美術品についてなのですけれども、低稼働率のものなどがありましたら、なるべく区内全域の多くの子どもたちに鑑賞してもらえるようお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３５３ページ、学校給食費に関連して和牛などを使用した学校給食について、３６３ページ、教科書採択事務について、３６９ページ、学校図書館経費に関連して電子書籍の促進についてお伺いいたします。この日本の食を守るために幾つか質問します。今年の３月から学校が休校となりましたが、学校の再開後、給食も再開されたと思いますけれども、いつ頃から具体的に再開されたのかを教えてください。","respondent":"篠田学務課長","answer":"今年度の学校給食の再開ですけれども、学校が６月から分散登校ということで再開されましたので、それに合わせて給食も提供させていただいたところです。","id":"exchange-088"},{"speaker":"小芝委員","kind":"意見","question":"その学校給食の食材が今、画期的なニュースとなっています。全国の自治体でも、和牛などを使った献立を提供する取組みがある中で、品川区でも学校給食に、これまではなかなか提供できなかった和牛など、日本の第一次産業で育てられた食を提供することで、子どもたちの思い出づくりをサポートすることになると思いますし、食育の機会にもなると思いますが、お考えをお聞かせいただければと思います。","respondent":"篠田学務課長","answer":"ですので、なかなか区が単独でできる事業ではないというのがあるのですけれども、そういった面で制度面が整ってくれば、一定程度、私どもも対応の仕方はあるのかとは考えているところです。","id":"exchange-089"},{"speaker":"小芝委員","kind":"質問・要望","question":"ざっくり否定されてしまいましたけれども、前向きにぜひお考えいただければと思います。続きまして、３６３ページ、教科書採択事務についてお伺いいたします。今年の夏、来年度から使用されます、中学校や義務教育学校の後期課程の生徒を対象にしました教科書の選定が行われました。教育委員会で教科書が採択されるまでの、ざっくりとした流れというものを教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"教科書採択の流れです。初めに、教科用図書調査検討委員会を立ち上げます。その後に、教科書調査研究会、こちらは各教科別に担当教員がおりまして、複数で協議します。その結果を、次にもう一度、教科用図書調査検討委員会に上げまして、その報告を教育委員会でしていただく。","id":"exchange-090"},{"speaker":"小芝委員","kind":"質問・要望","question":"３段階を経て教科書が採択されるということを理解いたしました。教科書採択には、文部科学省のホームページにもあるとおり、公正性と透明性が求められています。品川区でも同様の事案がありました。その後、こういう事案のニュースは聞かなくなりましたが、教科書採択の公正性を担保するために品川区が取り組んできたことがあれば、教えていただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"教科書採択に関わるご意見のことです。２か所、品川区役所と教育総合支援センターにおきまして、教科書展示会を１か月間ほど行いました。その間に、アンケート用紙がありますので、それなどでご意見を頂いています。特に委員がご心配されるような内容はございませんでした。","id":"exchange-091"},{"speaker":"小芝委員","kind":"質問","question":"採択の原点に立ち、いかなる教科書であっても、公正・中立なご判断のもと、真摯に教育委員会で審議されるべきと考えております。そこでお聞きします。これまでの教科書採択の歴史の中で、数ある教科書の中で特定の教科書だけは採択しないようにという意見が、これまで教育委員会、また採択に関わる人々に対してされた事実はありましたでしょうか。","respondent":"矢部教育総合支援センター長","answer":"当然、意見を書きますので、このたびＡ社、Ｂ社についてご意見はありました。ただ、そこは、受ける意見の一つだと考えていますので、そのように認識しています。","id":"exchange-092"},{"speaker":"小芝委員","kind":"提案","question":"３６９ページの学校図書館経費に関連して、電子書籍の促進についてお伺いいたします。今年の第１回定例会で、我が会派の芹澤委員からも導入の提案がありました電子書籍について、コロナ禍を生きる子どもたちの未来に向けた質問をします。今、コロナ禍で、電子書籍への注目が高まっております。今は既に自由に使えると思いますが、今現在の学校図書館での状況を教えていただければと思います。","respondent":"横山品川図書館長","answer":"区立図書館から学校図書館へ、学校支援スタッフを派遣している状況ですが、休校が明けましてからは、スタッフも学校図書館で生徒を待って対応しているような状況が続いて、通常どおり開館しています。","id":"exchange-093"},{"speaker":"小芝委員","kind":"意見","question":"その環境を整えていくことも、行政による区民サービスの一つであると考えますし、ＧＩＧＡスクール構想で今年度中にタブレット端末が区内の全ての小・中学生に行き渡れば、誰もが電子書籍にアクセスできる公平性が担保されることからも、学校図書館への電子書籍の導入を視野に入れた前向きなお考えを頂ければと思いますが、よろしくお願いします。","respondent":"横山品川図書館長","answer":"先ほどご案内しましたように、電子図書館の導入そのものについても、今後の状況を見ながら検討していきたいと思ってあります。","id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"今、こういうコロナ禍の状況ですけれど、感染拡大防止につながる点で、私も電子書籍の導入に向けて質問させていただきました。今後も時代の変化に合わせて、品川区に限らず東京都、そして全国に至って、読書のパーセンテージを上げていただきますことを期待しまして質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３６９ページの学校図書館運営費に関わって、学校司書と司書教諭の充実について質問します。学校司書の配置について伺います。これまで、学校司書が毎日いるように配置を求めてきました。学校司書の全日配置に向けて、予算化などを含めて、今、どんな取組みをしているのか、伺います。","respondent":"横山品川図書館長","answer":"その中で問題点を把握し、今後の動きについて検討する形とともに、今現在、週１５時間の配置の中で、それ以外については学校において学校ボランティアの方や父兄の方にご参加いただき、いろいろな方が関わって学校図書館を運営していただく形を取ってありますので。","id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"今、いろいろなスタッフの方など、アンケートをしたり話し合いをしているということでしたけれども、現段階でどういった形というか、どういう意見が出されているのか、できる範囲でご説明いただけたらと思います。","respondent":"横山品川図書館長","answer":"ですので、急に全日配置というような勤め方はなかなか難しい、また、収入の面、時間の面でも、増えてしまうのが急であると対応しづらいというのが、スタッフ、また事業者の意見でもあります。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろなボランティアの方など、区内の学校でもいろいろな状況があるということですので、できる学校から始めていただきたいと思いますが、いかがでしょうか。教育上、司書のいる学校図書館が求められているということですので、教育委員会が責任を持って学校司書の全日配置を行うことを求めますが、いかがでしょうか。","respondent":"横山品川図書館長、工藤指導課長","answer":"学校ごとに事情が違いますし、また状況もそのときによって変わってくることなので、その学校で、今は大丈夫であるけれど、来年度にそれが望ましいかどうかというのは、また冷静な判断が求められるところですので、それは。そういった意味では、学校図書館の効果的な活用は引き続き学校教育の中で進めていきたいと考えています。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"運営スタッフが配置されている１５時間のうち１２コマが授業で埋まってしまい、選書や書架整理、教材用の図書を選ぶ時間、掲示物や装飾、図書館だよりを作る時間などが取れないということです。しかし、そもそも学校司書が行うべき仕事ができているのでしょうか。現在の学校司書配置時間で、ボランティアなどができない部分について、十分だと考えているのか、伺います。","respondent":"横山品川図書館長","answer":"スタッフの配置につきましては、まず運営にあたって毎月１回、学校の副校長を中心に図書の先生、スタッフ、また学校ボランティアの方も時には参加して、次の月の運営について打合せを持つような形が義務づけられてあります。","id":"exchange-099"},{"speaker":"のだて委員","kind":"質問","question":"ボランティア等学校全体でということですが、そういう方ができない、司書としての専門性が活かされる部分というのがあると思うのです。そういったところで、しっかりとした十分な時間が取れているのかということを改めて伺いたいと思います。","respondent":"横山品川図書館長","answer":"スタッフのほうが司書の資格を持っている場合もかなり多いですが、各学校に司書教諭の先生が配置されております。学校の責任としては校長先生が学校図書館長ですので、その指揮の下、司書教諭の先生が取りまとめをする形で運営している状況です。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"司書教諭が取りまとめしているのは分かりましたけれども、十分な時間が確保されているのかということなのです。小学校で１２学級以上ある学校は、３７校中３０校あります。運営スタッフや先生からも時間増の要望が上がっています。１２学級以上ある学校では、学校司書の配置時間を増やしていただきたいと思いますが、いかがでしょう。","respondent":"横山品川図書館長","answer":"以前にも申し上げましたとおり、将来的には調整の上で時間を増やすことを検討していきたいと思ってありますので、先ほどのアンケートや打合せの結果も踏まえて、丁寧に対応について検討し、計画を進めていきたいと思ってあります。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"全日配置に向けて力を尽くしていただきたいと思うのですが、１２学級以上ある学校の大変さというのは今起きていることですので、ぜひ早めに配置していくようにということで求めておきたいと思います。次に、司書教諭について伺います。現在、変更があればご説明ください。司書教諭のスキルアップも必要だと思いますけれども、区の司書教諭の研修はどのように行われているのか、伺います。","respondent":"工藤指導課長","answer":"司書教諭につきましては、司書教諭の資格は持っているということで、またその研鑽につきましては、研修会という形を開いてはございませんけれども、適宜校長から、また学校運営のスタッフなどと協議しながら進めていくというところがあります。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"研修をやっていないということですので、ぜひそういったこともやっていただいて、司書教諭と学校司書の連携で、創造的な授業をやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"塚本委員","kind":"確認","question":"この警報の、何が出ているから休校だというところでの判断は、過去、保護者が各自にというようなところで原則的にはなされているかと思いますけれども、一方で、なかなか見にくいというか、情報収集がなかなか的確にできなかったりする場合もあったりするということで、品川区のホームページ等で。","respondent":"矢部教育総合支援センター長","answer":"今年度より、広報広聴課と連携いたしまして、７時の判断は変わりませんけれども、特別警報と暴風警報の２つが出た場合は、休校というお知らせをホームページにしていただくようになっております。今年度はまだその事案が発生してございませんので、今後努めてまいります。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"中学生のスマホ持込みのことについてなのですが、ご案内かと思いますけれども、今年の７月３１日に文部科学省から、中学校のスマホ持込みに関する通知というものが都道府県、政令市に対して出されたと。原則禁止ということはありつつ、持ち込む場合の４つの条件というものを示したということになっております。このことに関して、都から区にどのように伝えられているのか、初めにお伺いします。","respondent":"矢部教育総合支援センター長","answer":"スマートフォン等の持込みについては、国からの指示に従って、特段、東京都からの通知はまだ認知してございません。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問","question":"東京都からということでしたけれども、そうすると、この４つの条件は品川区としてどのように捉えているかというところが、焦点というか、お伺いしたい点になってくるかと思います。","respondent":"矢部教育総合支援センター長","answer":"これまでどおり、中学校も小学校も原則、持込み禁止です。ただし、事案によっては、保護者と相談しながら個別に対応しているケースもあると理解しています。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問","question":"つまり、この４つの条件を満たしていれば、どうぞ、お持ち込みくださいというスタンスなのか、いや、そうではないのだと。何度か委員会等でもこの議論はしていますけれども、どのように教育委員会としてこの課題に対して答えていくのかということについて、１つの選択肢というか、検討すべき事案ではないのかなとも思っておりますので、そういったところも含めて、もう一度ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"原則禁止にのっとって、これまでに引き続き、ただ個別の対応には応じていくです。防犯についてのお問合せですけれども、そちらにつきましても、中学生はブザーを配付していますので、それを活用して自分で身を守るという点で、登下校の安全を守りたいと考えております。","id":"exchange-107"},{"speaker":"塚本委員","kind":"質問・要望","question":"身を守るという部分ではなくて、保護者との連絡手段として、要望というかお声が出ているので、ブザーはちょっと、この問題の解決としては違うのです。その点についてお考えをお聞きしたいのと、それとは別に、災害時等、今、コロナの関係もあって、さらにそういった意味ではいろいろな懸念事項が世の中にある中で、保護者として子どもと連絡を取りたいということに応えていくことについて、もう一度。","respondent":"矢部教育総合支援センター長","answer":"２点目、連絡ツールとしましては、まず中学生ですので、自分の安全を守るということで大事だと思うのですが、学校の中で被災すれば学校での連絡になりますし、今後はタブレットも配付され、どのように活用されるか、検討の余地がありますけれども、様々状況に鑑みた上。","id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"そう意味では、その部分について、教員にお任せというところではなかなか難しいというか、そういうわけにもいかない部分が出てくるというところで、１つはＩＣＴ支援員というのが、いよいよ支援員を強力に配置してというところでの支援という体制は伺っておりますけれども、ＩＣＴ支援員というところの支援で事足りるものなのかどうか。","respondent":"工藤指導課長","answer":"教員の体制としては、各学校にＩＣＴ推進の教員を位置づけて、その教員に対する研修も踏まえながら、またその教員による伝達研修も行いながら、また様々なことで情報も共有しながら、授業の効果的な活用というのは図っていきたい、そのような体制を考えているところです。","id":"exchange-109"},{"speaker":"塚本委員","kind":"質問","question":"この辺はＧＩＧＡスクール導入にとって非常に問われるところだと思いますので、また改めて取り上げていきたいと考えています。あるいは、例えば校長会などをＺｏｏｍでやったりしたなどということがあったり、この先やるかもしれないのか。そういった、教員における現状のオンライン活用の様子というのをお伺いしたいと思います。","respondent":"工藤指導課長","answer":"副校長連絡会は、オンラインで配信して行うであるとか、そういったところで活用も進めてありますので、研修をオンラインで進めるということも併せて進めてありますので、そういったところで活用を図って、またその活用の仕方も共有を図っているです。","id":"exchange-110"},{"speaker":"塚本委員","kind":"質問","question":"教職員の方々がしっかりとそういった機器に慣れるというか、少しでも親しむというか、やはり慣れるということですか。そういう意味では、今、使えるところからどんどん活用していけるようにしていくということも、１つの方策かと思いますので、そういった部分では積極的に、今後とも教職員の間でも使っていくような場面をつくっていくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"私からは、３５０ページ、学務費になるのか、３０人学級について少し。それから３５３ページの就学援助費、３５５ページ、生徒指導対策等経費から痴漢防止について、それから３６７ページ、学校ＩＣＴ活用経費、時間がありましたら、３５５ページの帰国児童・生徒等支援費についてもお伺いしたいと思います。それから、就学援助費。既に実施したこと、または計画していることがあれば教えてください。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"３０人学級に絡みまして、今後の校舎改築等の対応です。基本的には、私どもでは将来的な人口推計を見据えながら、現状の学級編制を基本に、今後どうしていくかということで、校舎改築等につないで整備しています。委員ご指摘のとおり、コロナ禍で、外部の人を呼んでの講習というのはできておりませんが、生活指導主任会が定期的にありますので、今のような内容について一度確認しまして、また周知を広めていきたいと考えております。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問・要望","question":"各自、今年は特に時数がタイトであるということも承知しているので、あれをやれ、これをやれなど、なかなか言いにくいのですけれども、ただ、やはり大切に育てて卒業させた子どもが、憧れの高校に入ったのに、通学途中に痴漢に遭って、怖くて学校に行けなくなってしまうというようなことは、もうこれ以上起きないようにしてほしい。ぜひ工夫していただきたいと思うので、今後について一言頂ければと思います。","respondent":"矢部教育総合支援センター長","answer":"委員のご指摘のとおり、もう一度確認して、できる範囲の中で進めてまいりたいと思います。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"６月の一般質問でも伺いましたけれど、病気やけがなど長期療養中の児童・生徒への活用は、検討状況はいかがでしょうか。ここは、ぜひ急いでやっていただきたい、整備していただきたいと考えています。それから、学校内の教員以外の講師あるいは学校図書館司書など、教員以外の方もぜひＩＣＴの力を活用していただくことで、より学校をパワーアップしていただきたいと思いますが、いかがでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長、篠田学務課長","answer":"それで、持ち帰りに関しては、重さもありますので、そういったときには柔軟に、これまでの例えばルールを変えて、今、配備いたしたタブレットは。ただ、物が行くだけでは活用がうまくいきませんので、そこについては十分、間を詰めて丁寧に対応して、ぜひ円滑にできるようにと考えております。基本的に、今回のＧＩＧＡスクールに関しましては、全ての子どもと教員というのがベースになっていますけれども、現実にはそのほかの形で、いろいろな形で。","id":"exchange-114"},{"speaker":"あべ委員","kind":"質問・要望","question":"それぞれ取組みも進めていらっしゃるということで大変安心しましたが、やはり学校によって、まだまだ取組みの具合に差があると思います。それぞれグッドプラクティスを見習いながら、品川区全体の教育の底上げをしていただければと思います。外国人児童・生徒に対してもオンライン授業が始まっていると聞いております。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、３７５ページ、第１目学校管理費、保健運営費から、学校における新型コロナウイルス感染症について質問いたします。このマニュアルも踏まえながら、この間の品川区の、学校における新型コロナウイルス感染症対策についてお伺いしていきたいと思います。品川区はどの感染レベルに相当すると教育委員会は考えておられるのでしょうか。お知らせください。","respondent":"有馬庶務課長","answer":"基本的には、これまでの国の通知や都の通知といったものを踏まえまして、区では区立学校における感染症のガイドラインというものを設定しておりますので、それに基づいて、今、対応しています。","id":"exchange-116"},{"speaker":"鈴木（博）委員","kind":"質問","question":"品川区は、品川区の独自の基準と考え方で感染レベルを設定しているというお話と理解いたしました。以下、具体的に質問してまいります。品川区では子どもたちにどのように感染予防について教え、理解させているのでしょうか。特に教職員の目が届かないところでの注意事項など、具体的な取組みについてお示しください。","respondent":"矢部教育総合支援センター長","answer":"臨時休業中から、通知や学校ホームページによって、感染症予防策、３密を避けた行動等について、ガイドラインによって周知しています。現在は、区で作成している感染予防ガイドラインにのっとって、３つの密の回避を徹底すること。","id":"exchange-117"},{"speaker":"鈴木（博）委員","kind":"質問","question":"一般質問に引き続き、マスクについて再度お尋ねします。文部科学省の衛生管理マニュアル「学校の新しい生活様式」によれば、マスクは密接に対する処置であり、学校の教育活動においては、児童・生徒等および教職員は身体的距離が十分に取れないときはマスクを着用するべきと記されています。併せて、フェイスシールドやマウスシールドなどについても、教育委員会のご見解のご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"ただ、お子さんによって（マスクを）したい、外したいというお子さんもいますので、個別に対応しています。","id":"exchange-118"},{"speaker":"鈴木（博）委員","kind":"確認","question":"ただし、医学的ファクトがない場合、例えば熱中症の危険がある場合など、マスクが必要ない場合、あるいは医学的に例えば荒れるとか、そういう場合というのは、無理にさせる必要はないということで、小児科医、臨床医の間では統一見解が出ております。次に、出席停止について少しお伺いします。皆勤賞なるものは、既に今、小学校ではなくなったと考えてもよろしいのでしょうか。その確認もお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"皆勤賞につきましては、教育委員会が示したものではなく、各学校で、また、もしかしたらクラスでつくっている場合もあるかと存じますけれども、そこは学校の裁量で、それを楽しみに来ている子どもも実際にいましたので、そういう裁量になってあります。","id":"exchange-119"},{"speaker":"鈴木（博）委員","kind":"質問","question":"このためにわざわざ無理をして学校に行くような、非常に誤った風潮なども助長することになりますので、認めるのではなくて禁止する方向で、学校の対応をぜひお願いしたいと思います。先ほども質問がありましたが、コロナ流行下においても、児童・生徒の適切な栄養補給と食生活を支援するために、感染リスクに配慮しつつも積極的に進めていかなければならないと考えます。","respondent":"篠田学務課長","answer":"現状の学校給食についてご説明いたします。基本的には、一人ひとり個別に授業のスタイルで、間を取りながら前を向いて会話しないで給食を取るという形が子どもたちのほうの対応です。","id":"exchange-120"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今回、決算特別委員会を通して行ってきた、私の新型コロナウイルス感染症に関しての一連の質問は今日で終わりますが、新型コロナウイルス感染症は高齢者では今でも非常に恐ろしい病気です。感染予防策は大切です。感染予防策それ自身を絶対化することなく、血が通い、温かみのある配慮を加えることによって、それで運営してこそコロナと共存する新しい生活様式だと確信して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、３５２ページ、教育指導費に関連して、性教育について伺いたいと思います。性の正しい知識、それに伴った行動が重要だということで、性教育の充実を求めてきましたけれども、先日、アフターピル、緊急避妊薬を薬局で購入できるようにするかどうか、こうしたことの議論がＮＨＫなどでも報道されておりました。そこで注目が集まっているのが、日本の遅れた性教育です。区は遅いと思いませんか。","respondent":"矢部教育総合支援センター長","answer":"実際の指導には、水着の隠れる部分は見せたり触らせたりしないようにという指導は、日常的に小さな子でもやってあります。ＣＡＰやセーフティ教室の中でも、犯罪被害の防止に努めているところです。","id":"exchange-122"},{"speaker":"石田（ち）委員","kind":"質問","question":"その学習指導要領が問題というか、本当に遅いと私は思うのです。１４歳、１５歳で妊娠している状況です。産婦人科医の先生方からも、望んでいるならいいのですけれども、やはり望んでいない、そして予期せぬ、そうしたことが１０代には多いと。そうしたことも含めて教えてもらえたらと私も思っています。性の権利を守り、そして学び、男女ともに学んでいくことが必要だと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ただ、現状において、日本において、やはり一番大事なのは、暴力の加害や被害、また傍観者にならないということが一番基本だと考えておりますので、学年の発達段階に応じて進めてまいりますが、国も性被害防止については検討していますので。","id":"exchange-123"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり、そうした性被害の防止についても、お互いの体を知り、そしてどうしたらどうなってしまうのかというのを、早い段階から教えていくことが必要だと思うのです。これは何回も言わせていただくのですけれども。性は、生きていく上では切り離せない、幅広く深いものですので、私はやはり包括的性教育をしていただきたいと。そこはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"学習指導要領にのっとるのは先ほどのとおりですが、教育会では、体育部門、保健部門がありますので、そちらのほうでの検討でいろいろな授業が展開される可能性はあります。","id":"exchange-124"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"幾らそこで、それは駄目なのだというのを教えても、全体的に体の仕組みから、どうするとどうなっていくのかということ、そして性的アイデンティティや性的指向ということも含めて早い段階から教えていかないと、結局、暴力につながっていってしまうと思います。ぜひその立場に立って、学校教育要領を含めて抜本的に見直していただきたいと思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"本区の学校教育要領も学習指導要領を基に進めてありますので、意見は分かりましたけれども、発達段階に応じて、今、計画的に進めているところですので、あくまで人権尊重を基盤にして、各教科・領域において指導してまいりたいと考えております。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"ご見解を聞きますけれども、これ以上、生産者をいじめないでほしい。しっかりと法にのっとった形で、必要であるならば国が放射性物質のチェックをするという方向を示すべきであるわけであって、品川区が安全なものを提供しているということであるならば、放射性物質の検査についてはやめる方向でお願いしたいと思いますが、その見解をお聞きします。それから３５５ページ、教育指導費になるのでしょうか。","respondent":"篠田学務課長、品川財政課長、有馬庶務課長、矢部教育総合支援センター長","answer":"やはり検査をするということは、それなりに経費もかかりますし、また労力もかかってくるということがありますので、こういった実情を鑑みながら。今後、毎年１校から２校ぐらい、今、改築を進めているのですけれども、ここに対して充当していくために基金を積み立てていっているというものです。８３運動につきましては、委員ご指摘のとおり、今、小学校ＰＴＡ連合会が中心になって、推進委員会が発足してということですので。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、改めていただきたいと思います。積立金についてですが、これは５０億円というのが毎年積み上がっていくという、一定金額を積み上げていくというものなのか、あとは、今後増やしていくとか減らしていくなどというのは、どういう観点で、先ほど、年に１校、２校という形でということなのですが、その辺の計画、長期にわたっての計画があるのかを確認したいと思います。ここをお聞きしたいと思います。","respondent":"品川財政課長、矢部教育総合支援センター長","answer":"こういうところにも応じて、積立額というのは状況を見て変えていこうと考えています。今後、学校改築が続きますので、それを維持できるような形で、資金もしっかりと準備をしていきたいと考えております。直接電話で頂くこともあります。少なくとも、悩んでいる保護者が多いので、学校名が分かれば、こちらから連絡をして、学校のほうで丁寧に対応しています。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問","question":"問題行動を起こす保護者の方々ですが、これは多分、認識されている部分はあるかと思うのです。私も幾つか相談を受けております。そして、一番心配なのは、お子さんたちなのです。そこのところの認識はどこまであるのでしょうか。その場合の、例えば弁護士を雇う、相談に乗るなどという体制は、どのぐらいまでできているのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"子ども家庭支援センターとも連携しまして、必要に応じて、福祉や医療（の部門）とも相談して進めてまいります。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３５１ページ、８３運動経費、３６１ページ、特別支援教育費、３６５ページ、図書館運営費からお伺いしたいと思います。８３運動経費は、関連して、ＰＴＡの方や地域の方々と区と協働で取り組む、児童・生徒の登下校における安全対策・防犯対策についてお尋ねいたします。","respondent":"有馬庶務課長","answer":"８３運動の見守りの効果ですが、これをどういうふうに検証するかというのは、なかなか難しい部分があるかと考えております。","id":"exchange-129"},{"speaker":"こんの委員","kind":"質問","question":"先週の総務費のところでも触れましたけれども、警視庁が発信している「メールけいしちょう」という不審者情報、こうしたメールはご存じでしょうか。昨年１年間で届いているメールけいしちょうは約１００件ありまして、これを換算すると、三、四日に１件、発生していることになります。こうした状況が見られます。こうした取組みは必要ではないかと考えるわけですが、いかがでしょうか。","respondent":"有馬庶務課長","answer":"最初の質問で、防犯の意識は、８３運動に関わってくれている方は、誰もがそういう防犯の意識ということで子どもを見守ってくれている、それは間違いありません。それをどういうふうにはかるかというところは難しいという説明をさせていただいたものです。","id":"exchange-130"},{"speaker":"こんの委員","kind":"質問・要望","question":"１つには、情報共有ができる環境もなくはないというところですが、それをさらに広げていくようなお考えで、情報を共有しないと、なかなかどこがどういうふうに見守っていいのか。せっかく防犯意識を持っていただいているのであれば、その見守りを効果的にしていただくような方策を、ぜひ今後、考えていただければと、要望で終わります。この事業に対する令和元年度の事業の総合評価は、Ａとなっておりました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"特別支援学級の数です。１３学級あります。それと、学級数は、令和２年度、固定級が２５学級、通級が７学級です。区内での異動の場合にも、経験者を配置する。初任者あるいは経験年数が浅い教員が提示されることもありますので、そういったバランスをよく見ながら、継続した支援ができるよう配置を行っているところです。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"そういう状況の中だと分かったのですが、実態は、お子さん方、いわゆる児童・生徒に対応する先生の対応力と言うのでしょうか、保護者とのコミュニケーションの取り方というのでしょうか。その辺のところは、専門家の方が視察し、そして助言していく、指導していく中で、どのようなコミュニケーション、指導力といったことへの指導というのはあるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ただ、そのときには、今、若手の特別支援教室の教員などもおりますので、ベテランと一緒に対応しているようなところです。そのほか、３年次までの教員には、一般的に研修が３年間ありますので、その中で特別支援教育の研修も行ってあります。","id":"exchange-132"},{"speaker":"こんの委員","kind":"提案","question":"今お話を伺って、とすると、なかなかコミュニケーションの取り方、また指導・育成は、それぞれの感じ方や、コミュニケーションは本当に取りにくい、難しいところでもあると思いますけれども、児童・生徒の育成には、保護者のご協力も大変に大事だというところも考えると、先生と保護者の方との信頼関係はお子さんにとっては本当に大事なところだと思いますので。","respondent":"横山品川図書館長","answer":"図書館で検討いたしまして、ティーンズの担当を中心に、ＳＮＳでの発信であるとか、ＹｏｕＴｕｂｅの利用だとかについて、現実的に検討できるかどうかというのを、今、計画立てて進めているところです。","id":"exchange-133"},{"speaker":"こんの委員","kind":"質問・要望","question":"学校図書館においては、著作権のことも、先ほどの答弁を聞いて理解しているところです。近い将来、著作権のことなどの課題がクリアになったならば、学校図書館の本がタブレットで見られる。こうした環境を作っていけるよう要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校地域コーディネーターです。そうすると、今までですと比較的、時間の動きが取れたような状況が、職員ということで拘束されてくるのではないかと想像するのですけれど、その辺のところは影響がないのかどうかということを１点確認させてください。その辺の規定があるのかどうかも確認させてください。そういうことがないと思うのですけれど、その辺の関係も教えていただければと思います。","respondent":"工藤指導課長","answer":"会計年度任用職員になったとしても、１年ごとの任用ではありますが、それを継続することは可能ですので、そういった意味では、同じ方、続けていただける方がそのまま続けていただけるような状況です。","id":"exchange-135"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"本当に、学校と地域をうまくつないでいる方なので、これからも校区教育協働委員会とも協力しながら、いい形で進めていっていただきたいと思います。その上で、今回、質問の中で、品川コミュニティ・スクールというのはあまり出ていなかったので、品川コミュニティ・スクールにかける品川区の思いがもしあれば改めて一言頂ければと思うのですが、よろしくお願いします。","respondent":"工藤指導課長","answer":"今、全校で展開しています品川コミュニティ・スクールですが、やはり地域とともにある学校づくりの中で、校区教育協働委員会の中には、卒業生、また地域の方も含まれるというところで、本当に学校が地域の中のコミュニティの拠点として。","id":"exchange-136"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これも要望にします。２点目に、学力向上プラン推進事業の勉強合宿についてです。８年生が今、行っていると思うのですけれど、この取り組み状況を教えていただければと思います。","respondent":"工藤指導課長","answer":"勉強合宿についてのお尋ねです。ご指摘いただきましたように、８年生の夏季休業中に集中的に学習に取り組むという事業です。現在、義務教育学校６校と中学校、合わせて８校で実施しています。宿泊型で行っているのが４校、通学型が４校ということで取組みを進めているところです。","id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問","question":"分かりました。ただ、少し気になっているのは、今８校だけがやっている中で、やはり全校展開できないのかなという思いもあります。それから夏の間ですから、クラブ活動とか、いろいろな問題が絡んでくるとは思うのですけれど、やはり全員が受けられる体制も取ってほしいと、これは希望なのですけれど、その辺のお考えを教えていただければと思います。","respondent":"工藤指導課長","answer":"そういった意味では、先ほど申し上げた宿泊日数であるとか、例えば通学型から始めるとか、できるところからスタートするような工夫なども併せながら、また支援にあたる、指導にあたる人材の確保なども、併せて取組みを進めて、拡充を図っていきたいと考えています。","id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう一点、学芸大学との連携のプロジェクトです。これが、就学援助を受給しているご家庭の６年生の勉強の機会をつくってもらっていた中で、これは今年の予算には入ってきていなかったので、その辺の進め方について、指導という点でお考えを教えてください。","respondent":"工藤指導課長","answer":"学芸大学の連携事業ですが、こちらにつきましては、東京学芸大学と連携して、学習支援と、また学芸大学附属中学校への進学支援を行うという事業でございました。当初、予定していました３年目ということで、令和元年度におきまして学習支援については終了したところです。","id":"exchange-139"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、昨年度でそれが終わってしまったのですけれど、これからの進学支援ということにどのようにまた取り組んでいくのかについてと、それから、現在、学芸大学附属中学校に行っているお子さんに対する、品川区教育委員会として何かフォローしなくていいのかというのも少し感じているのですけれど、やはり少し離れた学校に行っているところで、その辺は何か考えていらっしゃるのかどうか。","respondent":"工藤指導課長","answer":"そういった補充学習のところで、またそれは、自分が通っている学校で開かれている未来塾に通うことができるというところで、学習支援は行っていけるとは考えてありますが、いわゆる補充学習等につきましては、しっかりと取り組んでいきたいと考えています。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"３５５ページ、教職員研修。教職員研修。この若手の教員の方にどのようなアドバイスをしていただけるでしょうか。もちろんないと思いますが、品川区ではこういうことはないのでしょうか。ほかの学校でも、全てのページは難しいかもしれませんけれども、このような取組みをお願いしたいと思いますが、お考えを伺います。あれば、工事の方あるいは教職員、児童・生徒にけがなどはなかったのでしょうか。","respondent":"工藤指導課長、矢部教育総合支援センター長、小林学校施設担当課長","answer":"やはりそういったところを、同じ学年で、あるいはチームの中で、しっかりと取り組んでいくという姿勢が必要であると考えますので。学校だよりの振り仮名等ですが、本当に優しい対応だと感じております。確かに時間はかかりますけれども、好事例として紹介していきたいと思います。改築工事での現場での事故というのは、ないものと記憶しております。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほどの学級通信の例は品川区ではないと思いますので、もし仮にそういうことがあったとしたら、チームで指導していただきたいと思います。改築は承知しました。そういったところを地域未来塾でどのようにカバーしていらっしゃるのでしょうか。補習という観点でどのようにカバーしているか、また実施日数を増やすなどの、あるいは財政支援等で支援していただきたいと思いますが、いかがでしょうか。","respondent":"工藤指導課長","answer":"地域未来塾につきましては、学校再開と同時に各学校、予定に従いまして進めることができております。そういったところでは、放課後補充学習として、指導員の方からのサポートがありながら進めているところです。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"授業については、授業時間数確保ということで、授業がかなりハードな形で進めていると思いますので、１つのフォローとして地域未来塾の活用をお願いいたします。次は学校ＩＣＴ化ですが、いろいろな委員の方から質問が出ておりましたので、そこと重ならないようにＩＣＴ支援員についてお尋ねします。どのような方が何人ぐらい学校を巡回しているのでしょうか。日数等は先ほど伺いました。","respondent":"篠田学務課長","answer":"現在は、ＩＣＴ推進校１０校を中心に回ってあります。推進校は毎月１回、それ以外の学校は学期に１回回っているという形です。回っているのは、民間のコンピュータ関係に詳しい方で、教育情報化コーディネータ２級という資格を持った方が回るという形で契約しています。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、教育情報化コーディネータという資格をお持ちの方ということで、この資格をお取りになって、いろいろな人材派遣のところに登録し、学校を巡回している方が多いと伺っています。この後、タブレットが支給された場合に、どれぐらいの頻度で学校を巡回していただけるのでしょうか。","respondent":"篠田学務課長","answer":"したがいまして、かなり手厚くやっていく必要があるとは考えてあります。予算との絡みもあるものですから、今のところ、様々検討しているところではありますけれども、少なくとも今まで以上の形での配置をしていきたいと考えているところです。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"それともう一つは、機械が調子が悪いとか、つながらないとかだけではなくて、やはりＩＣＴ支援員の一番大事なところは、熊本市の教育委員会の方がおっしゃっていましたが、授業の教材づくりにどこまで協力できるかということで、学校の授業の中身と、それを授業でどういうふうにするかということの理解がある方が、ＩＣＴ支援員になり、そして教員が教材をつくるところでアドバイスし。","respondent":"篠田学務課長","answer":"教員と一緒に教材等の作成ですけれども、これは現実に、今の支援員もかなり、各学校を訪問した際には、一緒に教材研究・作成等を手伝っているところがありますので、引き続き今後もそういった対応が取れるような体制を取っていきたいと考えているところです。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"意見","question":"週１日だと８,０００万円余ということですので、手厚くお願いいたします。","respondent":"篠田学務課長","answer":"これから、今まで入られた方も加えて、新たな方も入ってこられますので、きちんと学校と連携した形で、実のあるものとなるように、私どもも注視してまいりたいと思っているところです。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"卒業を迎える学年の児童・生徒に３月末までに指導すべき内容の指導を行うことができなかった場合、当該児童・生徒の卒業を認定するのかを教えてください。そして、児童・生徒の学習保障は、実際、本当にできるのでしょうか。学年ごとに必要な学習が身についていると、どのようにして判定するのですか。そして、判定テストでも行って、身についていない児童・生徒がいた場合、補習や再テストを行うのですか。","respondent":"工藤指導課長","answer":"学習の保障に関するお尋ねです。４月当初から臨時休業が続いたことで、授業日数としては３４日間ほど不足したところがあります。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"きちんと答えてください。だったら、授業がきちんとできていない、身についていないということではないのですか。もう一つ質問しますので、その後にお聞かせください。自主欠席を行うことで、児童・生徒の学習にさらに遅れが生じることが予想されますが、この辺について学習保障はきちんとできるのですか。教える日数が少ない。だったら、子どもたちはどういうふうにされるのですか。教えてください。","respondent":"工藤指導課長","answer":"必要な事項については指導しています。様々な理由で出席停止扱いということで、学校に登校しない場合でも、各学校の担任からは課題を渡し、その課題について添削する。そういったところで学びを止めないという動きは、学校がしっかりと取り組んでいるところがあります。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"今、日数が少なくて、いや、家庭でテキストを持ち込んでやると。だったら、学校は要らなくなるのではないですか。だったら、補習なり何なりきちんと、やはり教育委員会としてもっと、夕方に勉強、補習をするとか、どこかで補うとか、土曜日も今、休んでいるわけですけれど、そういうのも使って、できるだけ遅れないようにやるべきだと私は思うのですが、もう一度お考えをお聞かせください。","respondent":"工藤指導課長","answer":"いわゆる知識・理解などの学力だけではなく、コミュニケーションを取りながら、対話をしながら進める学習というのは非常に重要であることは、私どももコロナ禍の中で再度認識したところがあります。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"私がしっかりと考えてほしいのは、学力格差が広がってしまうのです。それについては、私はしっかりと考えていただきたいと思います。通常で、今の状態でも格差がある。その中で、１つここでお聞きしたいのですが、オンライン教育・授業のメリット・デメリットを教えてください。品川区はオンライン授業を発展させていくつもりなのか、そしてデメリットについてどういうふうにお考えか、教えてください。","respondent":"工藤指導課長","answer":"オンラインで行う教育というのは様々な展開が考えられるところがあります。現状、オンラインで取り組むというところで、今、学校で進めているもので言えば、ゲストを招いたような学びというのは、コロナ禍の中では非常に難しいところがあります。","id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"だったら、こういうことをどうして教育委員会は考えていないのですか。これは民間企業もそうなのです。今、テレワーク、オンラインから、やはり対面式にするべきだという会社が増えつつあります。ですけれど、その辺も考えて子どもたちの教育というのを見ていく、そしてずっと考えて見守っていくということが、教育委員会として大事なことだと私は思うのですが、いかがですか。ご見解をお聞かせください。","respondent":"工藤指導課長","answer":"やはり有効な点は教育活動に取り入れながら、学校という場で授業を行いながら育むべき資質・能力を最も大事にしていくというのは、これまでと同様に変わらずに進めていきたいと考えています。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、そういうお話をお聞きしました。きちんと医学会で報告もされています。やはりそういうところも勉強していただいて、きっとやっていると思うのですが、やはり将来、この子どもたちをどういうふうに学ばせていくのだ、そして、社会へ立派に飛び立てるようにできるのだということを考えながら、教育というのを見ていただきたいと私は思います。何かご意見があったら、最後に一言言ってください。","respondent":"工藤指導課長","answer":"頂いたご意見がありますけれども、私どもは、やはりオンライン教育というもののよさを活用しながら学校教育を進めてまいります。","id":"exchange-152"},{"speaker":"安藤委員","kind":"質問・要望","question":"３６３ページ、教科書採択事務、３７３ページ、普通教室増設工事等に触れながら、少人数学級について伺います。伺いますが、教科書採択はイニシャルでなく教科書会社名で報告・審議することと、あと教科書展示の区民意見の報告内容は、委員が採択する上で十分な資料になり得るような、意見総数など数字の報告も含めて充実すること、以上２点を改めて求めたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"１点目のほうは、分かりやすい教科書採択に向けまして、私どもも次回の採択に向けて検討してまいりますが、１つは、イニシャルでというのは、小学校でしたら１年から６年までの教科書に何社も手を挙げて発行しているものですから、物凄い数が机の上に乗りまして。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の説明を伺っても、私は、イニシャルで、何でわざわざ傍聴者が分かりづらいやり方をするのかというのは、言葉は悪いですけれど、へ理屈にしか聞こえないというか、教育委員がその場で、そんなにもう、一から十まで全部の教科書を読み上げているのかというと、そんな実態はないと思いますし、やはりどういう教科書が採択されるかというのは、別に立場がどうであれ、住民の関心事なのです。大事な関心です。","respondent":"篠田学務課長","answer":"ただ、やり方ですけれども、様々な形で、今、学校にある多目的室ですとか、あるいは少人数学級用に今、設置しているような部屋で、そのまま部品だけを入れれば使えるような部屋もあるのですけれども、やはり中を工事で改築した上でないと教室を転用できないところに関しては。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問","question":"もう一点伺いたいのですが、これらのように、現状、普通教室増設に使える多目的室などの教室は、これから改築していくというところはあるでしょうけれど、区内全体で、まだ改築していないところも含めてどれだけあるのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"実際には、普通教室化するための部屋ということではございませんで、いろいろな形で活用していますので、必ずしもきちんとした形での把握は難しいと考えているところではあります。","id":"exchange-155"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれど、本来なら２６人なのに３９人、本来なら３０人なのに小学校１年生から４０人というのは、加配をしたとしても、子どもにとっても教師にとってもよくない選択だと思いますが、いかがでしょうか。なぜ素直に学級数を増やさずに、加配を選択しているのか、やむを得ない理由でもあるのか、あるならその解決に区教育委員会は援助しているのか、伺いたいと思います。","respondent":"篠田学務課長","answer":"１年生に関しましては、学級編制、法律でも３５人と定められているところですけれども、特例的に４０人での対応も可能であるという形です。それに基づいて、委員ご指摘のような事例が発生しています。","id":"exchange-156"},{"speaker":"安藤委員","kind":"質問","question":"１年生から４０人というのは、考えられないといいますか、そういうところにこそ、お金を使うべき。私は、そういう課題があるのだったら、何かその解決に区教育委員会は援助しているのかと伺いましたので、伺いたいと思います。そして、文教委員会などでもありましたけれど、区が独自に加配する区費講師、そういう方もいらっしゃるということなので、その人数も伺いたいと思います。","respondent":"篠田学務課長、工藤指導課長","answer":"私どももできるだけそういう対応は取っていきたいとは考えているところですけれども、先ほど委員からご指摘のあった第二延山小学校や小山小学校というのが、実は改築が済んでしまっている学校という特殊要因がございまして。区で少人数指導を進める、また、あるいは教科担任制を進めるために区費講師として任用している者は５９名です。","id":"exchange-157"},{"speaker":"安藤委員","kind":"質問・要望","question":"こうした費用と人材措置をさらに強めた上で、区独自にクラスの規模を減らすということのために充てるべきだと私は思います。伺いますが、少人数学級を見据えて、また現在の加配や区独自教員なども活かし、区独自で学級規模を減らすことを目標にして、教室の増設、学校の増設、教員の増員を検討するよう求めますが、いかがでしょうか。","respondent":"篠田学務課長、工藤指導課長","answer":"ですので、そうなりますと当然、学校の環境が悪化するといったこともありますし、委員から学校の増設というお話もございましたけれども、学校を増設するにあたっては、１つの小学校を造るには、最低でも七、八千平米の土地が必要ですし。先ほど報告いたしました、区でつけています講師や、少人数指導また教科担任制を推進する上での取組みは、引き続き進めていきたいと考えています。","id":"exchange-158"},{"speaker":"安藤委員","kind":"質問・要望","question":"コロナ禍を経て、大きく考え方も変わってきております。子どもたち第一に、ぜひ少人数学級に、区として前進していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私からは、３５５ページ、生徒指導対策費に関連して、また３６６ページ、学校管理費に関連して伺います。それは、５年生と７年生というのは、なぜそうなのかということの理由が分かれば教えてください。予算特別委員会で、会派の委員から、あくつ委員長なのですが、質問させていただきまして、隣の都営住宅との関係で、あそこは台場と言うぐらいですから、非常に海抜が低いという中で、小学校が３階建て。","respondent":"矢部教育総合支援センター長、小林学校施設担当課長、篠田学務課長","answer":"委員ご質問の１番目と３番目についてお答えいたします。１点目、スクールカウンセラーの全員面接です。現在、取付け位置および取付けの方法などを検討しております。今後、都なども含めて協議して、取り付ける方向で考えていきたいと考えています。新型コロナに感染した児童・生徒の数ですけれども、昨日時点で、今、１０名です。学校の数で言いますと５校です。","id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"スクールカウンセラーについては、では５年生と７年生、東京都のほうからそういうお話だということ。それで、今回のコロナ禍を受けて、例えば今までの相談の数に比べて今回少し増えてきているのだとか、具体的な数の報告なども取られているのかどうか、分かれば教えてください。都営なので、勝手にできないので、その上で、またさらにやりますということだと思うのですけれど、一応確認させてください。","respondent":"矢部教育総合支援センター長、小林学校施設担当課長","answer":"続きまして、スクールカウンセラーの実施状況ですが、昨年度は５２人の配置で、１万６,５１０件という数字が上がってありますが、４月から６月についてはお子さんがいないということもありまして、ほぼ実績はございません。そのとおりでございまして、今後、取り付けていくよう進めてまいりたいと考えております。","id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問・要望","question":"スクールカウンセラーについては、よく分かりました。きちんと件数も確認されているということで安心しました。それで、今お聞きしたところですと、５年生・７年生だけではなくて、全校に週１回ですか、配置されているので、５年生・７年生以外のところでも、相談したければ対応できるということですよね。台場小学校は分かりましたので、ぜひとも進めていただければと思いますので、よろしくお願いします。","respondent":"矢部教育総合支援センター長","answer":"思い出づくりのほうは、これまでどおり、学校の工夫を活かしてしっかりと努めていきたいと考えております。","id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"３５３ページ、教育指導というか、受験指導について伺います。それと、図書館かとは思ったのですけれども、先ほど品川図書館長のお話の中で、青空文庫を利用したことによって、読書をする、何か習慣というか、大いに効果を上げているということなのですが、そこの取組みについて、今、通告した質問の前に聞かせていただきたい。","respondent":"横山品川図書館長","answer":"こちらについては、有識者の呼びかけで、名作を中心に１万６,０００点ほどの、著作権が切れた本等をストックしているもので、こちらは誰でもアクセスできるような状態になっているところなのですが。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"すみません。泉鏡花があったり露伴があったり藤村があったりということで、ここのところはどういうふうに、そういう新聞の記事が載っているわけですから、利用しない手はないと思うのですけれども、今後そこのところをうまく利用しながら、夏目漱石もいっぱい載っていますので、三部作も載っていますので、これは大いに利用していただきたいと思うのですけれどもいかがでしょうか。","respondent":"横山品川図書館長","answer":"」という動画を配信したり、塗り絵とか、それぞれの小さな子どもから取り組めるようなもの、またサイトも青空文庫だけでなく、国際子ども図書館や、福井県立恐竜博物館や、ＪＲ西日本のペーパークラフトなど、いろいろなものを紹介する形で、切り口として、読書ではないですが。","id":"exchange-164"},{"speaker":"大沢委員","kind":"質問・要望","question":"少しあれなのですけれども、コロナにおいて、中学３年生の受験指導について伺いたいと思いますが、歳入のところで質問させていただきましたけれども、私は、現場、そして生徒、もう一つ、塾ということで、お話を聞いた部分がありまして、これは主観もあるでしょうけれども、大体、今、先生方、生徒も、そのようなことを感じていらっしゃるのではないかと思いまして、一つ一つ伺ったことを。","respondent":"工藤指導課長","answer":"ですから、指導面におきましては、先ほど指摘がございましたように、理科の場合には、一部の単元の中で、さらにその一部を除外するという表記といった、東京都教育委員会からの説明です。ですので、やはりその内容も全て含めて履修をしっかりと行う。","id":"exchange-165"},{"speaker":"大沢委員","kind":"意見","question":"主人公である生徒の声なのですけれど、９年生。範囲を狭くして受験生の負担を減らした意味がなく、かえって曖昧な範囲をめぐって余計な心配が増えただけだと思う。緊急時だからこそ、範囲を狭くしたのなら、国立・公立・私立で足並みをそろえてほしい」ということで、主人公である受験生の声ですけれども、これについてはどういうふうにお考えになりますか。","respondent":"工藤指導課長","answer":"確かにそのようなお声があるということは認識しているところでもあります。ただ、学校におきましては、指導内容をきちんと定着させるという観点で、生徒に対しても指導して、確実に定着するというところをもって安心していただければと考えています。","id":"exchange-166"},{"speaker":"大沢委員","kind":"質問・要望","question":"塾なのですけれども、塾は、区の範囲外なのですが、塾の先生、たまたまそこだけだったので、あまり重く捉えていただかなくて結構なのですけれども、都の教育委員会に範囲確認の電話をしてもらちが明かないというようなことなのですが、これはもう結構ですけれども、ぜひとも東京都と、そこのところを密に取っていただきたいと思います。","respondent":"工藤指導課長","answer":"そういったことの関連で、やはり児童・生徒のよりよい成長のためにお互い協力して進めていくということが必要であると。そういった役割というのは、やはり子どもを中心にしてお互い協力していくことだと認識しています。","id":"exchange-167"},{"speaker":"大沢委員","kind":"質問","question":"ところが、最近というか、もう近年になりますか。最近ということではなく近年でありますが、親と先生がお互いに、何というのでしょうか、干渉するような、干渉し過ぎてしまって窮屈になってしまっているようなところが散見されると、私は感じるところがあるのですけれど、その辺は、現場をご覧になっていて、どういうふうに課長は考えられ、お感じになられているのか、教えてください。","respondent":"工藤指導課長","answer":"ただし、声をかけることは非常に大事であるとか、反応がなくても声かけを続けることが大事であるとか、そういったポイントを絞りながら、つかず離れず、また、つくときはつくと。やはり干渉する度合いなども必要に応じて助言したりして行っているところです。","id":"exchange-168"},{"speaker":"大沢委員","kind":"意見","question":"まさに私も同感でありますが、近年、やはり携帯電話とか、いろいろな文明の利器のさらなる普及によって、つかず離れずが逆に過干渉になって、子どもも先生方も親御さんも疲れ切っているという部分が大いにあるのではなかろうかと私は思っています。そこで１つ、主人公である子どもたちには、やはり逃げ場が必要だと思うのですけれども、逃げ場について、課長はどのようにお考えになりますか。","respondent":"工藤指導課長","answer":"誰か一人でもつながることが、その子の未来を開くことになると信じて進めていくことだと思ってあります。","id":"exchange-169"},{"speaker":"大沢委員","kind":"意見","question":"やはり人間である以上、息抜きも必要であると思います。綱を引っ張った状態では、いつかはほころびが出るわけでありますから、そうではなくて、ぜひとも幾らか余裕を持った教育、余裕を持った子どもたちに対する接し方であってほしいし、そういう知識であってほしいと思います。希望で終わらせてもらいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"提案","question":"先ほど来出ている思い出づくりのことについて、伺いたいと思います。そういうことも含めると、やはり教育委員会の中で提案していくということが必要だと私は思っています。それで、教育委員会に聞くと、いや、まず学校から提案してくれと。これがバス、陸です。だけど、そういうところでやれるというのも１つの提案であって、こういうところをぜひ考えていただきたいと思いますが、ご見解を教えてください。","respondent":"矢部教育総合支援センター長","answer":"現在、学校では、コロナ禍の中で感染予防対策を講じながら、子どもたちの学びの保障、不安やストレスへの対処に努めております。そのような中で、移動教室などの行事はほとんどが中止となっており、６年生の今後の支援は特に大切であると認識しています。","id":"exchange-171"},{"speaker":"石田（秀）委員","kind":"提案","question":"今言ったように、学校が相談するのではなくて、教育委員会が、こういうことがあるから、予算もあるから、やってあげたらと言ってやらないと、では提案しろと各学校にみんな言って、「こういうことをやってよ」と言うのか。できない。そこの考え方を変えてくれという質問をしているので、もう一回答弁をお願いします。","respondent":"中島教育長","answer":"まさに、あと残り半年の中で、教育委員会が全ての子どもたちを集めて何かをするなどということは、先ほどもお話がありましたように、なかなか今、現状としては難しい。しかしながら、それぞれの学校の単位で実施できるものというのは、幾つか出てくるのではないかと考えます。","id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"提案","question":"ぜひよろしくお願いします。そういうことで、各学校もそういうメニューがあれば提案できると思いますので、ぜひそういうところに予算をつけていただいて、集大成の部分で子どもたちに何かの行事をやれる。それはぜひお願いしたいと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/470470?Template=document&Id=1494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":128442,"voices":395}},{"id":"r02-20201016-4","meetingId":"r02-c-settlement","date":"2020年10月16日","dateIso":"2020-10-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤副委員長","kind":"質問・要望","question":"発生が確認されてから約１年が経った今でもいまだに有効とされる治療法は模索中であり、収束の見通しが立つまでウイルスとの戦いを続け、乗り越えていかなければなりません。我々品川区議会自民党は、これまで数回にわたり濱野区長へ緊急政策要望を行い、多くの要望に応えていただきました。併せて、区は今後どういった支援策を行っていくのかも教えていただきたいと思います。","respondent":"久保田地域振興部長","answer":"融資あっ旋「経営変化対策資金２０２０」につきましては、区内中小企業の経営基盤の下支え支援としまして、今年度末までは継続して実施してまいります。次年度につきましては、新型コロナウイルス感染症による経済状況への影響などを考慮し、検討してまいります。","id":"exchange-001"},{"speaker":"湯澤副委員長","kind":"提案","question":"国や東京都でも支援は多く行っておりますが、失業者を出さない、倒産をさせないためにも、可能な限り区独自の支援を引き続き行っていただきたいと思いますので、ぜひご検討をお願いいたします。支援を受けたいと思ってもよく分からないという方がいらっしゃいました。区民により分かりやすいよう、フローチャートやチャットボットの活用を提案いたしますが、ご見解をお知らせください。","respondent":"久保田地域振興部長","answer":"フローチャートやチャットボットの活用につきましては、区の事業でも取入れているものがありますので、引き続き研究してまいりたいと考えているところです。","id":"exchange-002"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"どれだけ役立つ支援でありましても利用されなければ役に立ちませんので、ぜひ支援を必要としている区民に分かりやすく示せるよう努力していただきたいと要望します。ＰＣＲ検査の充実を図るため、会派から要望しておりました品川区ＰＣＲ検査センターが５月１２日に区役所第二駐車場内に設置され、ＰＣＲ検査専門の施設として、病院内での感染リスクの軽減にも役立っていると思います。","respondent":"福内品川区保健所長","answer":"濃厚接触者と判定された場合は、保健所からの連絡に基づきＰＣＲ検査を受けるとともに、検査で陰性であっても感染の可能性が否定できないため、新型コロナウイルス感染症の潜伏期間にあたる１４日間の自宅待機をお願いしています。","id":"exchange-003"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"今お話しいただいたような新型コロナウイルス感染症への新しい取組みについて、区民はどこで情報を確認すればよいのでしょうか。新型コロナウイルス感染症に対する不安から誰かを傷つけてしまったり、命を絶ってしまうケースがあると報告されておりますが、心のケアについても対策があれば教えていただきたいと思います。","respondent":"福内品川区保健所長","answer":"心のケアについては、自殺対策も含め、日頃の普及啓発を継続的に実施していくことが重要と考えています。","id":"exchange-004"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"品川区ＰＣＲ検査センターの設置期間は来年３月までとなっておりますが、収束のめどが立たないような場合には設置の継続を要望したいと思いますが、いかがでしょうか。品川区においても既に１０月１日より、６５歳以上の方は無料で優先的に受けられるとされておりますが、周知は徹底されておりますでしょうか。区民に対する供給量は十分であるとお考えでしょうか。ご見解をお知らせください。","respondent":"福内品川区保健所長","answer":"ＰＣＲ検査センターの継続についてですが、今後につきましても感染状況に応じ、必要な方に必要な検査を迅速に対応できるよう、感染状況や区内の医療機関での検査状況、実施状況等も勘案しつつ、医師会と協議を行ってまいります。","id":"exchange-005"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"義務教育過程におけるオンライン教育について、お尋ねいたします。ＧＩＧＡスクール構想では、当時生徒１人１台の端末配備を２０２３年度中に計画していましたが、文部科学省より新型コロナウイルス感染症緊急経済対策の一環として、２０２０年度中の配備と大きく前倒しすることとなり、我が会派からもタブレットの早期確保、Ｗｉ－Ｆｉ機能の拡充、周辺機器の早期整備を要望してまいりました。","respondent":"齋藤教育次長","answer":"オンライン授業の構想ですが、同時双方向性を最大限活用し、再度の学校休校となった場合でも学びの保障に努めるほか、病気や不登校の児童・生徒に対してもオンデマンドで学習動画を配信するなど、全ての児童・生徒が一人も取り残されることがなく。","id":"exchange-006"},{"speaker":"湯澤副委員長","kind":"質問","question":"推進校や教員同士の会議などで既にＺｏｏｍを活用しているとお聞きしましたが、通信が途切れるなど今後の課題となるような事例はなかったでしょうか。併せて、今月新型コロナウイルス感染症による学年閉鎖をされた学校があり、対象となった生徒たちにはオンライン授業を行ったと伺いましたが、授業は不具合なく行えたのでしょうか、お知らせください。","respondent":"齋藤教育次長","answer":"今後のスケジュールですが、当初６年生・９年生は１２月から、その他の学年は２月中の配付を予定しておりましたが、配送に課題があり、６年生・９年生の配付が年明けになる可能性もあります。９年生には当初の計画どおり配付できるよう調整しています。","id":"exchange-007"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"特に要望の強かった受験を控える９年生、そして６年生などに対して優先的に取組んでいただけたことには本当に感謝申し上げます。Ｚｏｏｍによる様々な課題に関しましてはしっかりと解消し、今後につなげていっていただきたいと思います。オンライン環境についてですけれども、事情によって家庭内の通信環境が整えられない世帯に対して、通信費用を含めた支援を要望いたします。","respondent":"齋藤教育次長","answer":"塾に通うことなく、これまで以上に学習の定着が図れるものと考えております。保護者へのＺｏｏｍの指導ですが、使い方、ルール、トラブル対応のマニュアルを提供して丁寧にご説明するほか、ＺｏｏｍをＰＴＡ活動でご利用いただけるよう、ＰＴＡとの連携を深めてまいります。","id":"exchange-008"},{"speaker":"湯澤副委員長","kind":"質問","question":"新型コロナウイルス感染症により在宅避難を選択し、食料や簡易トイレなどを消費してしまった場合は、どのようにすればよいのでしょうか。し尿などの不衛生なごみはどこに廃棄すればよいのでしょうか。そして、新型コロナウイルス感染症陽性者や経過観察中の方は、避難所に避難をしてよいのでしょうか。それぞれお知らせください。","respondent":"滝澤災害対策担当部長","answer":"避難所の在り方について、ご説明申し上げます。","id":"exchange-009"},{"speaker":"湯澤副委員長","kind":"質問","question":"品川区においてそのような心配はないでしょうか。７年前の本日、大島では台風による甚大な被害がもたらされました。例えば企業、お寺、神社、ホテル・旅館、高校といった耐震性の高い施設の管理者と協定を結び、災害時には避難所として活用させてもらうことも、ウィズコロナ時代の避難所の在り方ではないかと考えますが、区の見解をお知らせください。","respondent":"滝澤災害対策担当部長","answer":"併せまして、帰宅困難者の一時滞在施設として利用する事業者においても避難所として利用できないかということで調整をしておりまして、引き続き避難所の拡大について検討してまいりたいと思います。","id":"exchange-010"},{"speaker":"湯澤副委員長","kind":"質問","question":"ホテルや企業、そしてお寺などともそういった協定を結んでおられるということでありますが、区内には耐震性の高い施設がまだまだたくさんありますので、発災時に避難所難民が出ないように、区民の生命を守る避難所、避難場所の充実に前向きな検討をお願いいたしまして、私からの質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私からは、まず、長期基本計画についてお伺いします。その中で、品川区にとっては長期的な視点による施策の推進も重要な問題であります。長期基本計画が本年４月からスタートしました。品川区基本構想に掲げた「輝く笑顔住み続けたいまちしながわ」に向けて策定されたこの新長期基本計画の特徴と、今後の区政課題について、改めてお伺いをいたします。","respondent":"堀越企画部長","answer":"総論部分を新設いたしまして課題ですとか視点などの大きな考え方を明示するとともに、計画体系といたしまして、区民の生活に根差した分かりやすい政策分野として、地域、人、安全の３つを掲げ、それぞれ連携して取組むことで。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"人口も、今お話がありましたが、ここ２か月品川区は多少減少しております。そのような状況が出てきているし、一方で９月補正によりまして、品川区の予算も約２,５０３億円という大きな金額になってまいりました。通常であれば実施計画に基づいて予算編成をされていくわけですが、実施計画がまだできていない中で、来年度予算に向けてはどのように編成していくのか、その点についてもお聞きしたいと思います。","respondent":"堀越企画部長","answer":"その内容ですが、長期基本計画の実現に向けて、重点的に実施する事業を示すものとして策定したいと考えてございまして、内容については、やはり大きな方向性ですとか有効性等の進捗管理を行いながら推進するものと捉えてあります。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、お話しいただきましたように、方向性の中で災害対策とかオリンピックということが重点項目に出てくると思うのですが、もちろん区内の皆様の生活の安定、この辺を強調した予算を作っていっていただきたいと考えています。その辺について、両面でのお考えを教えてください。","respondent":"堀越企画部長","answer":"長期基本計画と言ってみれば対になっているものというのでしょうか、そういった考え方でやっていきたいと思ってございまして、予定といたしましては、やはりこれも新型コロナウイルス感染症の状況を見ながら実施計画の策定作業をしっかりと再開し。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"来年度に向けてですが、先ほどお話がありましたようにオリンピックという一大イベントもこれから見込まれております。その中で、やはり新型コロナウイルス感染症との戦いというのは区政の最大の関心事になると思います。長期基本計画に関する質問の最後にあたりまして、今後の区政運営に向けて区長のお考えをお聞きしたいと思いますが、いかがでしょうか。","respondent":"濱野区長","answer":"したがいまして、この新しい長期基本計画を着実に推進することが大事なことでありまして、そのためにも限りある財源を最大限に有効活用して、区民が求めておられる大切なサービスを実施していくことが求められていると考えています。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"次の質問に移っていきますが、その施策の中で、まず障害者施策についてお伺いしていきたいと考えています。障害者施策の拠点施設として、昨年１０月に障害児者総合支援施設「ぐるっぽ」が開所しました。改めて障害者施策についての区のお考えと、品川児童学園を障害児者総合支援施設とした目的について、お伺いをいたします。","respondent":"伊崎福祉部長","answer":"そのために、障害者の方のライフステージを通して総合的・継続的な支援を実施し、障害者の方が住み慣れた地域で安心して暮らし続けられるよう、施策を進めているところです。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問","question":"基本方針として、ライフスタイル、総合的・継続的な支援というお話がございました。その辺につきまして、区のお考えをお聞きしたいと思っています。職員の方はいろいろご苦労もあると思うのですが、障害者施策を推進する上で、担当者の方というのはどのように現場を体験しているのか、その点についてもお聞きしたいと思います。","respondent":"伊崎福祉部長","answer":"障害児者総合支援施設は、地域生活支援拠点として、障害児者の地域生活を総合的に支援する機能を持つ圏域での中核となる施設です。区内の事業所との連携を密にして、地域全体の福祉サービスの向上を図ることが重要だと考えております。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"施設関係ですが、以前の委員会とかでもいろいろとお話をお聞きしたし、今のお答えの中にも出てきていたと思うのですが、障害児者総合支援施設は、地域生活支援拠点に求められる機能についての整備・充実を図っていくということで今までお話しいただいております。","respondent":"伊崎福祉部長","answer":"しかしながら、地域生活支援拠点としまして、今後も増え続ける障害者の高齢化・重度化、それから医療的ケアへの対応、親亡き後を見据えた相談支援の充実、緊急時の受入れ対応、専門的人材の育成等の機能を持っていただきたいと考えております。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"新しい指定管理者がこれから選定されるわけですが、今、３つの法人が別々に指定管理を受けている中で、今度は一つの法人になると。ですから、全く新しい法人に変わってしまう、新しい事業者に変わってしまうわけですね。選定にあたりましては、その辺も含めて公平な視点を活かしていっていただきたいと思いますので、その辺の区としてのお考えについてお聞きしたいと思いますが、いかがでしょうか。","respondent":"伊崎福祉部長","answer":"ですので、これから公募するところですが、施設、事業ともに一体的に管理運営ができる体制としてまいります。利用者につきましては、相談から支援まで、総合的・一体的なサービスの提供をできる体制とすることで、より利用しやすい施設になるよう改善を図ってまいります。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"障害者施設の拠点として、例えばボランティアの育成などにも努めていっていただきたいと思うのですが、その辺についてのお考えはいかがでしょうか。この点につきましても強く求めてまいりますが、また医療的ケアという点も進めていっていただきたい、医療面の充実も図っていただきたいと思いますが、この点についてもお考えをお聞きしたいと思います。","respondent":"伊崎福祉部長","answer":"障害児の方の早期発見・早期療育につきましては、引き続き運営事業者等と協議をしながら、改善を図れるよう取組んでまいります。さらに医療的ケアの充実につきましても、施設において医療的ケアの対応ができるよう、運営事業者の支援をしてまいります。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この施設を活用していただいて、障害者施策をどんどん進めていっていただきたいと思いますので、その点も要望させていただきたいと思います。障害者施策の質問の最後にあたりまして、就労支援関係についてお聞きしたいと考えています。一般的に解雇という問題も出ているので一概には言えない問題ですが、品川区の中で障害者の解雇という問題が出ているかどうか、その点についてまず１点教えてください。","respondent":"伊崎福祉部長、榎本総務部長","answer":"今後も就労を希望する障害者の方の就労機会の拡大と定着が図れるよう、障害特性に応じた多様な就労形態を検討するとともに、民間企業に対して障害者の雇用拡大に向けて、障害者理解の促進を進めていく、求めてまいります。今後の方策として、もちろん特別区選考での採用を進めていくのですけれども、それ以外に、今国においてチャレンジ雇用という制度を活用しているものがありまして、その点を研究しながら。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それと、その先のチャレンジ雇用のお話もございましたけれども、品川区でチャレンジした３年間を越えた後の就労先の確保についてのお考えについて、もう一度お答えをお願いしたいと思います。","respondent":"榎本総務部長","answer":"それと、特別区制度の採用は、勤務時間が３８時間４５分と長い採用時間になりますので、それだとちょっと障害者の方の特性を考えると難しいという場合には。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その点を目指して、これからの施策の展開をよろしくお願いしたいと思います。３点目、最後に広町地区のまちづくりについてお伺いしていきたいと考えています。現在の検討状況、また今後のスケジュール感についてお聞きしたいと考えています。特にＪＲ東日本の建築計画に関するスケジュールなども可能な範囲でお答えいただきたいと思いますが、よろしくお願いいたします。","respondent":"末元都市整備推進担当部長","answer":"ＪＲ東日本の建築計画についてですが、具体的な計画はＪＲ東日本の社外秘の情報となるため差し控えしますが、都市計画手続きに必要な地元説明会の開催に加え、建築物の規模によっては環境アセスメントの調査計画書の縦覧や説明会の実施など。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"事業計画は、ＪＲ東日本の問題もありますので、その辺は了解しますが、なるべく早く皆様に周知できるような形をとっていただきたいということを要望しておきます。先日大井町駅周辺地域まちづくり方針の素案が示されましたが、これと広町地区の整備推進の関係、その推進とともに他の地区のまちづくりへの影響についてもお考えをお聞かせください。","respondent":"末元都市整備推進担当部長","answer":"本方針決定後、これを踏まえ、検討が進んでいる広町地区の整備を先行し、その他の大井町駅周辺各地区については、まちづくりの検討熟度に応じて段階的に整備を進めていくものと考えております。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最後に、広場にはバス停も作っていくということですが、その役割分担、大井町駅の東口、西口の関係についてお答えをお願いしたいと思います。","respondent":"末元都市整備推進担当部長","answer":"現在バス路線が大井町駅に入っておりますが、具体的なバス事業者との調整については、今後事業の進捗に応じて協議を進めていく予定です。既存バスの乗り入れですとか、大崎駅からの長距離バス乗り場の可能性も含めて協議してまいります。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"テーマは新型出生前診断における支援について、児童発達支援センターについて、就学相談について、３点を順次伺います。新型出生前診断における支援について伺います。昭和大学病院産婦人科診療科長の関沢明彦教授からは、現在カウンセリングなどを実施していない営利目的のＮＩＰＴ無認可施設が約１３０カ所あると言われているという現状を伺いました。そこでお聞きします。２点お聞かせください。","respondent":"福内品川区保健所長","answer":"保健センターでは、子どもを安心して産み、育てるために、妊婦全員を対象として、妊娠期のネウボラ相談事業を実施しています。相談事業では助産師が中心となり、妊娠中の様々な不安にお答えしています。ハイリスクの妊婦に対しては、保健師が妊娠期から支援にあたっております。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問","question":"委員長の許可を得たので、提示します。こちらのブックレットは、妊娠継続をするときに読んでほしい月編と、赤ちゃんとお別れする選択をするときに知っておいてほしいことが書かれている星編に分かれています。そこで質問します。これらを知る機会は現在区で設けているでしょうか。ですから、妊娠中から子育てまで継続した支援が大切となってきますが、区ではどのように取組んでいくのか、見解を伺います。","respondent":"福内品川区保健所長","answer":"そのため、保健センターではこれまでに助産師、保健師、新生児訪問指導員を対象に、支援者として知っておくべき出生前診断の実際に関する研修を実施しておりまして、今後も様々な機会を活用し、スキルアップを図ってまいります。","id":"exchange-027"},{"speaker":"せお委員","kind":"質問・要望","question":"次に移ります。ですので、現状を確認させていただきたく質問いたします。品川児童学園にて未就学児が児童発達支援を受ける際、基本的な流れとしては、子ども発達相談室で相談をしてから通園などのサービスが開始されると認識しておりますが、その認識でよろしいのでしょうか。さらに、子ども発達相談室の５か月待ちを解消するために、新しく改善を図った点はありますでしょうか。以上３点、お聞かせください。","respondent":"伊崎福祉部長","answer":"困ったときにはいつでも電話で対応する旨をお伝えしております。","id":"exchange-028"},{"speaker":"せお委員","kind":"質問","question":"この点は理解いたしました。現在、基本的な通園の基準は何でしょうか。お聞かせください。ふだんは幼稚園・保育園に通って、空いている曜日や時間で児童発達支援を利用するという形を基本にすべきであって、つまり並行通園が一般的であるべきですが、品川区の見解をお聞かせください。","respondent":"伊崎福祉部長","answer":"区といたしましては、必要な児童に必要な療育が受けられるよう対応していくべきと考えており、運営事業者に対して、並行通園の実施の検討を進めてもらっているところです。","id":"exchange-029"},{"speaker":"せお委員","kind":"質問","question":"次に移ります。最後に就学相談についてお聞きします。この一連の流れは果たして相談なのでしょうか。そこで質問します。さらに、就学相談とはそもそも何をする場所かという説明は、いつどのように行っているのでしょうか。その中で、区立学校の説明だけではなく、都立特別支援学校、こちらは判定で支援学校と言われることもありますので、特別支援学校の説明もされているのか、３点お聞かせください。","respondent":"齋藤教育次長","answer":"就学相談の説明につきましては、次年度に公立学校への入学、進学を控え、通級指導学級の利用や特別支援学級の在籍、または都立特別支援学校への入学を検討したいご家族に対して、必要な情報を６月から区のホームページや広報で掲載してお知らせいたします。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問","question":"そのアンケートの結果を踏まえて、ここから３点質問します。就学先を決定する上での適切な情報提供やご案内はどのようにされていますでしょうか。そして、就学相談中には通常学級や支援学級の見学はもちろんのこと、希望するご家族が必ず体験授業をできるように整え、その案内も必ずすべきだと考えますが、見解をお聞かせください。","respondent":"齋藤教育次長","answer":"情報提供についてのお尋ねですが、まず、心理検査を未実施のお子さんの場合には事前に検査の内容をご案内し、実施後に臨床心理士から結果の説明をいたします。","id":"exchange-031"},{"speaker":"せお委員","kind":"質問","question":"最後にお聞きいたします。さらにアンケートにおいて、「就学相談によって悩みや不安は解消されましたか」の質問には、約１０％の方が「悩みや不安は解消された」、約４０％の方が「解消されてはいないが、自分の悩みは伝えられた」とする一方で、約３５％の方が「悩みや不安が全く解消されなかった」、約１５％の方が「悩みや不安について話をする機会がなかった」と答えています。","respondent":"齋藤教育次長","answer":"お子さんの就学先は最終的には保護者で決定していただくものですので、相談の結果や理由を書面で連絡することはしておりませんでしたが、今後もお子さんやご家族に寄り添った対応の在り方について検討してまいります。","id":"exchange-032"},{"speaker":"せお委員","kind":"意見","question":"今のご答弁にも環境が大きく変わるところだというお話がありましたが、お子さんにとってライフステージが大きく変わる節目の段階であって、小学校に入学する場合は、それが初めて変化を経験する場所かもしれません。だから悩むのです。ご家族の考え方やライフスタイル、状況に寄り添い、子どもが幸せに過ごせる場所を一緒に考えていただけるような就学相談となり、そのような品川区となることを望みます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"渡部副委員長","kind":"質問","question":"せお委員に引き続き、総括質疑を続けます。初めに、本年実施の国勢調査について伺います。今年は５年に一度実施される国勢調査の年で、区民の皆様にご協力いただいているところです。大正９年の第１回調査から数えて２１回、１００年の節目を迎えます。品川区の国勢調査の結果、人口世帯の実績を教えてください。住基人口と国勢調査によって得た結果を比べての違いについてもお聞かせください。","respondent":"久保田地域振興部長","answer":"例えばですが、進学のために上京した学生が、様々な事情により住民票を移していないといったことが考えられるところです。","id":"exchange-034"},{"speaker":"渡部副委員長","kind":"確認","question":"近年は大型マンションへの対応やプライバシー意識の高まりなどがあって、今回に至っては新型コロナウイルス感染症の流行下での調査ということで、調査実施に際し、区も調査員の方も様々な苦労があったのではないでしょうか。調査員の方々からも様々な声は伺いました。今回の国勢調査のボリュームを確認させてください。調査区の数はどのぐらいありましたでしょうか。調査員の確保について伺います。","respondent":"久保田地域振興部長","answer":"調査開始時の実数につきましては、町会・自治会からは１,８５０人、マンション管理会社や管理組合、社会福祉施設からは９０人、区登録調査員が１２２人、公募が４２人となり、このほかに業務委託契約などが１８人いらっしゃいました。","id":"exchange-035"},{"speaker":"渡部副委員長","kind":"質問","question":"町会の皆様に感謝するとともに、大変うれしく思います。さて、ここ数回は調査ごとに変更点があるように思います。前回調査と比較し大きく変わった点や、区として工夫を凝らした点は何かございましたでしょうか。新型コロナウイルス感染症対策で調査員の負担軽減策も大変重要であったと考えますが、どのような対策を取られましたでしょうか、教えてください。","respondent":"久保田地域振興部長","answer":"変更点についてですけれども、今回の国勢調査は大規模調査にあたりまして、前回の調査と比べまして世帯に関する事項が２つ増えてあります。具体的には在学、卒業等の教育状況、就業・通学地までの利用交通機関という項目が増えております。","id":"exchange-036"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"調査員の方に対する対策を相当取られていたということで安心いたしました。これに限らず万全の対策をしっかりと取っていただいて、この取組みを引き続き進めていただくよう要望いたします。調査票による回答数、インターネットによる回答数、未回答数はどのようになっておりますでしょうか。未回答者へのアプローチはどのようになさっているでしょうか、教えてください。","respondent":"久保田地域振興部長","answer":"広報しながわ１０月２１日号や区ホームページにおいても、回答への協力をお願いしたところです。","id":"exchange-037"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"今お伺いしていて、回答率が相当いいようで、この件につきましては安心いたしました。時代の流れでしょうか、インターネット回答というのも前回と比較して伸びているし、次回以降の調査ではさらなる伸びがあるのかと考えています。私自身、この国勢調査というのが国の基幹調査として大変重要であると考えています。最後に、区としてこの国勢調査の大切さや重要な点について教えていただきたいと思います。","respondent":"久保田地域振興部長","answer":"は今回の国勢調査を着実に実施するとともに、国勢調査を含めました各種統計調査を正確かつ確実に進めてまいりたいと考えているところです。","id":"exchange-038"},{"speaker":"渡部副委員長","kind":"質問","question":"いかんせんまだ中途でありますので、引き続き対応をお願いしたいと思います。次の質問に移ります。行政手続のデジタル化について伺います。区ではこの間、様々な業務改善がなされております。ここから２点伺います。１点目は、地方公共団体のデジタル化で示された、システム等の共同利用の推進の観点から伺います。ここで質問しますが、これらの説明は区でいつ頃国からどのように受けましたでしょうか。","respondent":"堀越企画部長","answer":"このデジタル化の推進のいわゆる標準化に関する国からの説明についてですが、これまで国主催の説明会等が開催された実績はございません。全体的なデジタル庁等の考え方というのは、今、国のほうでも検討が進められております。","id":"exchange-039"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"２つ目は、行政手続のオンライン化の推進について伺います。区からは、国のマイナンバーカード管理システムのサーバー増強を強く求めていただきたいとともに、４０万人の人口に見合った台数の登録機を区として設置するよう強く要望いたします。ないようであれば、検討を進められたいと考えますが、いかがでしょうか。そして今後発行できるような可能性があるのか、教えてください。","respondent":"堀越企画部長","answer":"そのシステムですが、今申し上げたリプレイスが今月中に完了する予定でございまして、来年の１月より、コンビニ等で設置されたマルチコピー機において戸籍証明書の取得が可能になるような形で、今、鋭意準備を進めているところです。","id":"exchange-040"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"人事について伺います。新型コロナウイルス感染症による影響、デジタル化により人の手を介さずに行える業務が増えたり、さきのマイナンバーによる行政手続の簡素化、窓口の混雑回避策などによる、今後の人材適正配置について伺います。このような場合に、区役所は急激に業務負担が発生した際の応援体制が組まれているかと思いますが、どのような対応がされましたでしょうか、教えてください。","respondent":"榎本総務部長","answer":"一番多かったのは４月です。その場合の応援態勢ですけれども、新型コロナウイルス感染症の関係で事業等を中止したところがありますので、そういったところで施設を閉じたりとか、そういうところから適宜応援を求めるという形で対応したところです。","id":"exchange-041"},{"speaker":"渡部副委員長","kind":"提案","question":"今も対策を取られていて、これからも様々な対策を取り続けられるということで、何とかこの混雑解消に努めていただきたいと思います。２つ提案します。この２つを提案しますが、お考えをお聞きするとともに、先ほどお話しいただいた混雑解消の観点から、何かそれ以外、区民サービス向上に向けた取組みがもしおありのようであれば、お聞かせください。","respondent":"久保田地域振興部長","answer":"ＬＩＮＥによる事前入力、自動発行機なども取入れまして、これらの混雑解消への取組みを進めてまいりたいと考えております。","id":"exchange-042"},{"speaker":"渡部副委員長","kind":"質問","question":"子育て支援、とりわけ乳幼児をお持ちの家庭への支援について伺います。その結果、一人で抱え込んでしまう方もいらっしゃるのではないでしょうか。ここで乳幼児家庭に対する現在の児童センターの利用状況を伺います。区立学校は通常に戻りましたが、児童・生徒の居場所としての役割も制約があると考えますが、バンドやダンスの活動状況と合わせて利用状況をお教えください。","respondent":"柏原子ども未来部長","answer":"児童センターにおける現在の利用状況等です。最初に、乳幼児の部分ですけれども、コロナ禍におきまして緊急事態宣言解除後ですけれども、６月からチャイルドステーション事業をスタートさせました。","id":"exchange-043"},{"speaker":"渡部副委員長","kind":"質問","question":"大変ですね。ただ、利用したい方も大勢いらっしゃいますので、感染症対策を何とか講じた上で、多くの家庭や児童・生徒が気軽に訪れて活動ができるよう、何か新たなお考え等はないでしょうか。私自身は、公園などを利用した屋外の活動や様々な子育てサークルの方々などを紹介して参加していただく、広げていくなどの必要があるかと考えるのですが、その辺のお考えをお聞かせください。","respondent":"柏原子ども未来部長","answer":"そのほか、子育てサークルというところで、地域のほうで子育てをされている方の交流会というのを来月実施しようというところで検討していますので、そういったところでの交流の場であったり、それぞれの活動の紹介というのはやっていこうと考えていますので。","id":"exchange-044"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"ぜひいろいろと進めていただきたいと思います。今、子育てサークルというようなことでございましたが、このようなボランティア団体の方々についての支援を伺います。品川区には社会福祉協議会の中にボランティアセンターがありますが、子育て支援において、団体とボランティアセンターとの連携事例やその効果などがもしあるようでしたら、教えてください。","respondent":"柏原子ども未来部長","answer":"こちらは区とも連携してやっているところではありますけれども、子ども食堂を運営している団体、事業者との横のつながりであったり、そういった方々と実際ボランティアをやる方とのつながりという広がりができてきておりますので。","id":"exchange-045"},{"speaker":"渡部副委員長","kind":"提案","question":"ここからちょっと提案といいますか要望の形になるのですけれども、区内には様々なボランティア団体というのがあって、在宅子育て支援もそうですが、社会福祉協議会と連携して気軽に参加できるボランティアの仕組みというのを新たに構築されていくのがいいのかと、進めていただきたいと望みます。最後に、教育について伺います。この間の学校教育の状況、また家庭における学習について伺います。","respondent":"齋藤教育次長","answer":"学校休校中の特徴的なことのお尋ねですが、１つ目は、区では入学式、始業式をソーシャルディスタンスを確保しながら実施したことです。","id":"exchange-046"},{"speaker":"渡部副委員長","kind":"確認","question":"何かあった場合は、引き続きよろしくお願いいたします。長い休みの中で、個人の学力差が出たのではないかと心配しています。各家庭での取組みに学校が介入することはなかなかできませんが、実際の状況はいかがだったのでしょうか。学校再開後、学力低下が確認できた児童・生徒に対しては、何かしらのアクションが学校でなされていたのかどうか、教えていただけますか。","respondent":"齋藤教育次長","answer":"ただ、学校再開後に回収した課題や学校再開後の確認テストで学力に課題が見られた児童・生徒には、放課後で個別に指導したり、品川地域未来塾で学習支援をするなど、きめ細かく対応したところです。","id":"exchange-047"},{"speaker":"渡部副委員長","kind":"質問","question":"再開後すぐ定着度調査をされているというのはすばらしいことだと思います。今後ガイドライン等を作成して運用につかれると思いますが、幾つか伺います。この間のＩＣＴの推進校での取組みを全校で継続すべきと考えますが、教育委員会としてのお考えをお聞かせください。とりわけ先ほどもありましたが低学年が家庭で活用するには保護者の助けが必要になってしまうと思いますが、併せてお聞かせください。","respondent":"齋藤教育次長","answer":"教育委員会といたしましては、保護者に使い方、ルール、トラブル対応のマニュアルを提供するほか、連絡帳機能やＰＴＡ活動でご利用いただけるよう丁寧に説明いたします。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問","question":"品川区議会公明党を代表して、塚本よしひろ委員とともに総括質疑を行います。大きく防災とワンストップ窓口について伺います。初めに、風水害と地震がコロナ禍で発生した場合の避難について伺います。昨年の台風１９号で、品川区は自主避難施設を開設しましたが、地震時の避難所である区民避難所へ避難された方がいました。現在までどのように区民への周知が図られたのかお知らせください。","respondent":"滝澤災害対策担当部長","answer":"昨年の台風において課題となりました自主避難施設の区民への周知要領についてですが、昨年度の防災会議において、自主避難施設の定義や役割をお伝えし議論するとともに、区ホームページや広報しながわなどを活用して、避難要領に係る周知・啓発を実施してまいりました。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"ただいま３つの避難所があるということのご説明がありました。しかし、まだまだ区民には周知が足りないと感じております。そこで、自主避難施設、避難場所、避難所とは何かを分かりやすく掲載した冊子やリーフレットなどを作成し、配布することを要望いたしますが、見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"検討内容が整い次第、変更を伴う際は、冊子の作成を含めてあらゆる手段を講じて区民に対し周知徹底を図ってまいります。","id":"exchange-050"},{"speaker":"新妻委員","kind":"提案","question":"どうぞよろしくお願いいたします。先日の款別審査の土木費でも会派から確認いたしましたが、昨年は１８７万円、本年は４８０万円を予算化しています。そこで、公明党が平成３０年第３回定例会の一般質問で提案している、区が指定している目黒川の氾濫や土砂災害による対象区域において、地震とは別に浸水、高潮、土砂災害を想定した避難訓練の実施を改めて提案いたしますが、それぞれ見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"要支援者以外を対象とした訓練につきましては、先ほど説明をしました区民目線で分かりやすい避難要領の研究と併せて、広域化する風水害避難のための訓練要領について、その実施要領を具体化してまいります。","id":"exchange-051"},{"speaker":"新妻委員","kind":"提案","question":"それぞれ継続してお願いしたいと思います。次に、マイ・タイムラインについて伺います。新たな生活様式の中でもマイ・タイムラインの周知啓発に努めていただきたいと要望します。そこで、品川区公式ＬＩＮＥの中にある防災についてのコーナーに、マイ・タイムラインを作成できるサイトの東京マイ・タイムラインを分かりやすく掲載することを提案いたします。見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"しながわ防災学校においては、今年度、風水害対応における家庭・区民コースにおいて、マイ・タイムラインの作成を実施予定でありましたが、新型コロナウイルス感染症の影響で中止となりました。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問","question":"いち早く対応していただければと思います。次に、避難所について伺います。公明党は、８月に地震の際に避難する区民避難所の視察で御殿山小学校を訪問しました。定期的に行う訓練は防災意識を維持、高めるために重要であり、コロナ禍だからこそ防災訓練を行う必要があると考えます。ウィズコロナ時代の新たな避難所運営を行う地域の声をどう受止め、対応しているのか伺います。","respondent":"滝澤災害対策担当部長","answer":"共助による避難所運営の負担を軽減するために、症状のある避難者など、感染の恐れの高い避難所エリアの運営については、区の職員が実施することを基本に考えており、区の職員に対しては防護服の着脱を含めた感染防止のための訓練を庁内で実施しております。","id":"exchange-053"},{"speaker":"新妻委員","kind":"提案","question":"品川区においても、しながわ防災体験館で３密を避けるための避難所のイメージを展示するなどの検討をされてはいかがでしょうか。そして、コロナ禍に関するマニュアルの実効性が高くなるよう、防災区民組織や区民がコロナ禍の避難所をイメージできるような動画を作成し、ホームページへの公開や防災体験館での活用を提案いたします。併せて見解を伺います。","respondent":"滝澤災害対策担当部長","answer":"動画の作成についてですが、新型コロナウイルス感染症に対応する避難所訓練を１２月の区内一斉防災訓練で区民避難所において実施する予定でありますので、訓練の実施要領を踏まえて、その際に動画を作成することの可能性についても検討してまいります。","id":"exchange-054"},{"speaker":"新妻委員","kind":"意見","question":"タブレットにつきましては、ぜひ活用をお願いしたいと思います。９月初旬の台風１０号の発生に伴い、九州地方では親戚や知人宅に加えて、ホテル宿泊で避難する人が多くいました。災害社会工学を専門とし、「釜石の奇跡」で著名な東京大学の片田敏孝特任教授は、コロナ禍における厳重な警戒が呼び掛けられた台風１０号は、住民が避難所以外の選択肢を考えるきっかけになったと言われています。","respondent":"滝澤災害対策担当部長","answer":"区と都の役割としては、区が具体的な宿泊や食事支援の協定を締結する一方、都は利用可能なホテル情報の提供や利用のための相互調整支援を実施するものであります。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"ホテルの活用も有効かと思いますので、また一層の拡充に取組んでいただきたいと思います。ここ数年のそれぞれの利用実績をお知らせいただき、それぞれの利用状況の課題をどう捉えているのか伺います。そして、安心して在宅避難ができるよう、家具転倒防止器具取付助成の対象者拡充や、希望する方へ食器類の飛び出しを防止する器具などの無償提供を求めますが、いかがでしょうか。","respondent":"中村都市環境部長、伊崎福祉部長、滝澤災害対策担当部長","answer":"本事業の実績ですけれども、平成２９年度が２件、平成３０年度が３件、令和元年度が１件となっております。一層のＰＲが課題であると認識しています。周知方法につきましては、広報紙やホームページなどでお知らせをしているところですが、まだまだ行き渡っておりませんので。在宅避難の有効性は、近年クローズアップしてきており、また一方で、区民の居住環境は様々ありますことから、在宅避難を進める上で。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問","question":"在宅避難をするため、家庭内での被災をしないという取組み、今後も一層よろしくお願いしたいと思います。次に、行政サービスのワンストップ窓口、書かない窓口についてです。款別審査でも伺いましたが、証明交付窓口のリニューアルをした目的と評価、そして課題をお知らせください。このことによって区民の利便性の向上と負担軽減がどのようにされるのか伺います。","respondent":"久保田地域振興部長","answer":"評価としましては、複数の証明書を一度に取得する場合に、申請書に何度も同じことを書かなくて済むということが挙げられます。課題としましては、知られていないということがありまして、利用頻度が１日に数件程度ということで、さらなる周知が必要であると考えています。","id":"exchange-057"},{"speaker":"新妻委員","kind":"意見","question":"ＬＩＮＥのサービスがこれから始まると思います。周知も課題ですが、このＬＩＮＥの事業が始まるにあたっての周知、何かお考えがありましたらお知らせください。","respondent":"久保田地域振興部長","answer":"それ以外にも、区ホームページの手続きページやチャットボット経由での紹介など、あらゆる手段を使いまして周知を図っていきたいと考えています。","id":"exchange-058"},{"speaker":"新妻委員","kind":"提案","question":"伺います。平成２９年予算特別委員会の総括質疑で、私は別府市のおくやみコーナーを紹介し、品川区でも導入をと提案した経緯がありますが、現庁舎において手続きに不慣れな外国人や高齢者の負担を軽減する、また子育て世帯の転入の際には、子どもの申請などに係る手続きの簡素化など、書かない窓口の設置を要望いたします。それぞれ見解を伺います。","respondent":"堀越企画部長","answer":"今後、様々な先行自治体の例も参考にさせていただきながら、現庁舎で対応できる部分というような形にはなりますけれども、具体的な方法について様々検討していきたいと考えているところです。","id":"exchange-059"},{"speaker":"新妻委員","kind":"質問・要望","question":"現庁舎での行政サービスの向上をもう一歩要望いたしまして、私の総括質疑を終わります。塚本委員に引き継ぎます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"区議会公明党を代表して、新妻委員に引き続き、総括質疑を行います。初めに、新型コロナウイルス感染症のＰＣＲ検査について質問します。ＰＣＲ検査の受皿が拡大される中、検査のありようについては様々な意見があります。加えて、行政検査とスクリーニング検査について、感染拡大を最小化するために、それぞれの検査をどのような方針で実施することが効果的であると考えているか伺います。","respondent":"福内品川区保健所長","answer":"スクリーニング検査につきましても、地域や施設の感染状況も踏まえ実施することが効果的と考えております。","id":"exchange-061"},{"speaker":"塚本委員","kind":"質問・要望","question":"区の保健所では、高齢者施設や学校で陽性者が出た場合、今ご説明があったとおり、濃厚接触の範囲を超えて積極的にＰＣＲ検査を実施し、感染拡大防止に努めています。その現状について、区はどのように認識しているか伺います。東京都への要請や各種医療機関への働きかけなど、あらゆる手を尽くして医師免許を持つ職員を確保するよう求めます。区の見解を伺います。","respondent":"福内品川区保健所長、榎本総務部長","answer":"対象が１００名近くなど多い場合は、非常勤医師の活用も含め、２チームの編成が必要となります。保健所の所長以外の医師は保健予防課長１名のため、管理職業務等の合間や休日に対応しており、迅速性の担保が課題となっております。医師の確保の関係です。品川区における医師不足につきましては、十分認識しており、これまでも東京都へ要望してきたところです。今回、新型コロナウイルス感染症への対応にあたり、その必要性をこれまで以上に認識したところであります。","id":"exchange-062"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の医師不足というか、庁内のＰＣＲ検査は待ったなしの中で、医師の不足ということでの体制確保へのご答弁、総務部長のほうからいただいたということは、ひとつ私としても評価したいというか、品川区保健所だけの問題ではなくて、ＰＣＲ検査体制の行政検査の整備の推進というか強化は全庁的にやっていただきたい部分であるというふうに思っておりますので、今、品川区は、今日のデータで見ると。","respondent":"伊崎福祉部長","answer":"受診後に専門医療機関や区の支援策に適切につながるような認知症ケアパスの仕組みも考えてまいります。さらに、家族、地域へのフォロー体制としましては、認知症カフェをご案内するなど、適切な対応に努めてまいります。","id":"exchange-063"},{"speaker":"塚本委員","kind":"意見","question":"今、６５歳以上に対しての検査というか、行っていただくというご答弁をいただきました。来年度、迅速にというか、スムーズにこれをスタートできるように、ぜひこの事業の推進をよろしくお願いしたいと思います。令和元年度の区の施設整備の状況を見ると、地域密着型サービス施設等整備費助成は１億４,４７９万円余の決算となっていて、着実に整備を進めていると、このように認識しております。","respondent":"伊崎福祉部長","answer":"重度の方につきましては、認知症デイサービスなどをご利用いただくなど、認知症になっても在宅生活を継続できるよう、サービスの提供に努めてまいります。","id":"exchange-064"},{"speaker":"塚本委員","kind":"提案","question":"認知症ケアを一層充実させるため、在宅介護支援センターにある総合相談窓口で伴走型で相談者に常に寄り添い、所管をまたぐ様々な相談に応じることができるよう、窓口機能を充実すること、また、地方の施設や遠隔地にいる当事者と家族をつなぐＩＣＴ等の活用、そして支える家族同士の情報交換や悩みを共有するコミュニティの構築、こういったことを提案いたしますが、区の見解を伺います。","respondent":"伊崎福祉部長","answer":"複雑化、多様化する相談に対応するため、在宅介護支援センターや支え愛・ほっとステーションなど、現在ある様々な相談機能を踏まえた上で、重層的な支援体制整備に向けて総合的な相談窓口機能の検討を進めてまいります。","id":"exchange-065"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ認知症施策の一層の推進をお願いいたしまして、次の質問に移りたいと思います。新型コロナウイルス感染症を想定した新しい生活様式が求められる中、日本社会のデジタル化の後れが顕在化しました。商店街についてです。区は、五反田バレーと商店街の連携も進める中で、ポストコロナを見据えた商店街のにぎわい創出や運営効率化について、デジタル活用による施策をどのように展開するのか見解を伺います。","respondent":"久保田地域振興部長","answer":"しかしながら、商店街では、ＩＴを活用することについての情報が不足しているといった現状がございまして、こうした課題を解決するために、ＩＴツールの試験導入や、また五反田バレーとの連携も進めまして、商店街のにぎわいや運営の効率化を図るためにも。","id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"教育についてです。品川区は、第２回定例会で成立した補正予算で、学習用タブレット端末２万４,０００台の予算を計上しました。次に、機器の操作などの支援にはＩＣＴ支援員が配置されますが、品川区の教育要領に基づいた単元の中で、一人ひとりに個別最適化された学習を行うためには、授業の組み立て方など、教員の大きな意識改革が必要と考えますが、区の認識を伺います。区の見解を伺います。","respondent":"齋藤教育次長","answer":"授業での活用状況を学校評価に加えることで、十分に検証を図りつつ、活用を推進してまいります。ＩＣＴ推進教員への支援についてのお尋ねですが、各学校では、ＩＣＴ推進教員と学年主任を中心に活用検討組織を立ち上げ、教職員の意欲とスキルアップを図ることを目指しております。","id":"exchange-067"},{"speaker":"塚本委員","kind":"質問・要望","question":"来年度になるかと思いますが、ぜひ、各学校が同じようにスタートを切れるよう進めていっていただきたいと思います。次に、医療のオンライン化についてです。区は、医療のオンライン化についてどのように考えているのか、見解を伺います。さらに、医療のオンライン化について、区内の医療機関から要望などがあった場合、区として支援の考えがあるか伺います。","respondent":"福内健康推進部長","answer":"今般、初回診療時からのオンライン診療の恒久化について検討が進められており、日本医師会からは、安全性と信頼性を確保するため、かかりつけ医が関わるなど、医師と患者の面識があることを前提にすべきとの考えが示されております。","id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"行政のデジタル化が求められておりますが、そのためには、なりすましを防止する確かな個人認証システムが必要です。今後、行政機関の個人認証システムは、マイナンバーカードに集約するべきと考えますが、区の認識を伺います。区として今後の行政サービスのデジタル化に伴い、マイナンバーカードと東京電子自治体共同運営サービスをどのように整理していくのか伺います。","respondent":"堀越企画部長","answer":"個人認証の関係等ですけれども、区も行政手続のオンライン化は積極的に進めていきたいというふうに考えているところです。その上で、やはりなりすましの防止、セキュリティ対策をしっかりと構築していかなければならないと思ってあります。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"デジタル・ディバイド解消のため、例えば品川区のほぼ全域に張り巡らされている品川ケーブルテレビの通信インフラを活用して、難しい技術を単純な操作で使えるよう、情報弱者の立場に合わせたインターネット環境の提供など、思い切った施策を検討していただきたいのですが、区の見解を伺います。そのために、権限と実効性のある体制をつくり、全庁的な検討を開始するよう求めます。区の見解を伺います。","respondent":"堀越企画部長","answer":"今ご質問いただいていますＩＴツールを活用した形でのワンストップを図っていくという点。それから最後に、やはり各部、職員がしっかりと連携して対応していくというような多角的な視点からしっかりと検討に努めていきたい、このように考えているところです。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"コロナ禍を乗り越えた先に品川区が先進的なオンライン・シティとなることを願い、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"どうぞよろしくお願いいたします。私からは、この３月末から本格運用が始まり、区民の暮らしを大きく変えている羽田新飛行ルートについて質問いたします。騒音の問題です。このような受止めでいいのでしょうか。７７.１デシベル、７９デシベルという騒音は、住民にとってあまりにもうるさい騒音です。想像していた以上にうるさい。そこで伺います。いかがでしょうか。これもいかがでしょうか。伺います。","respondent":"中村都市環境部長","answer":"現在までに電話やメールなど様々な方法で区民の皆様から影響についてご意見をいただいておりまして、これも国に伝えているところです。引き続き、区としまして、区民の皆さんの意見をしっかりと聞き、区民の立場に立って国に対し必要な対応を求めてまいるという考えです。","id":"exchange-072"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひ寄り添った対応をしていただきたいと思います。２０１８年にＷＨＯは環境騒音ガイドラインを改定して、航空機騒音について、人の健康を守るために、１日平均の騒音指標の１つであるＬｄｅｎを４５デシベル以下にすることを強く勧告いたしました。そこで伺います。品川区では、騒音測定において、このＬｄｅｎの値をなぜ出さないのでしょうか。出すべきではないでしょうか。伺います。","respondent":"中村都市環境部長","answer":"Ｌｄｅｎですけれども、健康の保護に資する基準というところで、年間Ｌｄｅｎによって判断されるものですけれども、区では、現在、騒音の最高値、発生回数等を公表しております。ただ、Ｌｄｅｎにつきましても、今後、年間Ｌｄｅｎについて公表を予定しております。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"Ｌｄｅｎの値、区民の健康という非常に重要な要素に関するものです。ぜひ積極的に取入れていっていただきたいと思います。地域からも驚きと不安の声が上がっております。そこで伺います。そして、受けていなかったのなら、区も区民も全く知らされてこなかった重大な事実が新たに判明したわけですから、国に即刻運用中止と、改めて説明の場を設けさせるべきだと思いますけれども、いかがでしょうか。伺います。","respondent":"中村都市環境部長","answer":"自衛隊輸送機が飛行したですけれども、新飛行ルートの事前の説明では、飛ぶとも飛ばないとも説明はなかったという認識です。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問","question":"事前に説明を受けなかった以上、やはり全く新しい事態が展開しているわけです。民間機と自衛隊機は全く違うものを運びますし、違う飛行機が飛ぶわけです。全く新しい事態が展開した以上、新しい事態の展開として少なくとも説明の場は設けさせるべきだと考えますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"おくの委員","kind":"質問・要望","question":"新しい事態に対する新しい説明、強く求めていただきたいと思います。新ルートの固定化回避を掲げる検討会が、結局、新ルートの固定化を招くという問題について伺いたいと思います。２番目、そうであるなら、この検討会は、区民にとって新ルートの固定化ということではないでしょうか。３番目、やはり中止またはルートの変更を国に求めるべきだと思うのですが、いかがでしょうか。以上３点、伺います。","respondent":"中村都市環境部長","answer":"ただ、この国が行う検討については、先ほども申し上げました区民の負担を可能な限り軽減していただく、こういった方向性で取組んでいただくというところは、区としてぶれずに結果を注視していきたいというふうに考えております。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、今のご答弁からも、区としてもこの固定化回避は現在の都心ルートを前提にしたものであると。次にいきます。伺います。品川区の住民に、新ルートへの賛否を聞かれたことが一度でもあったでしょうか。いかがでしょうか。それからもう１つ、最後に伺います。区として、住民投票を求める住民運動をどのように受止めていますか。伺います。","respondent":"中村都市環境部長","answer":"区も同席しましたけれども、国からの直接の回答による活発な質疑応答が行われたと記憶をしています。条例制定に向けた署名運動につきましては、自治法上も認められた権利ですので、区としましても法令に基づき厳正に対応してまいりたいと考えております。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問・要望","question":"結局、この条例制定運動も地元の理解を得て進めると国自らが言いながら、地元の理解を得られないまま進めた点から、こういう自体に立ち至ったと。新ルートへの賛否を聞かれたことが結局は一度もなかったという事態から生じたことだと私は思います。新ルートによって区民は日々の暮らしとその環境を壊され、また、健康も蝕まれております。新ルートの中止、撤回、強く求めて私の総括質疑を終えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"続きまして、日本共産党の総括質疑を行います。感染拡大を抑えるためのＰＣＲ等検査の抜本拡充と、深刻な経済危機から区民の暮らしを守る対策を求めて質問します。それから、品川区のＰＣＲ検査体制について伺います。ＰＣＲ検査センター、帰国者・接触者外来での１日のＰＣＲ検査可能数、医師会を通じて東京都と契約しているＰＣＲ検査可能な医療機関の数と、そこでの検査可能数をそれぞれ教えてください。","respondent":"福内品川区保健所長","answer":"４月、７月、８月、９月、１０月の感染者数、ＰＣＲ検査数、陽性率です。４月は、感染者数１３９人、検査数５１３件で、陽性率２７.１％です。７月は、感染者数２３３人、検査数２,６４１件、陽性率８.８％。８月は、感染者数２７０人、検査数４,７１９件、陽性率５.７％。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この抜本拡充こそ必要だと思います。さらに、９月１５日、厚生労働省からインフルエンザの流行に備え、検査体制の拡充に向けた指針が出され、検査体制の点検と強化が求められています。これからの検査需要の見込み、ＰＣＲ検査の検体採取対応力について、現状での１日の件数と、ピーク時、１日何件まで引き上げる計画か、そのための体制整備をどうつくっていくのか、相談体制はどう拡充するのか伺います。","respondent":"福内品川区保健所長","answer":"今後も増加の見込みがありますので、先ほど申し上げました１日で３２６件程度の検査は可能ではないかというふうに考えてあります。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひこれを区が活用して、高齢者、基礎疾患のある希望者へのＰＣＲ検査を実施するよう求めます。いかがでしょうか。この要請に沿って検査の拡充を求めます。いかがでしょうか。いかがでしょうか。以上、３点の実施について、お答えいただきたいと思います。新型コロナウイルス感染症地方創生臨時交付金は、品川区に幾ら出されているのか、どう活用されているのか、今述べた対策に活用できるのか伺います。","respondent":"品川財政課長、伊崎福祉部長、福内品川区保健所長","answer":"委員のご質問にありますＰＣＲ検査等につきましては、地方創生臨時交付金の対象におおむねなるというふうには考えておりますが。区といたしましては、委員ご指摘の介護サービス事業者等のＰＣＲ検査の実施に向けて、今、作業を進めているところでございまして、こういった手段を講じて。今後も感染状況等に応じて確実に検査を実施してまいります。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高齢者と基礎疾患のある人を対象に、国庫補助を行うという通知は、１か月前の９月１５日に出ているのです。１か月前に出ているものに対して、１か月間、このことに対して検討してこなかったのでしょうか。何よりも高齢者と基礎疾患のある人は、かなり幅広くなります。大変意味のあることだと思いますが、区は、この高齢者と基礎疾患のある人への検査に対して、必要な検査とは考えないのか伺います。","respondent":"福内品川区保健所長","answer":"ただ、検査を実施するにあたっては、やはり効果的に実施する、また、感染の疑いがある方たちからきちんと検査を行い、また、場合によっては対象をそこから広げて検査をしていくことが望ましいというふうに考えてあります。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、この６５歳以上の高齢者と、基礎疾患を有する者に国庫補助を行うと、ここまで出しているわけですから、この検査をやっていただきたい。これを検討しなかったのか、そしてこれを必要だと思わないのかを伺ったので、そのことについて答弁をお願いします。","respondent":"福内品川区保健所長","answer":"品川区の場合は、現在、高齢者の方は家族からの感染、または施設の中での感染ということが見られておりますので、現時点では、そのような状況を踏まえて、施設等、または家族の中で。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"非常に残念です。ここまで国が出しているわけですから。改めてＰＣＲ検査等の拡充を強く求めます。次に、保健所体制の拡充について伺います。この間、長時間労働や仕事の緊張など、多大なストレスだったのではないでしょうか。もともと保健師は、人口対比の定数が２３区で最低の人数であり、共産党は定員増を求め続けてきました。区として保健師の正規職員の大幅増員を求めますが、いかがでしょうか。","respondent":"榎本総務部長","answer":"ストレスチェックにつきましては、９月に全職員に実施しておりまして、その中で、今、検診機関のほうで集計をしているところで、１１月には各個人に報告書を通知する予定です。その結果によりまして、産業医の面談、本人であったり上司を通じての面談などを行う予定です。","id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"区がこの状況をどう捉え、どのような対策が必要と考えるか伺います。さらに具体的に伺います。東京都並みの２倍に額を引き上げること、３か月の期間を国並みの６か月に引き上げることを提案します。さらに区独自の収入が５割減、また３割減が３か月という厳しい要件を緩和することを求めますが、いかがでしょうか。１回限りの給付ではなく、持続的支援を国に求めていただきたいが、いかがでしょうか。","respondent":"榎本総務部長、久保田地域振興部長","answer":"そのほかいろいろな業務量を考えて、この間、増員をしてきているところです。今後も適正な仕事の執行ができるように人員をきちんと配分しながら仕事を進めていきたいと考えています。家賃支援給付金についてですが、これらの要件につきましては、経営状況が特に厳しい事業者に迅速な支給を実施するものと考えておりまして、審査を極力簡略化し、迅速な給付をするという観点から。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"保健師は、ぜひ定数として増やしていただきたいと思います。続きまして提案ですけれども、住居確保給付金、緊急小口資金・総合支援資金は、多くの人が活用し救われています。支給された人数をそれぞれ教えてください。給付期間延長を国に求めてください。いかがでしょうか。港区のように、品川区でも大学生、専門学生に対する給付型奨学金制度の創設を改めて求めます。いかがでしょうか。","respondent":"伊崎福祉部長、柏原子ども未来部長","answer":"住宅確保給付金および緊急小口資金・総合支援資金の期間の延長につきましては、国において議論をされるものと認識しておりますので、状況を注視してまいります。こちらの問題に関しまして、進学はもちろんそうですが、高校生が途中で退学した場合に、その後の就職であったり、様々な影響がある、これはかなり大きな影響があるということで、大学生のそういった部分との比較において。","id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はコロナ禍による区民の苦境に心を寄せた対応をお願いしたいと思います。しかし、まだまだ不十分です。ＰＣＲ検査、医療体制の拡充、暮らし、営業を守る支援の取組みを求めます。ＪＲ開発のために進める庁舎の建て替え、８００億円もの税金を投入する巨大道路づくり、こうした税金の使い方は見直し、コロナ禍から区民の命と暮らしを守るために充てるよう求め、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"新型コロナウイルス感染症問題の影響で、倒産、休・廃業や解散は５万件、解雇、雇い止め、自宅待機などの失業者と休業者は数百万人いて、その大半の収入がゼロになり、生活費や家賃に回すお金がなくなっていて様々な援助を受けています。１つ目、区内の中小・零細企業の経営の現状をどのように把握していますか。そして、倒産、廃業、休業、解散などをした企業数を把握していたら教えてください。","respondent":"久保田地域振興部長","answer":"区内中小企業の現状ですけれども、このコロナ禍の中で経営は大変厳しい状況になっているというふうに私どもも認識しています。倒産、廃業の件数ですけれども、廃業についての区内の状況はつかみ切れていないところです。","id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"今、地域経済と社会活動の崩壊が始まっていると思います。この新型コロナウイルス感染症による影響は、非常事態であり、そして異常事態ではありませんか。ならば、区内産業の経営状況を、調査、把握するべきだと思いますが、再度教えてください。確かに倒産は減っていますが、廃業、休業等の会社が多数あるように聞いております。もう一度ご見解をお聞かせください。","respondent":"久保田地域振興部長","answer":"廃業につきましての数値ですけれども、品川区ということではございませんが、全国の場合ですと、昨年が約４万件ほど、それに対して今年は、たしか５万件を超えて６万件近くいくのではないかという見込みが出ているということは把握しています。","id":"exchange-089"},{"speaker":"須貝委員","kind":"質問","question":"この新型コロナウイルス感染症問題から起きていることは、今までの不景気とは全く異質です。大企業であれ、日本の基幹産業であれ、対処が難しく、いつ倒産や廃業を迎えてもおかしくないという状況にあります。違いますか。これについてもう一度ご見解をお聞かせください。休業する。そして、何か対策をお考えですか。教えてください。そして失業者が増え、貧困層が増えると思いますが、教えてください。","respondent":"久保田地域振興部長","answer":"これらの対策に加えまして、企業のほうの様々な経営相談に乗るということも大事なことでございまして、社労士等を活用した相談窓口の設置、また、国や東京都の助成金の相談窓口の開設をはじめ、そういった企業や雇用を維持できるような形の支援も継続的に進めているところです。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"でも、いずれ返さなくてはいけない。別にご商売をやっている方にいくわけではなく、そして消費にしても、やはり品川区民の中の本当に一部ですから、これが景気回復または地域振興、仕事をやっている皆さんのために、ゼロとは言いませんがそんなに貢献しているとは思いません。今、相談ではないのではないですか。今は何とかして企業を存続させるということを第一に考えるべきではないかと思います。","respondent":"久保田地域振興部長","answer":"屋形船等の支援に加えて、他の業界へというお話もございましたけれども、まずは大きな痛手を負いました屋形船のところに支援をさせていただいて、その後、状況等を見ながら、必要に応じて他の業種等につきましても検討を進めていきたいと考えております。","id":"exchange-091"},{"speaker":"須貝委員","kind":"提案","question":"今、経営相談もやって、これから皆さんがどうやっていったらいいのだということを、区としても力を入れてやっていくと。第二には、今もう難しいなら転業を考えられたらどうですかとか、そういうことも１つの提案だと思います。私は、何とかその方たちにお金が回るようにやっていただきたいと思います。そして次にいきます。教えてください。そして、今後、区はどのような対応をお考えなのかお聞かせください。","respondent":"品川財政課長","answer":"今後の対策としましては、既存事業の見直しも進めまして、優先順位をしっかりと見極めながら、必要な事業をしっかりと進めていきまして、引き続き、計画的で健全な財政運営を行ってまいりたいと考えております。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つは、しながわ水族館の廃止です。品川区の近くにはＪＲの駅前に２つの水族館があります。近くに民間の水族館がこれだけできているならば、ましてアクセスがいい水族館が２つもあるならば、もう民間でできることは民間に任せるべきだと思いますが、お答えください。そして２つ目は、ふるさと納税対策です。今では約２４億円の税収減で、渋谷区のように返礼品競争を本格的にやるべきではないかと思います。","respondent":"藤田防災まちづくり部長、榎本総務部長","answer":"しながわ水族館ですけれども、宿場町として栄えていた品川区として、昭和５０年代に埋立て等がかなり進んでいく中で、区として東京湾の資料や生物を紹介する資料館の計画案がまず立案されまして、その後、昭和６０年代に入りまして。その中で国がいろいろと制度を変えてきまして、地方に有利なルールづくりというか、そういう基準を作ってきました。その中で品川区は、平成２７年度から返礼品を考えてふるさと納税に着手してまいりました。","id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"お金に余裕があってやっているわけではないのです。そういうことを考えたら、もう転換しなければいけないのではないかと思いますが、もう一度ご見解をお聞かせください。でも、今はそれは終わったのではないですか。周りにこれだけ民間でできるところがある。ましてアクセスが全然違う。現に来場者が少しずつ減っているならば、もう転換する時期だと思いますが、もう一度ご見解をお聞かせください。","respondent":"榎本総務部長、藤田防災まちづくり部長","answer":"そういった仕組みになっておりますので、今現在そういう形で流出する元というのは、ちょっと言いづらいですが、区内の高額所得者の方が地方へ寄附すると、その部分の区の税金が外へ流れるという、そういう仕組みになっていますので。入館者数が減少してきていることは確かにそのとおりですけれども、現在、私どもも顧客満足度満点プロジェクトということで、来てもらえるお客様にぜひとも満足をしていただけるような仕組みも改めて検討しています。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問・要望","question":"個別にお聞きします。ですから、高齢者には社会活動に参加していただき、心身ともに元気な生活を続けていただきたいものと思いますが、ご見解を教えてください。そして、シルバーセンターやほっと・サロンでは、カラオケやマージャンなどの教室や様々なサークルなどがありますが、感染対策を工夫した上で、使用制限を解除したらどうでしょうか。お答えください。","respondent":"伊崎福祉部長","answer":"しかしながら、様々なところで再開をしている先例もありますので、そういったものを参考にしながら、区の中でどうやって活かしていったらいいのか検討してまいりたいと思います。","id":"exchange-095"},{"speaker":"須貝委員","kind":"質問・要望","question":"避難場所には、赤ちゃんから高齢者まで大勢の区民が殺到しますが、健康な方のほかに、様々な持病や病気をお持ちの方、インフルエンザや新型コロナウイルス感染症の感染者などを収容できるスペースはあるのですか。収容能力を超えた場合は入場制限をするのですか。混乱時ですが対応できるのですか。狭いところに大勢入るわけですから、二次感染、三次感染を防ぐことは可能なのですか。教えてください。","respondent":"滝澤災害対策担当部長","answer":"その場合には、そのエリアを閉鎖するとか、必要であれば、体育館に入っているものをホテルを借り上げて全て個室にして、そこで一時、２週間なり管理をするとか、そのときの状況に応じて。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、これは本当に難しい問題だと思います。今回、新型コロナウイルス感染症問題が出て初めて、やっぱりこれは怖いなと私も思ったので、避難計画の見直しと避難所の見直しをしていただきたいと思うのですが、そこら辺はご検討しているのでしょうか。お知らせください。","respondent":"滝澤災害対策担当部長","answer":"現在、新型コロナウイルス感染症に伴いまして、避難所のマニュアルの改定を行いながら、いかに避難所の運営を支援するかについては検討しております。最終的に、新型コロナウイルス感染症に伴う災害対策計画の修正についてまでは検討している範囲ではございません。","id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"多くの生徒は、家族をはじめ、日常生活で習い事やスポーツクラブなど、様々な人と接触しております。教えてください。そして、今ご答弁がありましたが、学校は感染拡大を防止するより、風評被害を優先するということですか。教えてください。","respondent":"齋藤教育次長","answer":"保健予防課長に先頭に立っていただき、日曜や平日、夜間にも最も精度の高いＰＣＲ検査を実施していただきました。検査にあたっては、行動履歴の把握や関係者に丁寧な聞き取りを行っております。その上で、検査対象者を絞り込んでいました。","id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"今、校庭を使用している、学校施設を使用している団体の保護者が、校庭内で練習等を見学することを禁止されている学校がありますが、感染リスクが少ない校庭での見学はなぜ駄目なのですか。教えてください。見学を了承している学校もありますが、なぜ対応が分かれているのですか。この辺についてもご見解をお聞かせください。","respondent":"齋藤教育次長","answer":"学校での感染リスク、学校からの感染リスク、こういった疫学的判断は保健所の知見によることが重要であると考えておりますので、保健所と連携を図りつつ情報提供を図ってまいります。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり教育委員会として、学校を束ねている、指導しているのですから、私はやはり１つの指針が必要だと思います。なぜ外で駄目なのか、これは親御さんも分からない。教室とか体育館、校舎内は分かりますが、やはりその辺はしっかりとしたご見解をしていただきたいと思います。以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問","question":"全庁的な障害者への合理的配慮に関しての質問をいたします。これです。この編集の所管は障害者福祉課になっているので、改訂の都度、障害者福祉課から発信、配付がされていると考えてよろしいでしょうか。各所管では、このハンドブックを受止め、どのように職員で共有し、活用の方法を徹底しているのか、研修などもあったほうがいいと思うのですけれども、その辺の活用について伺います。","respondent":"伊崎福祉部長","answer":"各部の取組みといたしましては、障害者差別解消法や職員ハンドブックの内容にのっとり、庁内ルールの周知徹底をしております。情報発信では、音声コードへの対応を行う、窓口では必要な備品を配備するなど、各部の業務内容に応じて合理的配慮を行っているところです。","id":"exchange-101"},{"speaker":"吉田委員","kind":"確認","question":"発信だけではなく、この実施についても福祉部が統括的に行っているというふうな理解でよろしいでしょうか。それから、併せて２１ページの貸出用用品について伺います。款別審査のときには、たしか５０台用意されていると伺いましたが、貸出システムについて伺います。どのように利用されているのでしょうか。窓口でタブレットが使えることの表示、案内はどのようにあるのか、それぞれの所管について伺います。","respondent":"伊崎福祉部長、堀越企画部長","answer":"ハンドブックに記載されている内容につきましては、常に障害者福祉課として見直しを行っておりますので、近年の様々な対応にそぐわないところがございましたら、修正をしていきたいと考えております。関係団体につきましては障害者福祉課のほうで対応していますので、全庁的に連携して対応をしていきたいと思ってあります。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"タブレットですけれども、情報推進課に５０台あるということなのでしょうか。総合案内も大分表示が変わってきてよくなったと思うのですけれども、ちょっと分かりにくいかと、総合案内、表示はありますけれども、分かりにくいかと思いますが、見解を伺いたいと思います。次に、２３ページの統一ルールの中の手話通訳者派遣・要約筆記者派遣について伺います。なぜでしょうか。この点について見解を伺います。","respondent":"伊崎福祉部長、堀越企画部長","answer":"手話通訳につきましては、合理的配慮の提供という部分になってくるかと思うのですが、国の基本指針、あるいは障害者差別解消法におきましても、合理的配慮の提供は、その事業を行うにあたり。周知については、今、福祉部長が申し上げましたとおり、我々としても全庁的に庁内周知に努めてまいりたいと考えています。","id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"タブレットですけれども、どこに置かれているかが分からないということだと思います。併せて、これは要望ですが、説明会や講演会でパワーポイントを使う場合、視覚障害者の方には、パワーポイントに何が表示されているのかの説明をサポートすることが必要です。これらの配慮も今後実施してほしいと思いますが、見解を伺います。事前広報への明記も同様に考えますが、見解を伺います。","respondent":"伊崎福祉部長","answer":"手話通訳につきましては、先ほども申し上げましたが、本来、合理的配慮の考え方として、お申し出があればということではありますが、お申し出いただくということができるように、そのご案内はしていきたいと考えております。","id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。款別審査の際、新型コロナウイルス感染症の検査で陽性となった場合は、原則入院、軽症の場合は施設で隔離ということを改めて確認しました。自宅ならともかく、初めての場所ではサポートが必須です。あらかじめ想定しておきたいと考えるのは当然ではないでしょうか。障害者福祉課だけの判断では難しいと考えますが、しかるべき担当部署としてお答えいただきたいと思います。","respondent":"伊崎福祉部長、福内品川区保健所長","answer":"障害のある方に関する新型コロナウイルス感染症の検査のお話かと受止めました。検査につきましては……。検査で陽性になった後の隔離につきましては、障害のある方それぞれの特性がありますので。軽症者については、施設、ホテルに入所していただくですが、やはり様々なご事情があって、それが難しいという方については、こちらも事情をよくお聞きし。","id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのことを質問が出たときに答えていただきたいと思います。時間がないので次にいきます。最初に、騒音被害の問題について伺います。品川・生活者ネットワークとしても、当然、国の責任で行うべきと考えていますが、区としてそれを国にどのように主張しているのでしょうか。国はどう回答しているのか伺います。国が動くまで区民を守る立場から区が実施すべきと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"新ルートの説明会でも同様の声がありまして、国の回答としましては、これまで事例がなく、調査は予定していないという回答でございましたけれども、やはり区としましては、こうした情報を得た場合には、しっかりと国に伝え、そして対応を求めていくというのは。","id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろと求めていらっしゃることは承知しております。それは時間が経ってしまいますので、ぜひ国がその責任をちゃんと果たすまで、区民を守る立場から区が実施すべきと考えて見解を伺いました。その点について伺います。ぜひ検討すべきと考えますが、見解を伺います。落下物の目撃情報があったときは、少なくとも国としてきちんと調査はされるべきと考えますが、区としての見解を伺います。","respondent":"中村都市環境部長","answer":"万が一、落下物が発生した場合には、国が責任を持ち調査を行い、航空事業者とともに対応にあたるといったことを確認しています。事業の停止ですけれども、発生時の対応といたしまして、まずは速やかな原因究明が一番最初に行うべき重要なものであるというふうに考えております。","id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、被害があったら、本当に当然で、区も一緒にその原因を区民の立場に立って、国の責任、それから事業者の責任を求めていっていただきたいと思います。この点も区として国に求めるべきと考えます。そのことについて、品川区は、そのようなプレッシャーをかけるようなことはないと信じておりますので、区民の立場に立って国に求めていただきたいと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"こうした役割を担う国土交通省が厳正に行うべきと考えておりますので、区としましても、それをしっかりと注視して、適切な措置が行われるように求めてまいります。","id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ公正に行っていただきたいと思います。ただ、先ほどご紹介いたしました事例、やっぱり事業にとって都合が悪い調査はプレッシャーがかかるのです。それを区民は心配しております。ぜひ区民の立場に立っていただきたいと主張して、私の総括質疑を終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"令和元年度は、普通会計の実質収支が約５１億円の黒字となり、経常収支比率は７５.７％、人件費比率は１３.６％と健全財政を維持していることを評価いたします。そして、基金残高も１,０００億円超を維持しております。コロナ禍の中ではありますが、引き続き、区民の福祉・生活の維持向上に努められることを要望いたします。何点か、ここで取上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"大沢委員","kind":"提案","question":"普通会計の実質収支は５１億円の黒字。経常収支比率は７５.７％、人件費比率は１３.６％であり、引き続き健全財政が維持された区政運営が行われている、以上の状況を確認いたしました。本委員会で会派所属の各委員が発言した指摘や提案が今後の事業遂行に十分に反映され、予算編成をはじめとする区政運営が、区民福祉の一層の向上に寄与することを強く求め、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"若林委員","kind":"提案","question":"区民サービスにおいては、公明党の提案を含めた取組みを積極的に展開しました。今後は、本委員会総括質疑で我が会派が取上げたコロナ禍のＰＣＲ検査、防災や認知症対策、ＩＣＴ等を活用した区民サービスの向上策、款別審査での指摘、提案など、また、これまでの緊急要望や予算要望を十分に検討され、今後の区政運営および来年度予算へ反映されるよう求めます。最後に、来年度予算について意見を述べます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"安藤委員","kind":"提案","question":"以下、反対の理由を述べます。区内家賃支援給付金、販路拡大助成金は対象の拡大、１回で終わらせず継続的な給付など、事業者の実態をつかみ、さらなる支援の制度設計と実施を、また、持続化給付金、住居確保給付金、緊急小口・総合支援資金の延長を国に要請することを求めます。国に給付額の引上げを求め、区も認める「生活保護は権利」との文言を明記し、受けるべき方が受けられるよう制度の周知を求めます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"本年度も歳入増に恵まれ、収支は５１億円の黒字となり、健全財政を維持しています。政府、日銀の財政金融政策で、資金繰り倒産は抑制されていますが、このまま社会活動や消費活動の停滞が続けば、廃業が増大し、さらに多くの失業者と貧困層が増えてしまうので、企業が存続できる支援をしていただきたい。そして、羽田飛行ルートの固定化を避けるために、これからも国に働きかけていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"以下、何点か意見と要望を述べます。款別審査では、まだ制度的に完全に整っていないことが伺えました。今後、議会としての決算審査の質の向上のためにも、区民への説明責任のためにも、制度整備を求めます。障害者差別解消法が施行され４年が経ちます。各款別審査で指摘、提案させていただいた意見を予算編成に活かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/470470?Template=document&Id=1496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":108517,"voices":267}},{"id":"r02-20201021-10","meetingId":"r02-cm10","date":"2020年10月21日","dateIso":"2020-10-21","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"議会報告会等準備会議からの報告事項","agenda":"議会報告会等準備会議からの報告事項","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"議会報告会等準備会議より、品川女子学院生徒との意見交換会の実施についてご報告申し上げます。ちなみにテーマは、１つは満員電車の問題、２つ目に音楽によるストレス解消、３つ目に効果的な勉強方法、４つ目に鍵（パスワードなどを含む）について、５つ目に通学時の荷物の重さ解決、最後６つ目は、自己紹介についてというテーマです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"議長からの報告について","agenda":"議長からの報告について","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"この資料で、初めて知ったのですけれども、今のご説明で、議会に親しんでいただくことが目的で、議運のメンバーにご協力を仰ぐということなのですけれども、議会というのはいろいろと多様性もあるので、少数会派の方々を、メンバーの選定に当たっては、そういった方々に、こういうのがありますということを含めて、議会全体で選出していくことも必要なのではないかと私は思うのですけれども。","respondent":"渡辺議長","answer":"その辺は大切なポイントかと承知しています。昨年の実績をもとに、昨年正副議長で対応して、参加する先方の都合といいますか、先方の人数や割り当てられた時間、質疑の時間から、経験をもとにまず適正な人数を想定しました。そして、いろいろな会議体があります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"まだやり始めたばかりということもありますし、先方からのオファーの時期もあると思うので、検討の時間とかもあると思うのですけれども、試みとしてはすごく大事なものだと思いますので、少し時間をかけて、必要な会議体、議運なのか、議会報告等準備会議なのか分かりませんけれども、そういったところを使いながら、場を活かしながら、丁寧な対応については今後議論をしていただければという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5380#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":8817,"voices":37}}]);
